import{n as a}from"./shared-CAKwAg2C.js";const o={"LEARN HOW THE INTERNET WORKS":"TÌM HIỂU CÁCH INTERNET HOẠT ĐỘNG","NOW LEARNING":"ĐANG HỌC","OSI LAYER":"TẦNG OSI","LEARNING PROGRESS":"TIẾN ĐỘ HỌC",COMPLETE:"HOÀN THÀNH","IN PROGRESS":"ĐANG DỞ","{pct}% complete":"Đã hoàn thành {pct}%","DESIGNED BY":"THIẾT KẾ BỞI","Dilum Sanjaya on X":"Dilum Sanjaya trên X","Layer {n}: {name}":"Tầng {n}: {name}",Physical:"Vật lý","Data Link":"Liên kết dữ liệu",Network:"Mạng",Transport:"Giao vận",Session:"Phiên",Presentation:"Trình diễn",Application:"Ứng dụng","OVERVIEW · {n} STEPS":"TỔNG QUAN · {n} BƯỚC","STEP {n}/{total} · {title}":"BƯỚC {n}/{total} · {title}","LESSON COMPLETE":"ĐÃ XONG BÀI HỌC",PROTOCOLS:"GIAO THỨC",Protocols:"Giao thức",Language:"Ngôn ngữ",Theme:"Giao diện","Light mode":"Chế độ sáng","Dark mode":"Chế độ tối","INTERNET PROTOCOLS":"CÁC GIAO THỨC INTERNET","Close the protocol list":"Đóng danh sách giao thức","Close (Esc)":"Đóng (Esc)",ALL:"TẤT CẢ",CORE:"CƠ BẢN",APPLICATION:"ỨNG DỤNG",SECURITY:"BẢO MẬT",NETWORK:"MẠNG",SEQUENCE:"TRÌNH TỰ",View:"Chế độ xem","Switch view (V)":"Đổi chế độ xem (V)","Network diagram":"Sơ đồ mạng","Sequence diagram":"Sơ đồ trình tự","STEP {n}":"BƯỚC {n}","PROTOCOL OVERVIEW":"TỔNG QUAN GIAO THỨC","STEP DETAILS":"CHI TIẾT BƯỚC","LESSON SUMMARY":"TÓM TẮT BÀI HỌC",OVERVIEW:"TỔNG QUAN",ACTIVE:"ĐANG MỞ","STEP {n} OF {total}":"BƯỚC {n}/{total}","PACKET {n} OF {total}":"GÓI {n}/{total}","PACKETS {from}–{to} OF {total}":"GÓI {from}–{to}/{total}","{n} LOST":"MẤT {n}","1 LOST":"MẤT 1",ENCRYPTED:"ĐÃ MÃ HÓA","LOST ON THE WAY":"BỊ MẤT TRÊN ĐƯỜNG","PACKET FLOW":"LUỒNG GÓI TIN","Colour key":"Chú thích màu","Playback speed":"Tốc độ phát","Previous step (←)":"Bước trước (←)","Previous step":"Bước trước","Play / pause (Space)":"Phát / tạm dừng (phím cách)",PLAY:"PHÁT",PAUSE:"TẠM DỪNG",REPLAY:"XEM LẠI",STEP:"BƯỚC","One packet at a time":"Từng gói một",RESET:"ĐẶT LẠI",Reset:"Đặt lại","Back to the overview (Esc)":"Quay lại tổng quan (Esc)","NO.":"STT",TIME:"THỜI GIAN",SOURCE:"NGUỒN",DESTINATION:"ĐÍCH",PROTOCOL:"GIAO THỨC",INFO:"THÔNG TIN",SIZE:"KÍCH THƯỚC","No packets on the wire yet.":"Chưa có gói tin nào trên đường truyền.",LOST:"MẤT","Packet inspector":"Trình kiểm tra gói tin","Previous packet":"Gói trước","Previous packet (←)":"Gói trước (←)","Next packet":"Gói sau","Next packet (→)":"Gói sau (→)",Close:"Đóng","E.G.":"VD.","an example value: it differs in every real capture":"giá trị ví dụ: mỗi lần bắt gói thật đều khác","bytes the lesson can’t show: encrypted, random, or a file’s contents":"các byte bài học không thể hiển thị: đã mã hóa, ngẫu nhiên hoặc nội dung của một tệp",BYTES:"BYTE","{n} in this frame":"{n} trong khung này","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Hàng này đại diện cho {n} đoạn TCP mang một thông điệp {size} byte; đang hiển thị đoạn đầu tiên","This packet was lost on the way":"Gói tin này đã bị mất trên đường",Padding:"Phần đệm","One packet at a time (S)":"Từng gói một (S)","KEYBOARD SHORTCUTS":"PHÍM TẮT","Press {key} any time to see these again.":"Nhấn {key} bất cứ lúc nào để xem lại.","Search protocols":"Tìm giao thức","Search protocols and steps":"Tìm giao thức và bước","Nothing matches.":"Không có kết quả.","to move":"để di chuyển","to open":"để mở","Protocol list":"Danh sách giao thức","Diagram only":"Chỉ sơ đồ",Fullscreen:"Toàn màn hình","Keyboard shortcuts":"Phím tắt",Playback:"Phát lại","Hide the protocol list (L)":"Ẩn danh sách giao thức (L)","Diagram only (D)":"Chỉ sơ đồ (D)","Fullscreen (F)":"Toàn màn hình (F)","Keyboard shortcuts (?)":"Phím tắt (?)","Show the protocol list (L)":"Hiện danh sách giao thức (L)","Show all panels (D)":"Hiện tất cả các bảng (D)","Exit fullscreen (F)":"Thoát toàn màn hình (F)","Play or pause":"Phát hoặc tạm dừng","Next step":"Bước sau","Go to step 1 to 9":"Đến bước 1 đến 9","Slower, faster":"Chậm hơn, nhanh hơn","Back to the overview":"Quay lại tổng quan","Network or sequence view":"Xem mạng hoặc trình tự","Show or hide the protocol list":"Hiện hoặc ẩn danh sách giao thức","Light or dark theme":"Giao diện sáng hoặc tối",Find:"Tìm","Next or previous protocol":"Giao thức sau hoặc trước","These shortcuts":"Các phím tắt này","Previous or next packet":"Gói trước hoặc sau","Close it":"Đóng lại"},s={"Hypertext Transfer Protocol":"Hypertext Transfer Protocol","HTTP Secure":"HTTP bảo mật","Transmission Control Protocol":"Transmission Control Protocol","User Datagram Protocol":"User Datagram Protocol","Internet Protocol":"Internet Protocol","Domain Name System":"Domain Name System","Dynamic Host Configuration":"Cấu hình máy chủ động","Internet Control Message":"Thông điệp điều khiển Internet","Simple Mail Transfer Protocol":"Simple Mail Transfer Protocol","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Truy cập thư trên Internet","File Transfer Protocol":"File Transfer Protocol","Secure Shell":"Secure Shell","Transport Layer Security":"Transport Layer Security",Internet:"Internet",Client:"Máy khách",Router:"Router","DNS Resolver":"Bộ phân giải DNS","Web Server":"Máy chủ web","Root Server":"Máy chủ gốc",".com TLD Server":"Máy chủ TLD .com","Authoritative Server":"Máy chủ có thẩm quyền","Mail Server":"Máy chủ thư",".com Server":"Máy chủ .com",Authoritative:"Có thẩm quyền",Server:"Máy chủ","Web Communication":"Giao tiếp trên web",Request:"Yêu cầu",Response:"Phản hồi","Data ACKs not shown":"Không hiện ACK của dữ liệu","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP là giao thức của web: máy khách yêu cầu một tài nguyên, chẳng hạn một trang HTML, và máy chủ trả lời bằng một mã trạng thái, các tiêu đề và thường là một phần thân. Mỗi lần trao đổi là một yêu cầu và một phản hồi, viết bằng văn bản dễ đọc trong HTTP/1.1.",Layer:"Tầng","Application (Layer 7)":"Ứng dụng (tầng 7)","Default Port":"Cổng mặc định","Data Format":"Định dạng dữ liệu","Text (headers + optional body)":"Văn bản (tiêu đề + phần thân tùy chọn)","Common Methods":"Phương thức thường gặp","Defined In":"Định nghĩa trong","Page delivered":"Đã giao trang","One request, one response":"Một yêu cầu, một phản hồi","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Trong chưa đến một phần mười giây, laptop đã tra một địa chỉ, mở một kết nối TCP và trao đổi một yêu cầu và phản hồi HTTP, tất cả đều ai trên đường đi cũng đọc được. Nhấn XEM LẠI để xem lại.","Round trips":"Lượt khứ hồi","Total time":"Tổng thời gian","Page size":"Kích thước trang","Sent as 9 TCP segments":"Gửi thành 9 đoạn TCP","Client Request":"Yêu cầu của máy khách","Browser prepares the request":"Trình duyệt chuẩn bị yêu cầu","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Bạn mở http://www.example.com. Trình duyệt sẽ gửi một yêu cầu GET, nhưng gói tin đi tới địa chỉ IP chứ không phải tên, nên trước hết nó cần địa chỉ của máy chủ. (Ngày nay trình duyệt thử https:// trước; đây là bản không mã hóa.)",Method:"Phương thức","Next hop":"Chặng kế tiếp","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"Phân giải DNS","Finds the server’s IP address":"Tìm địa chỉ IP của máy chủ","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Laptop hỏi máy chủ DNS mà DHCP đã cấp cho nó, 8.8.8.8, địa chỉ của www.example.com. Câu hỏi đi qua UDP cổng 53 và câu trả lời là một bản ghi A chứa địa chỉ IPv4. (Trên mạng có IPv6 nó còn hỏi cả bản ghi AAAA.)",Resolver:"Bộ phân giải","8.8.8.8 (had it cached)":"8.8.8.8 (đã có trong bộ nhớ đệm)","UDP, port 53":"UDP, cổng 53",Answer:"Trả lời","DNS QUERY":"TRUY VẤN DNS","DNS REPLY":"TRẢ LỜI DNS","TCP Connection":"Kết nối TCP","Establishes a reliable link":"Thiết lập một liên kết tin cậy","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP chạy trên TCP. Trước khi bất kỳ dữ liệu trang nào được gửi, laptop và máy chủ mở một kết nối tới cổng 80 bằng bắt tay ba bước: SYN, SYN-ACK, ACK.","Server port":"Cổng máy chủ","Client port":"Cổng máy khách",Handshake:"Bắt tay","HTTP Exchange":"Trao đổi HTTP","Request and response messages":"Thông điệp yêu cầu và phản hồi","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Trình duyệt gửi một yêu cầu GET có tiêu đề Host. Máy chủ trả lời 200 OK với HTML trong phần thân: 12.2 KB, quá lớn cho một gói, nên TCP chia thành 9 đoạn tối đa 1460 byte (ở đây vẽ thành một).",Status:"Trạng thái",Body:"Phần thân","text/html, 12.2 KB":"text/html, 12.2 KB","Sent as":"Gửi thành","12.2 KB in 9 segments":"12.2 KB trong 9 đoạn","Page Rendering":"Hiển thị trang","Browser displays the content":"Trình duyệt hiển thị nội dung","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Trình duyệt phân tích HTML và vẽ trang. CSS, hình ảnh và script được liên kết sẽ mỗi thứ khởi động thêm yêu cầu giống như thế này, dùng lại kết nối đang mở khi có thể.",Document:"Tài liệu",Connection:"Kết nối","Kept open for reuse":"Giữ mở để dùng lại","Seen on the laptop’s home network":"Thấy trên mạng gia đình của laptop",Destination:"Đích","The router: anything beyond the home network goes to it first.":"Router: mọi thứ ra ngoài mạng gia đình đều đi qua nó trước.",Source:"Nguồn","The laptop’s network card.":"Card mạng của laptop.",Type:"Loại","What the frame carries.":"Khung này mang gì.","Version, header length":"Phiên bản, độ dài tiêu đề","4, 20 bytes":"4, 20 byte","IPv4, with no options.":"IPv4, không có tùy chọn.","Priority and congestion marks; 0 means ordinary traffic.":"Mức ưu tiên và dấu tắc nghẽn; 0 nghĩa là lưu lượng bình thường.","Total length":"Tổng độ dài","This header and everything inside it.":"Tiêu đề này và mọi thứ bên trong.",Identification:"Định danh","Lets the receiver reassemble the pieces if the packet gets split.":"Giúp bên nhận ghép lại các mảnh nếu gói bị chia nhỏ.",Flags:"Cờ",none:"không có","Routers may split it if a link is too small.":"Router có thể chia nhỏ nó nếu một liên kết quá nhỏ.","Time to live":"Thời gian sống","Windows starts at 128.":"Windows bắt đầu từ 128.",Protocol:"Giao thức","Header checksum":"Checksum tiêu đề","Covers this header only; every router recomputes it after lowering the TTL.":"Chỉ bao phủ tiêu đề này; mỗi router tính lại nó sau khi giảm TTL.","Source port":"Cổng nguồn","Destination port":"Cổng đích",Length:"Độ dài","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Tiêu đề UDP và dữ liệu. UDP chỉ có vậy: không đánh số, không xác nhận.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Bao phủ tiêu đề, dữ liệu và các địa chỉ IP.","Transaction ID":"ID giao dịch","Picked at random; the answer must carry the same one.":"Chọn ngẫu nhiên; câu trả lời phải mang đúng ID đó.","0x0100: query, RD (recursion desired)":"0x0100: truy vấn, RD (yêu cầu đệ quy)",Questions:"Câu hỏi",Answers:"Câu trả lời","Authority records":"Bản ghi thẩm quyền","Additional records":"Bản ghi bổ sung",Question:"Câu hỏi","www.example.com, type A, class IN":"www.example.com, loại A, lớp IN","The laptop.":"Laptop.","The router’s side facing the home network.":"Phía router hướng vào mạng gia đình.","Started at 128; 10 routers on the way each took 1.":"Bắt đầu từ 128; 10 router trên đường mỗi cái trừ 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: phản hồi, RD (yêu cầu đệ quy), RA (có hỗ trợ đệ quy)","DF (don’t fragment)":"DF (không phân mảnh)","Routers must not split it; if it’s too big they report back instead.":"Router không được chia nhỏ nó; nếu quá lớn, chúng sẽ báo ngược lại.","Picked by the laptop’s system for this connection.":"Do hệ thống của laptop chọn cho kết nối này.","Sequence number":"Số thứ tự","This side’s starting number. Shown as 0; the real one is random.":"Số bắt đầu của phía này. Hiện là 0; số thật là ngẫu nhiên.","Real sequence number":"Số thứ tự thực",Acknowledgment:"Xác nhận","0 (not used yet)":"0 (chưa dùng)","A first SYN has nothing to acknowledge.":"SYN đầu tiên chưa có gì để xác nhận.","Header length":"Độ dài tiêu đề","20 bytes, plus 12 of options.":"20 byte, cộng 12 byte tùy chọn.",Window:"Cửa sổ","How much more data this side can take right now.":"Phía này còn nhận thêm được bao nhiêu dữ liệu ngay lúc này.","Covers the header, the data and the IP addresses, so damage is caught.":"Bao phủ tiêu đề, dữ liệu và các địa chỉ IP, nên hư hỏng sẽ bị phát hiện.","Urgent pointer":"Con trỏ khẩn",Options:"Tùy chọn","Maximum segment size":"Kích thước đoạn tối đa","The most data this side wants in one segment.":"Lượng dữ liệu lớn nhất phía này muốn trong một đoạn.","Spacing, so the next option lines up.":"Đệm, để tùy chọn tiếp theo thẳng hàng.","Window scale":"Hệ số cửa sổ","Window values are multiplied by this, so windows can be larger than 64 KB.":"Giá trị cửa sổ được nhân với số này, nên cửa sổ có thể lớn hơn 64 KB.","SACK permitted":"Cho phép SACK",yes:"có","This side understands selective acknowledgements.":"Phía này hiểu xác nhận chọn lọc.","Started at 64; 12 routers on the way each took 1.":"Bắt đầu từ 64; 12 router trên đường mỗi cái trừ 1.","The next byte this side expects: everything before it has arrived.":"Byte tiếp theo phía này chờ: mọi thứ trước nó đã đến.","Position of this segment’s first byte, counted from this side’s SYN.":"Vị trí byte đầu tiên của đoạn này, tính từ SYN của phía này.","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 byte)","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Khung Ethernet dài ít nhất 60 byte (64 byte kèm checksum do card thêm vào), nên khung ngắn được đệm thêm.",Text:"Văn bản","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 byte)","covers bytes not shown here":"bao phủ các byte không hiện ở đây","12,500 bytes: the HTML page":"12,500 byte: trang HTML","The page itself; its contents are not part of the lesson.":"Chính trang đó; nội dung của nó không thuộc bài học.","Secure Web":"Web bảo mật","TLS handshake":"Bắt tay TLS","HTTP request":"Yêu cầu HTTP","HTTP response":"Phản hồi HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS là HTTP gửi qua một kết nối TLS được mã hóa. TLS chứng minh máy chủ đúng là ai nó tự nhận bằng một chứng chỉ, thỏa thuận khóa mã hóa mới, rồi bảo vệ mọi yêu cầu và phản hồi khỏi bị đọc hay sửa trên đường đi.","Application (HTTP over TLS)":"Ứng dụng (HTTP qua TLS)",Security:"Bảo mật","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 vẫn phổ biến)",Proves:"Chứng minh","Server identity (certificate)":"Danh tính máy chủ (chứng chỉ)","Secure page delivered":"Đã giao trang bảo mật","Encrypted, except the lookup":"Đã mã hóa, trừ bước tra cứu","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Trình duyệt tra địa chỉ bằng DNS thường, mở một kết nối TCP, kiểm tra chứng chỉ của máy chủ và thỏa thuận khóa trong một lượt khứ hồi. Mọi byte HTTP sau đó đều đi dưới dạng mã hóa. Nhấn XEM LẠI để xem lại.",Cipher:"Bộ mã hóa","Still visible":"Vẫn thấy được","IPs, server name, sizes":"IP, tên máy chủ, kích thước","Secure Request":"Yêu cầu bảo mật","Browser asks for https://":"Trình duyệt yêu cầu https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Bạn gõ https://www.example.com. Chữ “s” bảo trình duyệt bảo vệ kết nối bằng TLS, mặc định trên cổng 443. Trước khi kết nối được, nó vẫn phải tìm địa chỉ IP của máy chủ.",Port:"Cổng","DNS Lookup":"Tra cứu DNS","Same lookup as HTTP, not encrypted":"Tra cứu như HTTP, không mã hóa","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Bước tra cứu giống hệt với HTTP thường: một truy vấn tới 8.8.8.8 qua UDP cổng 53. Nó không được mã hóa, nên ai trên đường đi cũng thấy bạn hỏi tên nào, trừ khi trình duyệt dùng DNS over HTTPS.",Encrypted:"Mã hóa","No (plain DNS)":"Không (DNS thường)","TCP Handshake":"Bắt tay TCP","Opens a connection to port 443":"Mở kết nối tới cổng 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS chạy trên TCP, nên vẫn là bắt tay ba bước trước tiên, lần này tới cổng 443. Chưa có gì được mã hóa.","TLS Handshake":"Bắt tay TLS","Agrees on keys, checks the certificate":"Thỏa thuận khóa, kiểm tra chứng chỉ","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Trình duyệt đưa ra các bộ mã hóa và phần khóa, gồm cả một kiểu lai hậu lượng tử. Máy chủ chọn kiểu đó và gửi phần của mình, rồi gửi chứng chỉ, lúc này đã được mã hóa. Trình duyệt kiểm tra nó với các tổ chức mà nó tin cậy.",Version:"Phiên bản","Key exchange":"Trao đổi khóa","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (lai)","Server name":"Tên máy chủ","Sent in clear (SNI)":"Gửi dạng rõ (SNI)","key shares: hybrid + x25519":"phần khóa: lai + x25519","cipher: AES_128_GCM_SHA256":"bộ mã hóa: AES_128_GCM_SHA256","then encrypted: cert, Finished":"rồi mã hóa: cert, Finished","CERTIFICATE VALID":"CHỨNG CHỈ HỢP LỆ","handshake complete (encrypted)":"bắt tay xong (đã mã hóa)","Encrypted Exchange":"Trao đổi đã mã hóa","HTTP inside TLS records":"HTTP bên trong bản ghi TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET và 200 OK vẫn là các thông điệp HTTP như trước, được niêm phong trong bản ghi TLS mà trên đường truyền trông như “dữ liệu ứng dụng” ngẫu nhiên. Máy chủ còn gửi hai vé phiên, để lần truy cập sau có thể bỏ qua một phần bắt tay.",Inside:"Bên trong","GET / and 200 OK":"GET / và 200 OK",Tickets:"Vé","2, for faster reconnects":"2, để kết nối lại nhanh hơn","APP DATA":"DỮ LIỆU ỨNG DỤNG","inside: GET / HTTP/1.1":"bên trong: GET / HTTP/1.1","outside: encrypted bytes":"bên ngoài: byte đã mã hóa","inside: HTTP/1.1 200 OK":"bên trong: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"bên ngoài: 12.9 KB, 9 đoạn","Browser shows the padlock":"Trình duyệt hiện ổ khóa","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Trình duyệt giải mã phản hồi, vẽ trang và hiện một ổ khóa: kết nối là riêng tư và máy chủ đã chứng minh danh tính. Tiêu đề Strict-Transport-Security bảo nó từ nay dùng HTTPS cho trang này.",Remembers:"Ghi nhớ","HTTPS only (HSTS), 1 year":"Chỉ HTTPS (HSTS), 1 năm","Server Hello + encrypted handshake, 3 segments":"Server Hello + bắt tay đã mã hóa, 3 đoạn","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (đã mã hóa)","Application Data (HTTP request)":"Application Data (yêu cầu HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (đã mã hóa)","Application Data (HTTP response), 9 segments":"Application Data (phản hồi HTTP), 9 đoạn",Record:"Bản ghi","Content type":"Loại nội dung","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Bản ghi của Client Hello ghi TLS 1.0 để các thiết bị trung gian cũ cho qua; các phiên bản thật được đưa ra bên trong.","Handshake type":"Loại bắt tay",Contents:"Nội dung","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Mọi thứ trình duyệt hỗ trợ. Trình duyệt thay đổi vài chi tiết giữa các kết nối.","Server name (SNI)":"Tên máy chủ (SNI)","Versions offered":"Phiên bản đề xuất","Key shares":"Phần khóa","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 byte), X25519","App protocols (ALPN)":"Giao thức ứng dụng (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Bản ghi TLS 1.3 ghi 1.2 ở bên ngoài, để tương thích.","The server’s choices and its half of the hybrid key exchange.":"Các lựa chọn của máy chủ và nửa phần của nó trong trao đổi khóa lai.","Cipher suite":"Bộ mã hóa","Key share":"Phần khóa","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 byte)","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Không có vai trò gì trong TLS 1.3; được gửi để thiết bị trung gian thấy một kiểu bắt tay quen thuộc.","Every encrypted record says Application Data on the outside; the real type is inside.":"Mọi bản ghi mã hóa đều ghi Application Data ở bên ngoài; loại thật nằm bên trong.","Encrypted data":"Dữ liệu đã mã hóa","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Bản mã, kết thúc bằng một thẻ 16 byte để lộ mọi thay đổi. Chỉ hai đầu mới đọc được.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (chuỗi chứng chỉ), Certificate Verify (chữ ký), Finished","Finished: a check value over the whole handshake":"Finished: giá trị kiểm tra trên toàn bộ quá trình bắt tay","The HTTP request":"Yêu cầu HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: cho phép lần truy cập sau tiếp tục phiên","The HTTP response, then the 12,500-byte page":"Phản hồi HTTP, rồi đến trang 12,500 byte","Reliable Delivery":"Chuyển giao tin cậy","Handshake and ACKs":"Bắt tay và ACK","Data from laptop":"Dữ liệu từ laptop","Data from server":"Dữ liệu từ máy chủ","Closing (FIN)":"Đóng (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP biến việc chuyển gói “cố gắng hết sức” của Internet thành một luồng byte tin cậy và đúng thứ tự. Nó đánh số mọi byte, xác nhận những gì đến nơi, gửi lại những gì bị mất và điều chỉnh nhịp bên gửi để cả bên kia lẫn mạng đều không bị quá tải.","Transport (Layer 4)":"Giao vận (tầng 4)","Three-way handshake":"Bắt tay ba bước",Reliability:"Độ tin cậy","Sequence numbers + ACKs":"Số thứ tự + ACK",Recovery:"Khôi phục",Retransmission:"Truyền lại",Header:"Tiêu đề","20–60 bytes":"20–60 byte","Connection closed":"Đã đóng kết nối","Every byte accounted for":"Không thiếu byte nào","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP mở một kết nối, đánh số và xác nhận mọi byte, phát hiện một khoảng trống và chỉ gửi lại đúng đoạn bị thiếu, rồi đóng gọn cả hai chiều. curl nhận đủ mọi byte theo thứ tự và không hề biết có mất mát. Nhấn XEM LẠI để xem lại.",Segments:"Đoạn","14 (1 lost, 1 resent)":"14 (1 mất, 1 gửi lại)","Bytes delivered":"Byte đã giao","78 up, 2,920 down":"78 lên, 2,920 xuống","Loss found by":"Phát hiện mất nhờ","Duplicate ACK + SACK":"ACK trùng lặp + SACK","Open Connection":"Mở kết nối","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl đã biết địa chỉ máy chủ. Trước khi gửi dữ liệu, hai bên chọn một số thứ tự bắt đầu và xác nhận nó: SYN, SYN-ACK, ACK. Các số ở đây là tương đối; số thật bắt đầu từ một giá trị ngẫu nhiên.","203.0.113.10, port 80":"203.0.113.10, cổng 80","Send Data":"Gửi dữ liệu","Every byte is numbered":"Mỗi byte đều được đánh số","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl gửi yêu cầu HTTP 78 byte: các byte từ 1 đến 78. Số ACK của máy chủ, 79, là byte tiếp theo nó chờ, nghĩa là mọi thứ trước đó đã đến.",Sent:"Đã gửi","78 bytes (seq 1–78)":"78 byte (seq 1–78)","79 = next byte expected":"79 = byte tiếp theo đang chờ","Two Segments Back":"Hai đoạn gửi về","One of them is lost":"Một đoạn bị mất","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Máy chủ trả lời 2,920 byte: hai đoạn đầy, mỗi đoạn 1,460 byte, mức tối đa vừa một gói ở đây, gửi liền nhau. Đoạn đầu bị rơi đâu đó trên Internet; đoạn thứ hai đến nơi.","Segment 1":"Đoạn 1","bytes 1–1460 (lost)":"byte 1–1460 (mất)","Segment 2":"Đoạn 2","bytes 1461–2920":"byte 1461–2920","Segment size":"Kích thước đoạn","1,460 bytes (MSS)":"1,460 byte (MSS)","2 SEGMENTS":"2 ĐOẠN","seq=1 and seq=1461":"seq=1 và seq=1461","the first is lost":"đoạn đầu bị mất","SEGMENT 1 LOST":"MẤT ĐOẠN 1","A Gap Is Noticed":"Phát hiện khoảng trống","Duplicate ACK with SACK":"ACK trùng lặp kèm SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Byte 1461–2920 đến nơi, nhưng 1–1460 thì không. ACK chỉ đếm được các byte nhận theo thứ tự, nên laptop lập tức lặp lại ACK 1 và thêm một khối SACK cho biết nó đã có 1461–2920.","1 (still waiting for byte 1)":"1 (vẫn chờ byte 1)","holds bytes 1461–2920":"đã có byte 1461–2920","At once, not delayed":"Ngay lập tức, không trì hoãn","DUP ACK":"ACK TRÙNG","sack: has 1461–2920":"sack: có 1461–2920","Resend the Gap":"Gửi lại khoảng trống","Only the missing bytes":"Chỉ các byte bị thiếu","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"SACK cho máy chủ biết chính xác cái gì bị thiếu, nên nó chỉ gửi lại đoạn 1, và laptop xác nhận tất cả. Nếu không có ACK nào quay về, bộ hẹn giờ sẽ ra tay: một gói thăm dò sau khoảng hai lượt khứ hồi, rồi hết thời gian truyền lại (ít nhất 200 ms trên Linux).",Resent:"Đã gửi lại","bytes 1–1460 only":"chỉ byte 1–1460","Next ACK":"ACK tiếp theo","2921 (everything)":"2921 (tất cả)","curl saw":"curl thấy","Every byte, in order":"Mọi byte, đúng thứ tự",RESEND:"GỬI LẠI","just the missing segment":"chỉ đoạn bị thiếu","Close Connection":"Đóng kết nối","Each side says goodbye":"Mỗi bên chào tạm biệt","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl đã xong nên nó đóng. Mỗi chiều đóng riêng: laptop gửi FIN và máy chủ xác nhận, rồi máy chủ gửi FIN của mình và laptop xác nhận. Laptop giữ thông tin kết nối thêm một lúc (TIME-WAIT).","Closed by":"Đóng bằng","A FIN from each side":"Một FIN từ mỗi bên",Order:"Thứ tự",Then:"Sau đó","Laptop waits (TIME-WAIT)":"Laptop chờ (TIME-WAIT)",Data:"Dữ liệu","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 byte: phản hồi HTTP, byte 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 byte: phản hồi HTTP, byte 1461–2920","has 1461–2920":"có 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Các byte đến sau khoảng trống, nên chỉ cần gửi lại khoảng trống.","Fast Datagrams":"Datagram nhanh","Your voice":"Giọng của bạn","Their voice":"Giọng bên kia","Media Server":"Máy chủ media","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP gửi dữ liệu thành các gói độc lập gọi là datagram, không kết nối, không xác nhận và không gửi lại. Nhờ vậy nó nhanh và nhẹ: hợp cho thoại, video, game và DNS, nơi câu trả lời muộn còn tệ hơn không có.",None:"Không có","None (no ACKs, no resends)":"Không có (không ACK, không gửi lại)",Ordering:"Thứ tự","Not guaranteed":"Không đảm bảo","Call keeps flowing":"Cuộc gọi vẫn tiếp tục","Fast, simple, no guarantees":"Nhanh, đơn giản, không đảm bảo","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Âm thanh bắt đầu ngay từ gói đầu tiên, mỗi datagram tự đi riêng, và gói bị mất thì biến mất luôn: UDP không hề hay biết. Ứng dụng che khoảng trống và cuộc gọi vẫn tiếp tục. Nhấn XEM LẠI để xem lại.",Datagrams:"Datagram","11 (1 lost, never resent)":"11 (1 mất, không gửi lại)","Setup time":"Thời gian thiết lập","0 ms (no handshake)":"0 ms (không bắt tay)","8 bytes (TCP: 20+)":"8 byte (TCP: 20+)",Shown:"Hiển thị","The first 0.2 s of a call":"0.2 s đầu của cuộc gọi","Send Right Away":"Gửi ngay","No handshake, data goes first":"Không bắt tay, dữ liệu đi trước","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Ứng dụng gọi đã biết địa chỉ và cổng của máy chủ media từ lúc đăng nhập. Nó không mở kết nối: ngay datagram đầu tiên đã mang 20 ms giọng nói của bạn, sau một tiêu đề UDP 8 byte.",Setup:"Thiết lập",Ports:"Cổng","VOICE 1":"THOẠI 1","92 B of audio, no setup":"92 B âm thanh, không thiết lập","A Stream of Datagrams":"Một luồng datagram","One every 20 ms, each on its own":"Mỗi 20 ms một gói, gói nào đi riêng gói đó","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Ứng dụng cứ 20 ms gửi một datagram. Mỗi datagram độc lập, có tiêu đề riêng và không liên kết với các gói khác. UDP không đánh số chúng, và không có gì quay về xác nhận chúng đã đến.",Rate:"Tốc độ","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Đánh số","None in UDP itself":"UDP không tự đánh số",Confirmation:"Xác nhận","None (no ACKs)":"Không có (không ACK)","4 DATAGRAMS":"4 DATAGRAM","voice frames 2–5":"khung thoại 2–5","each with its own 8-byte header":"mỗi khung có tiêu đề 8 byte riêng","Lost on the Way":"Mất trên đường","Nobody resends it":"Không ai gửi lại","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Khung 7 bị rơi đâu đó trên Internet. Máy chủ media không bao giờ đòi lại, và UDP không bao giờ báo cho laptop: không có xác nhận nào để mà thiếu. Các datagram sau đó đến bình thường.",Lost:"Mất","Voice frame 7":"Khung thoại 7","Never (no ACKs)":"Không bao giờ (không ACK)",Missing:"Thiếu","20 ms of audio":"20 ms âm thanh","3 DATAGRAMS":"3 DATAGRAM","voice frames 6–8":"khung thoại 6–8","frame 7 is lost":"khung 7 bị mất","FRAME 7 LOST · NOT RESENT":"MẤT KHUNG 7 · KHÔNG GỬI LẠI","Replies Come Back":"Phản hồi quay về","The other voice comes back":"Giọng bên kia quay về","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Giọng của người kia đến theo cùng cách, thành các datagram riêng gửi tới cổng 50000. Chúng vào được vì router của bạn đã nhớ cổng đi ra khi dịch địa chỉ của bạn (NAT).",Direction:"Chiều","Independent of ours":"Độc lập với chiều của ta","Through NAT":"Qua NAT","Router remembers the port":"Router nhớ cổng","the other person’s voice":"giọng của người kia","sent to port 50000":"gửi tới cổng 50000","The App Decides":"Ứng dụng quyết định","Reliability is up to the app":"Độ tin cậy là việc của ứng dụng","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Ứng dụng gọi tự đánh số khung (RTP làm việc này), nên nó thấy khung 7 bị thiếu và làm mượt khoảng trống 20 ms thay vì chờ. Chờ gửi lại sẽ làm cả cuộc gọi bị trễ.","App’s job (e.g. RTP)":"Việc của ứng dụng (vd. RTP)",Loss:"Mất mát","Hidden by the app":"Ứng dụng che đi","Also on UDP":"Cũng dùng UDP","DNS, games, QUIC":"DNS, game, QUIC","APP COVERS THE 20 MS GAP":"ỨNG DỤNG CHE KHOẢNG TRỐNG 20 MS","RTP + audio":"RTP + âm thanh","Version etc.":"Phiên bản v.v.","2, no padding, no extension, no CSRCs":"2, không đệm, không mở rộng, không CSRC","Marker, payload type":"Marker, loại payload","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, thỏa thuận khi thiết lập cuộc gọi)","Counts up by one per packet, so the app can spot a missing or late one.":"Tăng một sau mỗi gói, để ứng dụng phát hiện gói bị thiếu hay đến muộn.",Timestamp:"Dấu thời gian","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Đồng hồ âm thanh 48,000 mỗi giây: +960 cho mỗi khung 20 ms.","Identifies this audio stream.":"Định danh luồng âm thanh này.",Audio:"Âm thanh","80 bytes of Opus audio (20 ms)":"80 byte âm thanh Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, thỏa thuận khi thiết lập cuộc gọi)","Addressing & Routing":"Định địa chỉ và định tuyến","Outgoing packet":"Gói đi ra",Reply:"Phản hồi","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP cấp cho mọi thiết bị một địa chỉ và chuyển gói từ mạng này sang mạng khác. Mỗi router chỉ nhìn địa chỉ đích để chọn chặng kế tiếp. IP là “cố gắng hết sức”: nó không hứa giao tới hay đúng thứ tự. TCP thêm những điều đó ở bên trên.","Network (Layer 3)":"Mạng (tầng 3)",Address:"Địa chỉ","32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","20–60 bytes (IPv4)":"20–60 byte (IPv4)","Lowered by 1 at each router":"Giảm 1 tại mỗi router",Delivery:"Chuyển giao","Best effort":"Cố gắng hết sức","There and back":"Đi và về","Twelve routers each way":"Mười hai router mỗi chiều","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Laptop gửi gói tới router của nó, router thay vào địa chỉ công khai của mình. Tổng cộng mười hai router chuyển tiếp nó chỉ dựa vào địa chỉ đích, và phản hồi tìm đường về cũng theo cách đó. Nhấn XEM LẠI để xem lại.",Routers:"Router","12 each way (1 home + 11)":"12 mỗi chiều (1 ở nhà + 11)","TTL at server":"TTL tại máy chủ","116 (sent with 128)":"116 (gửi đi với 128)","Rewritten by NAT":"NAT viết lại","Source out, destination back":"Nguồn khi đi, đích khi về","IPv4 (IPv6 works alike)":"IPv4 (IPv6 hoạt động tương tự)","Local or Not?":"Nội bộ hay không?","Compare the address with the subnet":"So sánh địa chỉ với mạng con","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Laptop là 192.168.1.10 với mặt nạ /24, nên mạng của nó từ 192.168.1.0 đến 192.168.1.255. Máy chủ 203.0.113.10 nằm ngoài dải này, nên gói phải tới cổng mặc định: router ở nhà.",Laptop:"Laptop","Local range":"Dải nội bộ",Gateway:"Cổng mặc định","203.0.113.10 IS NOT LOCAL":"203.0.113.10 KHÔNG NỘI BỘ","Find the Router":"Tìm router","ARP turns an IP into a MAC":"ARP đổi IP thành MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Trong mạng nội bộ, khung được giao theo địa chỉ MAC. Nếu MAC của router chưa có trong bộ nhớ ARP của laptop, nó hỏi cả mạng “ai có 192.168.1.1?” và router trả lời bằng địa chỉ MAC của mình.",Asks:"Hỏi","Who has 192.168.1.1?":"Ai có 192.168.1.1?","Sent to":"Gửi tới","Everyone (broadcast)":"Mọi người (quảng bá)",Learns:"Biết được","Router’s MAC address":"Địa chỉ MAC của router","ARP REQUEST":"YÊU CẦU ARP","who has 192.168.1.1?":"ai có 192.168.1.1?","tell 192.168.1.10":"báo cho 192.168.1.10","ARP REPLY":"TRẢ LỜI ARP","Send the Packet":"Gửi gói tin","Addresses, TTL and protocol":"Địa chỉ, TTL và giao thức","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Tiêu đề IP mang địa chỉ nguồn và đích, một TTL và giao thức bên trong. Ở đây nó chứa một TCP SYN tới cổng 443. Windows bắt đầu TTL từ 128 (Linux và macOS dùng 64).","From → to":"Từ → tới","IP PACKET":"GÓI IP","TTL 128 · protocol TCP":"TTL 128 · giao thức TCP","NAT, Then Hop by Hop":"NAT, rồi từng chặng một","The router rewrites and forwards":"Router viết lại và chuyển tiếp","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Router thay nguồn riêng bằng địa chỉ công khai 198.51.100.7 của nó (và ở đây đổi cổng 52344 thành 40112), ghi lại ánh xạ và hạ TTL xuống 127. Rồi 11 router trên Internet mỗi cái chọn chặng kế tiếp theo đích và lại hạ TTL.","New source":"Nguồn mới","Leaves home":"Rời khỏi nhà","At the server":"Tại máy chủ","TTL 116 (11 more hops)":"TTL 116 (thêm 11 chặng)","TTL 127 · after NAT":"TTL 127 · sau NAT","ARRIVED WITH TTL 116":"ĐẾN NƠI VỚI TTL 116","The Reply Comes Back":"Phản hồi quay về","NAT translates it for the laptop":"NAT dịch nó cho laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Máy chủ trả lời địa chỉ nó thấy, 198.51.100.7:40112. Router tra địa chỉ đó trong bảng NAT, viết lại đích thành 192.168.1.10:52344 và chuyển tiếp. Phản hồi bắt đầu với TTL 64 và đến nơi với 52.","Delivered to":"Giao tới","64 → 52 (12 routers)":"64 → 52 (12 router)",REPLY:"PHẢN HỒI","TTL 52 · after NAT":"TTL 52 · sau NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (sau NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (sau NAT)","ARP request · 28 bytes":"Yêu cầu ARP · 28 byte","Broadcast: every device on the network receives it.":"Quảng bá: mọi thiết bị trong mạng đều nhận.","The sender’s network card.":"Card mạng của bên gửi.","Hardware type":"Loại phần cứng","1 (Ethernet)":"1 (Ethernet)","Protocol type":"Loại giao thức","Address sizes":"Kích thước địa chỉ",Operation:"Thao tác","1 (request: who has …?)":"1 (yêu cầu: ai có …?)","Sender MAC":"MAC bên gửi","Sender IP":"IP bên gửi","Target MAC":"MAC đích","All zeros: this is what the request wants to find out.":"Toàn số 0: đây chính là điều yêu cầu muốn tìm ra.","Target IP":"IP đích","ARP reply · 28 bytes":"Trả lời ARP · 28 byte","Straight back to the device that asked.":"Gửi thẳng về thiết bị đã hỏi.","2 (reply: … is at …)":"2 (trả lời: … ở tại …)","Seen as it leaves the router’s internet side":"Thấy khi rời phía Internet của router","The internet provider’s router, the next hop.":"Router của nhà mạng, chặng kế tiếp.","The router’s internet-facing port.":"Cổng của router hướng ra Internet.","As sent: this system starts at 64.":"Như khi gửi: hệ thống này bắt đầu từ 64.","The router’s NAT swapped in its own port for the laptop’s.":"NAT của router đã thay cổng của laptop bằng cổng của nó.","The sender’s next router; each hop puts the packet in a new frame.":"Router kế tiếp của bên gửi; mỗi chặng đặt gói vào một khung mới.","Name Resolution":"Phân giải tên",Query:"Truy vấn",Referral:"Chuyển tiếp","DNSSEC not requested here":"Không yêu cầu DNSSEC ở đây","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS biến các tên như www.example.com thành địa chỉ IP mà máy tính dùng để liên lạc với nhau. Không máy chủ nào biết mọi tên: hệ thống là một hệ phân cấp máy chủ, và câu trả lời được lưu đệm dọc đường nên phần lớn lượt tra cứu không phải đi xa.","53, UDP (TCP if large)":"53, UDP (TCP nếu lớn)",Turns:"Biến đổi","Names into IP addresses":"Tên thành địa chỉ IP",Hierarchy:"Phân cấp","Root → TLD → authoritative":"Gốc → TLD → có thẩm quyền",Caching:"Lưu đệm","For each record’s TTL":"Theo TTL của từng bản ghi","Name resolved":"Đã phân giải tên","And remembered for an hour":"Và ghi nhớ trong một giờ","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Bắt đầu với bộ nhớ đệm trống, bộ phân giải đi từ gốc tới .com rồi tới máy chủ riêng của example.com, sau đó trả lời laptop. Cho đến khi hết TTL, lượt tra cứu tiếp theo cho tên này được trả lời thẳng từ bộ nhớ đệm. Nhấn XEM LẠI để xem lại.",Queries:"Truy vấn","4 (laptop 1, resolver 3)":"4 (laptop 1, bộ phân giải 3)","Cached for":"Lưu đệm trong","Ask the Resolver":"Hỏi bộ phân giải","The laptop hands the question off":"Laptop giao câu hỏi đi","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Trình duyệt cần địa chỉ IP của www.example.com mà cả nó lẫn Windows đều chưa lưu đệm. Laptop gửi một câu hỏi tới bộ phân giải đệ quy mà nó được cấp, 8.8.8.8, và nhờ nó làm toàn bộ việc tra cứu (yêu cầu đệ quy).","www.example.com, type A":"www.example.com, loại A",Asked:"Đã hỏi","8.8.8.8 (recursive)":"8.8.8.8 (đệ quy)","RD (recursion desired)":"RD (yêu cầu đệ quy)","flags: RD":"cờ: RD","Points the way to .com":"Chỉ đường tới .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Bộ nhớ đệm của bộ phân giải trống (nó vừa khởi động), nên nó bắt đầu từ trên cùng. Máy chủ gốc không biết địa chỉ, nhưng biết máy chủ nào phụ trách .com và trả lời bằng một lời chuyển tiếp. Nhiều bộ phân giải chỉ gửi cho nó “com”, không phải tên đầy đủ.","Root servers":"Máy chủ gốc","13 names, 1,000+ anycast sites":"13 tên, hơn 1,000 điểm anycast","Referral (13 .com servers)":"Chuyển tiếp (13 máy chủ .com)","NOT IN CACHE":"KHÔNG CÓ TRONG ĐỆM",REFERRAL:"CHUYỂN TIẾP","no answer: ask .com":"không trả lời: hỏi .com","Points the way to example.com":"Chỉ đường tới example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Bộ phân giải hỏi một trong các máy chủ .com. Chúng cũng không lưu địa chỉ của mọi trang, nhưng biết mỗi tên miền .com dùng máy chủ tên nào, nên câu trả lời này lại là một lời chuyển tiếp, kèm địa chỉ của các máy chủ đó (glue).",Knows:"Biết","Name servers of .com domains":"Máy chủ tên của các tên miền .com","Referral + glue addresses":"Chuyển tiếp + địa chỉ glue","no answer: ask example.com":"không trả lời: hỏi example.com","Gives the actual answer":"Đưa ra câu trả lời thật","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Cuối cùng bộ phân giải hỏi máy chủ tên riêng của example.com, nơi giữ các bản ghi của tên miền. Nó trả lời bằng bản ghi A và đánh dấu câu trả lời là có thẩm quyền. Chủ tên miền quyết định nó được lưu đệm bao lâu: ở đây là 3600 giây.","AA (authoritative), TTL 3600":"AA (có thẩm quyền), TTL 3600",ANSWER:"TRẢ LỜI","TTL 3600 · flag AA":"TTL 3600 · cờ AA","Answer & Cache":"Trả lời và lưu đệm","The laptop gets its address":"Laptop nhận được địa chỉ","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Bộ phân giải gửi câu trả lời về laptop và giữ một bản sao. Trong một giờ tới nó có thể trả lời tên này ngay, vì thế bước tra cứu trong bài HTTP chỉ mất 24 ms. Laptop cũng lưu đệm nó.","RD, RA (recursion available)":"RD, RA (có hỗ trợ đệ quy)","Cached by":"Lưu đệm tại","Resolver and laptop":"Bộ phân giải và laptop","flags: RD RA":"cờ: RD RA","CACHED · TTL 3600 S":"ĐÃ LƯU ĐỆM · TTL 3600 S","Referral: com. NS ×13 (with glue)":"Chuyển tiếp: com. NS ×13 (kèm glue)","Referral: example.com. NS ×2 (with glue)":"Chuyển tiếp: example.com. NS ×2 (kèm glue)","Response A 203.0.113.10 (authoritative)":"Phản hồi A 203.0.113.10 (có thẩm quyền)","As sent: this system starts at 128.":"Như khi gửi: hệ thống này bắt đầu từ 128.","0x0000: query":"0x0000: truy vấn","UDP size 1232, DNSSEC OK = 0":"Kích thước UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Cho biết câu trả lời UDP có thể lớn đến đâu. Ở đây không yêu cầu chữ ký DNSSEC cho bài học ngắn gọn; bộ phân giải có xác thực như 8.8.8.8 thì có yêu cầu.","0x8000: response":"0x8000: phản hồi",Authority:"Thẩm quyền",Additional:"Bổ sung","0x8400: response, AA (authoritative)":"0x8400: phản hồi, AA (có thẩm quyền)","Getting an Address":"Nhận địa chỉ","From the laptop":"Từ laptop","From the DHCP server":"Từ máy chủ DHCP","No IP address":"Chưa có địa chỉ IP","192.168.1.1 · DHCP server":"192.168.1.1 · máy chủ DHCP","Dynamic Host Configuration Protocol":"Dynamic Host Configuration Protocol","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP cấp cho thiết bị mọi thứ cần để dùng mạng: một địa chỉ IP, mặt nạ mạng con, router để gửi lưu lượng qua và các máy chủ DNS để hỏi. Địa chỉ được cho thuê trong một thời gian nhất định và gia hạn khi thiết bị còn ở trong mạng.","UDP 67 (server), 68 (client)":"UDP 67 (máy chủ), 68 (máy khách)","Hands out":"Cấp phát","IP, mask, gateway, DNS":"IP, mặt nạ, cổng mặc định, DNS",Exchange:"Trao đổi",Lease:"Thời hạn thuê","Renewed at half its time":"Gia hạn khi hết nửa thời gian","On the network":"Đã vào mạng","Leased, and kept up to date":"Đã thuê và luôn cập nhật","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Bốn thông điệp đưa laptop từ chỗ chưa có địa chỉ tới một cấu hình chạy được, và khi hợp đồng thuê 24 giờ qua được một nửa, nó gia hạn bằng một yêu cầu gửi thẳng tới router. Nhấn XEM LẠI để xem lại.",Messages:"Thông điệp","4 to join, 2 per renewal":"4 để vào mạng, 2 mỗi lần gia hạn","24 h, renewed at 12 h":"24 h, gia hạn ở 12 h","No Address Yet":"Chưa có địa chỉ","The laptop joins the network":"Laptop vào mạng","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Laptop vừa kết nối. Nó có sẵn địa chỉ MAC, nhưng chưa có địa chỉ IP, cổng mặc định hay máy chủ DNS, nên chưa thể nói chuyện với gì ngoài mạng của chính nó. Nó xin những thứ đó bằng DHCP.","IP address":"Địa chỉ IP","None (uses 0.0.0.0)":"Chưa có (dùng 0.0.0.0)","MAC address":"Địa chỉ MAC",Needs:"Cần","NO IP ADDRESS YET":"CHƯA CÓ ĐỊA CHỈ IP",Discover:"Discover","Shout to the whole network":"Gọi to cả mạng","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Chưa có địa chỉ riêng, laptop gửi từ 0.0.0.0 tới địa chỉ quảng bá 255.255.255.255, nên mọi thiết bị trong mạng nội bộ đều nhận được. Chỉ máy chủ DHCP trả lời.",From:"Từ","0.0.0.0, UDP port 68":"0.0.0.0, cổng UDP 68","255.255.255.255, port 67":"255.255.255.255, cổng 67",Carries:"Mang theo","MAC, transaction ID":"MAC, ID giao dịch","any DHCP server out there?":"có máy chủ DHCP nào không?",Offer:"Offer","The router proposes an address":"Router đề xuất một địa chỉ","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Máy chủ DHCP của router chọn một địa chỉ còn trống và đề xuất nó cùng các thiết lập khác. Laptop chưa dùng được địa chỉ IP, nên lời đề xuất gửi thẳng tới địa chỉ MAC của nó (một số máy khách xin gửi quảng bá thay vào đó).",Offered:"Đề xuất","Gateway, DNS":"Cổng mặc định, DNS","offer: 192.168.1.10/24":"đề xuất: 192.168.1.10/24","gateway, DNS, lease 24 h":"cổng, DNS, thuê 24 h","Accept, out loud":"Chấp nhận công khai","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Laptop xin địa chỉ được đề xuất, nêu tên máy chủ nó chọn. Nó vẫn gửi quảng bá, nên mọi máy chủ DHCP khác đã đưa ra đề xuất đều biết mình không được chọn và có thể giải phóng địa chỉ của mình.",Requests:"Xin","Chosen server":"Máy chủ được chọn","I’ll take 192.168.1.10":"tôi lấy 192.168.1.10","from server 192.168.1.1":"từ máy chủ 192.168.1.1",Acknowledge:"Xác nhận","The address is the laptop’s":"Địa chỉ thuộc về laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Máy chủ xác nhận, và laptop cấu hình địa chỉ, mặt nạ, cổng mặc định và máy chủ DNS. Nhiều hệ thống trước hết kiểm tra bằng ARP rằng chưa có thiết bị nào khác dùng địa chỉ đó.","DNS server":"Máy chủ DNS","192.168.1.10 is yours":"192.168.1.10 là của bạn","for 24 hours":"trong 24 giờ","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · THUÊ 24 H",Renew:"Gia hạn","Halfway through the lease":"Khi thời hạn thuê qua một nửa","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Mười hai giờ sau, thời hạn thuê đã qua một nửa. Giờ laptop đã có địa chỉ, nên nó xin router gia hạn trực tiếp, và router đặt lại thành 24 giờ. Nếu router không trả lời, nó sẽ gửi quảng bá ở mức 87.5%.",When:"Khi nào","50% of lease (T1 = 12 h)":"50% thời hạn (T1 = 12 h)","The router (unicast)":"Router (unicast)","If unanswered":"Nếu không trả lời","Broadcast at 87.5% (T2)":"Quảng bá ở 87.5% (T2)","renew 192.168.1.10":"gia hạn 192.168.1.10","sent straight to 192.168.1.1":"gửi thẳng tới 192.168.1.1","lease renewed":"đã gia hạn","another 24 hours":"thêm 24 giờ nữa",Message:"Thông điệp","1 (request, from a client)":"1 (yêu cầu, từ máy khách)",Hardware:"Phần cứng","Ethernet, 6-byte addresses":"Ethernet, địa chỉ 6 byte",Hops:"Số chặng","Chosen by the client; every reply repeats it.":"Do máy khách chọn; mọi phản hồi đều lặp lại nó.",Seconds:"Giây","0x0000 (unicast replies are fine)":"0x0000 (phản hồi unicast cũng được)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Tắt cờ quảng bá: máy chủ có thể gửi thẳng tới địa chỉ MAC của máy khách.","Client address":"Địa chỉ máy khách","Filled in only when the client already has an address (renewing).":"Chỉ điền khi máy khách đã có địa chỉ (gia hạn).","Your address":"Địa chỉ của bạn","The address the server is giving out.":"Địa chỉ máy chủ đang cấp.","Next server":"Máy chủ kế tiếp","Relay agent":"Tác nhân chuyển tiếp","Client MAC":"MAC máy khách","Server name, boot file":"Tên máy chủ, tệp khởi động",empty:"trống","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Đánh dấu các tùy chọn theo sau là DHCP.","Message type: 1 (Discover)":"Loại thông điệp: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Định danh máy khách: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Tên máy: alice-laptop","Vendor class: MSFT 5.0":"Lớp nhà sản xuất: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Tham số cần: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252",End:"Kết thúc","2 (reply, from a server)":"2 (phản hồi, từ máy chủ)","Message type: 2 (Offer)":"Loại thông điệp: 2 (Offer)","Server identifier: 192.168.1.1":"Định danh máy chủ: 192.168.1.1","Lease time: 86,400 s (24 h)":"Thời hạn thuê: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Thời điểm gia hạn (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Thời điểm gắn lại (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Mặt nạ mạng con: 255.255.255.0","Broadcast address: 192.168.1.255":"Địa chỉ quảng bá: 192.168.1.255","Router: 192.168.1.1":"Router: 192.168.1.1","DNS server: 8.8.8.8":"Máy chủ DNS: 8.8.8.8","Message type: 3 (Request)":"Loại thông điệp: 3 (Request)","Requested address: 192.168.1.10":"Địa chỉ xin cấp: 192.168.1.10","Client FQDN: alice-laptop":"FQDN máy khách: alice-laptop","Message type: 5 (ACK)":"Loại thông điệp: 5 (ACK)","Network Diagnostics":"Chẩn đoán mạng","Ping / probe":"Ping / thăm dò","Echo reply":"Trả lời echo","Error report":"Báo lỗi","Internet Control Message Protocol":"Internet Control Message Protocol","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP là cách mạng báo ngược lại: một router nói thời gian sống của gói đã hết, một máy chủ nói không có gì lắng nghe trên một cổng. Các công cụ như ping và traceroute được xây từ những thông điệp này. Nó đi bên trong IP nhưng không mang dữ liệu ứng dụng.","Carried in":"Đi bên trong","IP (protocol 1)":"IP (giao thức 1)","A type and a code":"Một loại và một mã",Tools:"Công cụ",Often:"Thường","Filtered by firewalls":"Bị tường lửa lọc","The network answered":"Mạng đã trả lời","Replies, expiries and errors":"Phản hồi, hết hạn và lỗi","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Một yêu cầu echo đo thời gian khứ hồi, các gói có TTL nhỏ khiến mỗi router trên đường tự xưng danh, và một cổng đóng được báo về ngay. Nhấn XEM LẠI để xem lại.","Round trip":"Khứ hồi",Path:"Đường đi","12 routers, server at hop 13":"12 router, máy chủ ở chặng 13","Types used":"Các loại đã dùng","8, 0, 11 and 3":"8, 0, 11 và 3","Reply TTL":"TTL phản hồi","52 (64 − 12 routers)":"52 (64 − 12 router)",Ping:"Ping","Echo request":"Yêu cầu echo","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"“ping -n 1 203.0.113.10” gửi một yêu cầu echo ICMP (ping thường gửi bốn lần, cách nhau một giây): loại 8, mã 0, với một định danh, một số thứ tự và 32 byte đệm. Hệ thống của máy chủ tự trả lời, không cần ứng dụng nào.","Type, code":"Loại, mã","8, 0 (echo request)":"8, 0 (yêu cầu echo)","32 bytes (Windows)":"32 byte (Windows)","ECHO REQUEST":"YÊU CẦU ECHO","type 8 · seq 1":"loại 8 · seq 1","32 bytes of data":"32 byte dữ liệu","Echo Reply":"Trả lời echo","Round-trip time":"Thời gian khứ hồi","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Máy chủ gửi lại một trả lời echo, loại 0, với cùng định danh, số thứ tự và dữ liệu. Ping in ra thời gian đã mất và TTL mà phản hồi mang theo khi đến: “bytes=32 time=34ms TTL=52”.","0, 0 (echo reply)":"0, 0 (trả lời echo)","TTL on arrival":"TTL khi đến","ECHO REPLY":"TRẢ LỜI ECHO","type 0 · seq 1":"loại 0 · seq 1","same 32 bytes back":"trả lại đúng 32 byte","TIME=34MS TTL=52":"TIME=34MS TTL=52","The first router answers":"Router đầu tiên trả lời","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"“ping -n 1 -i 1” gửi cùng yêu cầu với TTL bằng 1. Router ở nhà hạ nó xuống 0, nên phải bỏ gói, và gửi lại thông điệp Time Exceeded từ địa chỉ của chính nó: “Reply from 192.168.1.1: TTL expired in transit.”","Sent with":"Gửi với","Dropped by":"Bị bỏ bởi","11, 0 (time exceeded)":"11, 0 (hết thời gian)","echo request":"yêu cầu echo","expires at the first router":"hết hạn ở router đầu tiên","TIME EXCEEDED":"HẾT THỜI GIAN","type 11 · from 192.168.1.1":"loại 11 · từ 192.168.1.1","quotes the dropped header":"trích tiêu đề bị bỏ","The next router answers":"Router tiếp theo trả lời","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Với “-i 2”, router ở nhà hạ TTL xuống 1 và chuyển tiếp. Router đầu tiên của nhà mạng hạ nó xuống 0 và báo về từ 198.51.100.1. Router ở nhà dịch báo cáo đó về cho laptop như mọi phản hồi khác.","ISP router 198.51.100.1":"Router nhà mạng 198.51.100.1","expires at the second router":"hết hạn ở router thứ hai","HOP 2 · 198.51.100.1":"CHẶNG 2 · 198.51.100.1","type 11 · from 198.51.100.1":"loại 11 · từ 198.51.100.1","That’s Traceroute":"Đó chính là traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … cho đến khi tới nơi","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert tự động hóa việc này: mỗi lần tăng TTL thêm một, gửi ba gói thăm dò mỗi chặng và liệt kê ai báo về. Các chặng 3 đến 12 cũng vậy, và với TTL 13 yêu cầu cuối cùng tới được máy chủ, máy chủ trả lời bình thường.","12 routers, then the server":"12 router, rồi máy chủ","Per hop":"Mỗi chặng","3 probes":"3 gói thăm dò","On Linux":"Trên Linux","traceroute sends UDP":"traceroute gửi UDP","enough hops to arrive":"đủ chặng để tới nơi","the server itself answers":"chính máy chủ trả lời","end of the route":"cuối đường đi",Unreachable:"Không tới được","Nothing listening on that port":"Không có gì lắng nghe trên cổng đó","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Một ứng dụng gửi datagram UDP tới cổng 9999, nơi không có gì lắng nghe. Máy chủ không giao được, nên trả lời bằng Destination Unreachable, mã 3 (cổng không tới được), trích phần đầu của datagram. Nhiều tường lửa lại lặng lẽ bỏ các gói như vậy.","3, 3 (port unreachable)":"3, 3 (cổng không tới được)","Other codes":"Mã khác","0 net, 1 host, 4 too big":"0 mạng, 1 máy, 4 quá lớn",Firewalls:"Tường lửa","Often silent instead":"Thường im lặng thay vào đó","to port 9999":"tới cổng 9999","nothing listening there":"không có gì lắng nghe ở đó",UNREACHABLE:"KHÔNG TỚI ĐƯỢC","type 3 · code 3":"loại 3 · mã 3","port unreachable":"cổng không tới được","ICMP · Echo request":"ICMP · Yêu cầu echo",Code:"Mã","Covers the whole ICMP message.":"Bao phủ toàn bộ thông điệp ICMP.",Identifier:"Định danh","Matches replies to this ping program.":"Ghép phản hồi với chương trình ping này.","Windows counts up across every ping it sends.":"Windows đếm tăng dần qua mọi lần ping nó gửi.",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 byte)',"Windows ping’s filler: the alphabet, a to w, then again.":"Phần đệm của ping trên Windows: bảng chữ cái từ a đến w, rồi lặp lại.","ICMP · Echo reply":"ICMP · Trả lời echo","Sent back exactly as it came.":"Gửi lại đúng như khi đến.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Hết thời gian (TTL về 0)","Time exceeded (TTL reached 0)":"Hết thời gian (TTL về 0)",Unused:"Không dùng","Original packet":"Gói gốc","Its source, destination":"Nguồn và đích của nó","its IP header and first 8 bytes (28 bytes)":"tiêu đề IP của nó và 8 byte đầu (28 byte)","App data":"Dữ liệu ứng dụng",'"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 byte)',"What the app sent; nothing on the server is listening for it.":"Những gì ứng dụng đã gửi; trên máy chủ không có gì lắng nghe nó.","ICMP · Destination unreachable (port unreachable)":"ICMP · Không tới được đích (cổng không tới được)","Destination unreachable (port unreachable)":"Không tới được đích (cổng không tới được)","Sending Email":"Gửi email","SMTP command":"Lệnh SMTP","SMTP reply":"Trả lời SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP chuyển email: từ ứng dụng thư của bạn tới máy chủ của nhà cung cấp, và từ máy chủ đó tới máy chủ của người nhận. Đó là một cuộc hội thoại bằng các lệnh văn bản ngắn, mỗi lệnh được trả lời bằng một mã ba chữ số. Đọc thư là việc khác, làm bằng IMAP hoặc POP3.","465/587 submit, 25 relay":"465/587 gửi, 25 chuyển tiếp","TCP, usually with TLS":"TCP, thường kèm TLS",Commands:"Lệnh",Replies:"Trả lời","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx tiếp tục, 4/5xx lỗi","Mail delivered":"Đã giao thư","Two hops, one message":"Hai chặng, một thư","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Ứng dụng của Alice giao thư cho nhà cung cấp của cô qua một kết nối đã mã hóa và đăng nhập. Nhà cung cấp tìm máy chủ thư của Bob trong DNS và chuyển thư tới đó, nâng liên kết đó lên TLS. Giờ thư chờ trong hộp thư của Bob cho đến khi anh đọc bằng IMAP hoặc POP3.","Laptop → provider → Bob’s":"Laptop → nhà cung cấp → Bob",Submission:"Gửi đi","Port 465, TLS, login":"Cổng 465, TLS, đăng nhập",Relay:"Chuyển tiếp","Port 25, STARTTLS":"Cổng 25, STARTTLS","Checks at Bob’s":"Kiểm tra phía Bob","Connect Securely":"Kết nối an toàn","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice bấm Gửi. Ứng dụng thư của cô kết nối tới máy chủ gửi thư của nhà cung cấp, smtp.example.com, trên cổng 465. Trên cổng này TLS bắt đầu ngay, nên toàn bộ cuộc hội thoại SMTP, kể cả mật khẩu, đều được mã hóa.","TLS from the start":"TLS ngay từ đầu","SMTP inside TLS":"SMTP bên trong TLS","Greeting & Login":"Chào hỏi và đăng nhập","EHLO, then AUTH":"EHLO, rồi AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Máy chủ chào bằng mã 220. Ứng dụng nói EHLO và máy chủ liệt kê những gì nó hỗ trợ, gồm cả AUTH. Ứng dụng đăng nhập bằng AUTH PLAIN (tên người dùng và mật khẩu, mã hóa base64) và nhận 235: đã xác thực.",Greeting:"Lời chào",Capabilities:"Khả năng","Login result":"Kết quả đăng nhập","user and password, base64":"người dùng và mật khẩu, base64","Send the Message":"Gửi thư","Envelope, then content":"Phong bì, rồi nội dung","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM và RCPT TO là phong bì: người gửi và người nhận. PIPELINING cho cả ba lệnh đi chung một gói. Sau 354 là thư, kết thúc bằng một dòng chỉ có một dấu chấm.",Envelope:"Phong bì","Content ends":"Nội dung kết thúc","A line with only “.”":"Một dòng chỉ có “.”",Result:"Kết quả",MESSAGE:"THƯ","… message …":"… thư …","250 QUEUED":"250 ĐÃ XẾP HÀNG","Find Bob’s Server":"Tìm máy chủ của Bob","An MX lookup in DNS":"Tra cứu MX trong DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Giờ nhà cung cấp của Alice phải giao tới example.org. Nó hỏi DNS bản ghi MX của tên miền đó, cho biết máy chủ nhận thư của nó, rồi tra địa chỉ của máy chủ đó.","MX record":"Bản ghi MX","Asked by":"Do ai hỏi","Alice’s provider":"Nhà cung cấp của Alice","Server to Server":"Máy chủ tới máy chủ","Port 25, upgraded with STARTTLS":"Cổng 25, nâng cấp bằng STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Nhà cung cấp kết nối tới mx.example.org trên cổng 25. Cuộc hội thoại này bắt đầu bằng văn bản thường: lời chào và trả lời EHLO quảng cáo STARTTLS, nhà cung cấp yêu cầu nó, nhận 220 và cả hai bên chuyển sang TLS.","Starts as":"Bắt đầu bằng","Plain text":"Văn bản thường",Upgrade:"Nâng cấp",Deliver:"Giao thư","The same transaction again":"Lại cùng giao dịch đó","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Khi TLS đã bật, nhà cung cấp lặp lại EHLO, rồi phong bì và thư, lần này thêm chữ ký DKIM và một tiêu đề Received. Máy chủ của Bob kiểm tra SPF, DKIM và DMARC rồi chấp nhận.","Login needed":"Cần đăng nhập","No (server to server)":"Không (máy chủ tới máy chủ)","1,316 bytes (signed)":"1,316 byte (đã ký)","IN BOB’S MAILBOX":"TRONG HỘP THƯ CỦA BOB","Server Hello + encrypted handshake, 2 segments":"Server Hello + bắt tay đã mã hóa, 2 đoạn","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 khả năng (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (thông tin đăng nhập)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (gửi gộp)","Message (316 bytes), then “.”":"Thư (316 byte), rồi “.”","250 capabilities (PIPELINING, STARTTLS …)":"250 khả năng (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 khả năng (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Thư (1,316 byte), rồi “.”","What this client supports. Its exact contents vary from client to client; this is an example.":"Những gì máy khách này hỗ trợ. Nội dung chính xác khác nhau giữa các máy khách; đây là một ví dụ.","up to 512 bytes":"tối đa 512 byte","The server’s choices and its key share.":"Các lựa chọn của máy chủ và phần khóa của nó.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (chuỗi chứng chỉ), Certificate Verify (chữ ký), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Thư của Alice (316 byte), rồi một dòng chỉ có “.”","example.org, type MX, class IN":"example.org, loại MX, lớp IN","mx.example.org, type A, class IN":"mx.example.org, loại A, lớp IN",Timestamps:"Dấu thời gian","Used to measure round trips; both sides offered them.":"Dùng để đo thời gian khứ hồi; cả hai bên đều đề xuất.","The signed message (1,316 bytes), then a line holding only “.”":"Thư đã ký (1,316 byte), rồi một dòng chỉ có “.”","Downloading Email":"Tải email về","POP3 command":"Lệnh POP3","POP3 reply":"Trả lời POP3","Post Office Protocol, version 3":"Post Office Protocol, phiên bản 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 cho ứng dụng thư tải thư từ một hộp thư trên máy chủ. Nó được thiết kế cho một thiết bị lấy thư về rồi xóa khỏi máy chủ. Lệnh là những từ ngắn, và mọi trả lời đều bắt đầu bằng +OK hoặc -ERR.",Model:"Mô hình","Download, then delete":"Tải về, rồi xóa","+OK or -ERR":"+OK hoặc -ERR","Mail downloaded":"Đã tải thư về","And gone from the server":"Và biến mất khỏi máy chủ","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Ứng dụng của Bob đăng nhập, thấy hai thư, tải thư đầu về và xóa nó, việc mà máy chủ thực hiện lúc QUIT. Thư đó giờ chỉ còn trên laptop này, vì thế POP3 hợp với một thiết bị còn IMAP hợp với nhiều thiết bị.","2 waiting, 1 downloaded":"2 đang chờ, 1 đã tải",Deleted:"Đã xóa","At QUIT (UPDATE state)":"Lúc QUIT (trạng thái UPDATE)","Best for":"Phù hợp nhất cho","A single device":"Một thiết bị","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Ứng dụng thư của Bob kết nối tới pop.example.org trên cổng 995, nơi TLS bắt đầu ngay. Bên trong, máy chủ chào bằng +OK. (Trên cổng 110, phiên bắt đầu bằng văn bản thường và được nâng cấp bằng lệnh STLS.)","Log In":"Đăng nhập","USER, then PASS":"USER, rồi PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Ứng dụng gửi tên người dùng bằng USER và mật khẩu bằng PASS. Mỗi lệnh nhận một +OK riêng. Vì phiên nằm trong TLS, mật khẩu không đọc được trên đường đi.","Protected by":"Được bảo vệ bởi","Check the Mailbox":"Kiểm tra hộp thư","STAT and LIST":"STAT và LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT trả về số thư và tổng kích thước: 2 thư, 5120 byte. LIST cho số thứ tự và kích thước từng thư, kết thúc bằng một dòng chỉ có một dấu chấm.","Message 1":"Thư 1","Message 2":"Thư 2",Download:"Tải về","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 xin thư đầu tiên. Máy chủ trả lời +OK kèm kích thước, rồi đến thư và một dấu chấm kết thúc: 1904 byte cộng dòng trả lời, hai đoạn TCP.",Command:"Lệnh","Delete & Quit":"Xóa và thoát","Deleted only at QUIT":"Chỉ xóa lúc QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 chỉ đánh dấu thư. Máy chủ xóa nó khi ứng dụng nói QUIT: nếu kết nối rớt trước đó, sẽ không có gì bị xóa. Nhiều ứng dụng có tùy chọn “để lại bản sao trên máy chủ”, tức bỏ qua DELE.","Marks message 1":"Đánh dấu thư 1",Removed:"Đã xóa","At QUIT":"Lúc QUIT",Option:"Tùy chọn","Leave a copy on server":"Để lại bản sao trên máy chủ","MESSAGE 1 DELETED":"ĐÃ XÓA THƯ 1","PASS (password)":"PASS (mật khẩu)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, thư, “.” (2 đoạn)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, thư 1,904 byte, rồi một dòng chỉ có “.”","IMAP command":"Lệnh IMAP","IMAP response":"Trả lời IMAP","Internet Message Access Protocol":"Internet Message Access Protocol","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP cho ứng dụng thư làm việc với một hộp thư nằm luôn trên máy chủ. Thư mục, dấu đã đọc, gắn cờ và việc xóa đều được lưu ở đó, nên điện thoại, laptop và webmail đều thấy cùng một hộp thư. Máy chủ còn có thể báo cho ứng dụng biết khi có thư mới.","Mail stays on the server":"Thư nằm trên máy chủ",Syncs:"Đồng bộ","Folders and flags":"Thư mục và cờ","Mailbox in sync":"Hộp thư đã đồng bộ","Read once, read everywhere":"Đọc một lần, đọc ở mọi nơi","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Ứng dụng của Bob mở hộp thư đến, đọc một thư, khiến thư đó được đánh dấu \\Seen trên máy chủ cho mọi thiết bị của anh, rồi chờ bằng IDLE cho đến khi máy chủ báo có thư mới. Không có gì bị xóa: máy chủ vẫn giữ mọi thứ.","2, then 3 (new mail)":"2, rồi 3 (thư mới)","Read mark":"Dấu đã đọc","\\Seen, stored on server":"\\Seen, lưu trên máy chủ","New mail":"Thư mới","Pushed during IDLE":"Đẩy về trong lúc IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Ứng dụng của Bob kết nối tới imap.example.org trên cổng 993, nơi TLS bắt đầu ngay. Máy chủ chào bằng một dòng “* OK” không gắn thẻ, đồng thời liệt kê các khả năng của nó, chẳng hạn IDLE.","Commands carry tags":"Lệnh mang thẻ","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Mỗi lệnh bắt đầu bằng một thẻ do ứng dụng chọn, như a1, và máy chủ kết thúc câu trả lời bằng chính thẻ đó. Nhờ vậy nhiều lệnh có thể chạy cùng lúc và mỗi trả lời được ghép đúng. Các dòng bắt đầu bằng * là dữ liệu không gắn thẻ.",Tags:"Thẻ","Match replies to commands":"Ghép trả lời với lệnh","Open the Inbox":"Mở hộp thư đến","SELECT a folder":"SELECT một thư mục","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX mở thư mục. Máy chủ báo số thư, các cờ nó hỗ trợ và thư chưa đọc đầu tiên, rồi xác nhận thư mục đã mở ở chế độ đọc-ghi.","First unread":"Thư chưa đọc đầu",Access:"Quyền truy cập","Read a Message":"Đọc một thư","FETCH, and the \\Seen flag":"FETCH và cờ \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] tải thư 2 (ba đoạn TCP). Việc đó đặt cờ \\Seen của nó trên máy chủ, nên trên điện thoại của Bob nó cũng hiện là đã đọc, và thư vẫn nằm đó.","Flag set":"Đã đặt cờ","\\Seen (on the server)":"\\Seen (trên máy chủ)","STILL ON SERVER · \\SEEN":"VẪN TRÊN MÁY CHỦ · \\SEEN","Wait for New Mail":"Chờ thư mới","IDLE: the server pushes":"IDLE: máy chủ đẩy về","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE bảo máy chủ “báo cho tôi khi có gì thay đổi”. Khoảng 42 giây sau thư của Alice đến và máy chủ đẩy ngay “* 3 EXISTS”. Ứng dụng kết thúc IDLE bằng DONE và có thể tải thư mới.","Server says":"Máy chủ báo","* 3 EXISTS (new mail)":"* 3 EXISTS (thư mới)","Ended by":"Kết thúc bằng","NEW MAIL ARRIVED":"CÓ THƯ MỚI","a1 LOGIN (user and password)":"a1 LOGIN (người dùng và mật khẩu)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, thư 3,216 byte, rồi a3 OK FETCH completed","Transferring Files":"Truyền tệp","FTP command":"Lệnh FTP","FTP reply":"Trả lời FTP","File data":"Dữ liệu tệp","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP chuyển tệp giữa máy khách và máy chủ. Nó khác thường ở chỗ dùng hai kết nối TCP: một cho lệnh và trả lời, và một kết nối mới cho mỗi tệp hoặc danh sách. Nó có từ đầu thập niên 1970 và gửi mọi thứ, kể cả mật khẩu, dưới dạng văn bản thường.","21 control, data varies":"21 điều khiển, dữ liệu thay đổi",Connections:"Kết nối","Control + one per transfer":"Điều khiển + một mỗi lần truyền",Encryption:"Mã hóa","None (plain text)":"Không (văn bản thường)","Safer options":"Lựa chọn an toàn hơn","SFTP, or FTPS (FTP + TLS)":"SFTP, hoặc FTPS (FTP + TLS)","File downloaded":"Đã tải tệp về","Two connections, no encryption":"Hai kết nối, không mã hóa","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Lệnh đi qua kết nối điều khiển, tệp đi qua kết nối dữ liệu riêng, và việc đóng kết nối đó đánh dấu hết tệp. Ai trên đường đi cũng có thể đọc mật khẩu và tệp, vì thế ngày nay người ta dùng SFTP hoặc FTPS.","2 (control + data)":"2 (điều khiển + dữ liệu)",File:"Tệp","4,000 bytes, 3 segments":"4,000 byte, 3 đoạn",Password:"Mật khẩu","Sent in plain text":"Gửi dạng văn bản thường","Use instead":"Hãy dùng","SFTP or FTPS":"SFTP hoặc FTPS","Control Connection":"Kết nối điều khiển","Port 21, plain text":"Cổng 21, văn bản thường","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Ứng dụng FTP mở một kết nối TCP tới ftp.example.com trên cổng 21. Kết nối điều khiển này mang lệnh và trả lời cho cả phiên. Máy chủ chào bằng 220. Giống SMTP, mọi trả lời bắt đầu bằng mã ba chữ số.","USER and PASS, readable by anyone":"USER và PASS, ai cũng đọc được","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Ứng dụng gửi USER, máy chủ xin mật khẩu bằng 331, và PASS gửi nó đi. Không có gì được mã hóa, nên tên người dùng và mật khẩu đi qua mọi mạng trên đường dưới dạng văn bản đọc được.","Visible to":"Ai thấy được","Anyone on the path":"Bất kỳ ai trên đường đi","PASSWORD IN PLAIN TEXT":"MẬT KHẨU DẠNG VĂN BẢN THƯỜNG","Passive Mode":"Chế độ thụ động","The server names a data port":"Máy chủ chỉ định cổng dữ liệu","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I xin một bản sao nhị phân từng byte. PASV xin máy chủ mở một cổng cho kết nối dữ liệu. Câu trả lời mã hóa địa chỉ và cổng thành sáu con số: 195 × 256 + 149 = cổng 50069. Laptop kết nối ra ngoài, cách này đi qua được NAT.","Data port":"Cổng dữ liệu","Active mode":"Chế độ chủ động","Server dials in: NAT blocks":"Máy chủ gọi vào: NAT chặn","Data Connection":"Kết nối dữ liệu","A second TCP connection":"Kết nối TCP thứ hai","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Ứng dụng mở kết nối TCP thứ hai, tới cổng 50069, và xin tệp trên kết nối điều khiển bằng RETR. Máy chủ trả lời 150 ở đó và bắt đầu gửi tệp qua kết nối mới.","Data to":"Dữ liệu tới","The File Arrives":"Tệp đến nơi","Closing the connection ends it":"Đóng kết nối là kết thúc","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"4,000 byte đến trong 3 đoạn TCP. FTP không ghi độ dài trong chính dữ liệu: máy chủ đóng kết nối dữ liệu để đánh dấu hết tệp. Khi laptop đã xác nhận tất cả, máy chủ xác nhận bằng 226 trên kết nối điều khiển.","report.pdf, 4,000 bytes":"report.pdf, 4,000 byte","End of file":"Hết tệp","Data connection closed":"Đã đóng kết nối dữ liệu","3 SEGMENTS":"3 ĐOẠN","4,000 bytes, readable by anyone":"4,000 byte, ai cũng đọc được","end of file:":"hết tệp:","data connection closed":"đã đóng kết nối dữ liệu",Quit:"Thoát","Close the control connection":"Đóng kết nối điều khiển","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT kết thúc phiên và máy chủ chào tạm biệt bằng 221. Với mọi thứ nhạy cảm, SFTP (một giao thức khác, chạy trên SSH) hoặc FTPS (FTP bên trong TLS) làm cùng việc đó có mã hóa.","Encrypted cousins":"Họ hàng có mã hóa","FTP data":"Dữ liệu FTP","The file itself, unencrypted: anyone on the path could read it.":"Chính tệp đó, không mã hóa: ai trên đường đi cũng đọc được.","Secure Remote Login":"Đăng nhập từ xa an toàn","Plain setup":"Thiết lập dạng rõ","From laptop":"Từ laptop","From server":"Từ máy chủ","Some packets not shown":"Không hiện một số gói","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH cho bạn một kết nối mã hóa và xác thực tới một máy tính khác, để chạy lệnh trên đó, sao chép tệp (SFTP, scp) hoặc chuyển các kết nối khác. Máy chủ chứng minh nó là ai bằng khóa máy chủ; bạn chứng minh bạn là ai bằng cặp khóa hoặc mật khẩu.","Server proves":"Máy chủ chứng minh","Host key (known_hosts)":"Khóa máy chủ (known_hosts)","You prove":"Bạn chứng minh","Key pair or password":"Cặp khóa hoặc mật khẩu","Logged in securely":"Đã đăng nhập an toàn","Encrypted from the key exchange on":"Mã hóa từ lúc trao đổi khóa","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Hai bên thỏa thuận thuật toán, tạo khóa chung bằng một trao đổi lai hậu lượng tử, và máy chủ chứng minh danh tính bằng khóa máy chủ. Alice chứng minh danh tính của cô bằng cách ký với khóa riêng chưa bao giờ rời laptop, rồi gõ một lệnh, mỗi phím một gói.",Login:"Đăng nhập","Ed25519 key, no password":"Khóa Ed25519, không mật khẩu","Say Hello":"Chào hỏi","Versions, in plain text":"Phiên bản, dạng văn bản thường","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice chạy “ssh alice@server.example.com”. Sau bắt tay TCP trên cổng 22, mỗi bên gửi một dòng văn bản thường nêu phiên bản giao thức SSH (2.0) và phần mềm của mình. Mọi thứ khác trong SSH đều là nhị phân.",VERSION:"PHIÊN BẢN","Agree on Algorithms":"Thỏa thuận thuật toán","KEXINIT lists, first match wins":"Danh sách KEXINIT, khớp đầu tiên thắng","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Mỗi bên gửi một KEXINIT liệt kê mọi thuật toán nó hỗ trợ, theo thứ tự ưu tiên, cho trao đổi khóa, khóa máy chủ, mã hóa, toàn vẹn và nén. Ở mỗi loại, thuật toán đầu tiên trong danh sách của laptop mà máy chủ cũng hỗ trợ sẽ được chọn.","Host key":"Khóa máy chủ","server’s algorithm lists":"danh sách thuật toán của máy chủ","in order of preference":"theo thứ tự ưu tiên","laptop’s algorithm lists":"danh sách thuật toán của laptop","Key Exchange":"Trao đổi khóa","Shared keys, and a host key check":"Khóa chung và kiểm tra khóa máy chủ","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Laptop gửi nửa phần của nó trong một trao đổi lai: một khóa Streamlined NTRU Prime, chọn để chống lại máy tính lượng tử tương lai, cộng một khóa X25519. Máy chủ trả lời bằng nửa phần của nó, khóa máy chủ và một chữ ký trên cuộc trao đổi. NEWKEYS bật mã hóa.",Hybrid:"Lai","Matches known_hosts":"Khớp với known_hosts","First visit":"Lần đầu ghé","ssh asks you to confirm":"ssh hỏi bạn xác nhận","public keys":"khóa công khai","its half, its host key":"nửa phần của nó, khóa máy chủ","and a signature":"và một chữ ký","HOST KEY MATCHES KNOWN_HOSTS":"KHÓA MÁY CHỦ KHỚP KNOWN_HOSTS","Log In with a Key":"Đăng nhập bằng khóa","Sign, don’t send a secret":"Ký, không gửi bí mật","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Máy chủ liệt kê các cách đăng nhập nó chấp nhận. Laptop đưa ra khóa công khai của Alice, và máy chủ nói nó sẽ chấp nhận. Rồi laptop ký phiên này bằng khóa riêng, khóa không bao giờ rời laptop. Máy chủ kiểm tra chữ ký với authorized_keys.",Methods:"Phương thức",Key:"Khóa","Ed25519, private stays here":"Ed25519, khóa riêng ở lại đây","Checked with":"Kiểm tra bằng","AUTH FAILURE":"AUTH THẤT BẠI","OFFER KEY":"ĐƯA RA KHÓA","alice’s public key":"khóa công khai của alice","would you accept it?":"bạn có chấp nhận không?","yes, that key":"có, khóa đó","is in authorized_keys":"nằm trong authorized_keys",SIGNED:"ĐÃ KÝ","same key, plus a signature":"cùng khóa, thêm một chữ ký","made with the private key":"tạo bằng khóa riêng",SUCCESS:"THÀNH CÔNG","logged in":"đã đăng nhập","Open a Session":"Mở một phiên","Channels inside one connection":"Các kênh trong một kết nối","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Một kết nối SSH có thể mang nhiều kênh: một shell, truyền tệp, cổng được chuyển tiếp. Laptop mở một kênh phiên, rồi xin một terminal và một shell (không hiện), và máy chủ gửi lời chào và dấu nhắc.",Channel:"Kênh",session:"session","Then asks for":"Sau đó xin","A terminal and a shell":"Một terminal và một shell","Also possible":"Cũng có thể","SFTP, port forwarding":"SFTP, chuyển tiếp cổng","CHANNEL OPEN":"MỞ KÊNH","open a channel:":"mở một kênh:",CONFIRMED:"ĐÃ XÁC NHẬN","channel open":"kênh đã mở","Type a Command":"Gõ một lệnh","Every key is a packet":"Mỗi phím là một gói","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice gõ pwd. Mỗi phím đi ngay trong một gói mã hóa riêng, và máy chủ gửi lại ký tự để hiển thị (tiếng vọng). Từ bản 9.5, OpenSSH gửi phím theo nhịp 20 ms và thêm các gói mồi, nên khó đọc nhịp gõ phím từ thời gian hơn.","Per key":"Mỗi phím","1 packet, 90 bytes":"1 gói, 90 byte",Echo:"Tiếng vọng","Sent back by the server":"Máy chủ gửi lại",Timing:"Thời gian","20 ms beat plus decoys":"Nhịp 20 ms cộng gói mồi",ECHO:"TIẾNG VỌNG",ENTER:"ENTER","Enter key":"Phím Enter",OUTPUT:"KẾT QUẢ","EACH KEY IS ITS OWN PACKET":"MỖI PHÍM MỘT GÓI RIÊNG","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Máy khách: KEX_ECDH_INIT (khóa công khai sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Máy chủ: KEX_ECDH_REPLY (khóa máy chủ, nửa phần của nó, chữ ký)","Encrypted (len=44): service request, ssh-userauth":"Đã mã hóa (len=44): yêu cầu dịch vụ, ssh-userauth","Encrypted (len=44): service accept":"Đã mã hóa (len=44): chấp nhận dịch vụ","Encrypted (len=68): login with method none":"Đã mã hóa (len=68): đăng nhập với phương thức none","Encrypted (len=52): try publickey,password":"Đã mã hóa (len=52): thử publickey,password","Encrypted (len=140): offer public key":"Đã mã hóa (len=140): đưa ra khóa công khai","Encrypted (len=100): public key OK":"Đã mã hóa (len=100): khóa công khai OK","Encrypted (len=308): public key + signature":"Đã mã hóa (len=308): khóa công khai + chữ ký","Encrypted (len=28): login success":"Đã mã hóa (len=28): đăng nhập thành công","Encrypted (len=52): channel open: session":"Đã mã hóa (len=52): mở kênh: session","Encrypted (len=44): channel open confirmed":"Đã mã hóa (len=44): xác nhận mở kênh","Encrypted (len=36): keystroke":"Đã mã hóa (len=36): phím bấm","Encrypted (len=36): echo":"Đã mã hóa (len=36): tiếng vọng","Encrypted (len=36): keystroke (Enter)":"Đã mã hóa (len=36): phím bấm (Enter)","Encrypted (len=132): output and a new prompt":"Đã mã hóa (len=132): kết quả và dấu nhắc mới","Packet length":"Độ dài gói","Bytes after this field.":"Số byte sau trường này.","Padding length":"Độ dài đệm","Random padding brings the packet to a multiple of 8 bytes.":"Đệm ngẫu nhiên đưa gói về bội số của 8 byte.",Cookie:"Cookie","Host keys":"Khóa máy chủ","Ciphers, out":"Bộ mã hóa, chiều đi","Ciphers, in":"Bộ mã hóa, chiều về","MACs, out":"MAC, chiều đi","MACs, in":"MAC, chiều về","Compression, out":"Nén, chiều đi","Compression, in":"Nén, chiều về","Languages, out":"Ngôn ngữ, chiều đi","Languages, in":"Ngôn ngữ, chiều về","First packet follows":"Gói đầu tiên theo sau",Reserved:"Dự trữ","Public keys":"Khóa công khai","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 byte (sntrup761 1,158 + X25519 32)","51 bytes: ssh-ed25519 public key":"51 byte: khóa công khai ssh-ed25519","Server’s half":"Nửa phần của máy chủ","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 byte (bản mã sntrup761 1,039 + X25519 32)",Signature:"Chữ ký","83 bytes: ssh-ed25519 signature over the exchange":"83 byte: chữ ký ssh-ed25519 trên cuộc trao đổi","From the next packet on, this side encrypts.":"Từ gói tiếp theo, phía này mã hóa.","SSH · encrypted packet":"SSH · gói đã mã hóa","Encrypted packet":"Gói đã mã hóa","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Với chacha20-poly1305, ngay cả độ dài cũng được mã hóa; một thẻ 16 byte ở cuối để lộ mọi thay đổi.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): người dùng “alice”, dịch vụ “ssh-connection”, phương thức “none”","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): các phương thức có thể tiếp tục: “publickey,password”","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): phương thức “publickey”, không chữ ký, khóa công khai ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): cùng khóa ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): phương thức “publickey-hostbound-v00@openssh.com”, khóa, khóa máy chủ của server và một chữ ký","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): “session”, kênh 0, cửa sổ 2 MB, gói tối đa 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): kênh 0 đã mở","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “p”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “p”, gửi lại để hiển thị","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “w”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “w”, gửi lại để hiển thị","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “d”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, “d”, gửi lại để hiển thị","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 1 byte, ký tự về đầu dòng (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), kênh 0: 94 byte: một dòng mới, mã terminal của shell, “/home/alice” và dấu nhắc có màu","From browser":"Từ trình duyệt","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS đặt một kênh an toàn lên trên TCP. Nó chứng minh danh tính máy chủ bằng chứng chỉ, thỏa thuận khóa mới, rồi mã hóa và xác thực mọi thứ được gửi. HTTPS, email bảo mật và nhiều giao thức khác chạy bên trong nó. SSL là tên của người tiền nhiệm.",Sits:"Vị trí","Between TCP and the app":"Giữa TCP và ứng dụng","OSI layer":"Tầng OSI","Often placed at 6":"Thường xếp ở tầng 6",Current:"Hiện tại",Retired:"Đã ngừng","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 và 3, TLS 1.0 và 1.1","The app’s own (443, 993 …)":"Cổng của ứng dụng (443, 993 …)","Secure from start to finish":"An toàn từ đầu đến cuối","One round trip to set up":"Một lượt khứ hồi để thiết lập","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Một lượt khứ hồi đã thỏa thuận một phiên bản, một bộ mã hóa và một khóa lai hậu lượng tử. Chuỗi chứng chỉ chứng minh máy chủ là ai, và mọi byte sau Server Hello đều được mã hóa và xác thực, cho đến close_notify. Nhấn XEM LẠI để xem lại.","1 round trip":"1 lượt khứ hồi","Everything the browser supports":"Mọi thứ trình duyệt hỗ trợ","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Sau bắt tay TCP, trình duyệt liệt kê những gì nó làm được: phiên bản TLS, bộ mã hóa và phần khóa cho các nhóm nó dự đoán, gồm cả kiểu lai hậu lượng tử X25519MLKEM768. Nó cũng nêu tên trang (SNI) và các giao thức nó nói (ALPN).",Versions:"Phiên bản","versions, ciphers, key shares":"phiên bản, bộ mã hóa, phần khóa","Choices made, keys computed":"Đã chọn, đã tính khóa","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Máy chủ chọn TLS 1.3, bộ mã hóa và nhóm lai, rồi gửi phần khóa của nó. Từ hai phần khóa, cả hai bên tính ra cùng một bí mật mà nó không bao giờ đi qua mạng. Mọi thứ sau thông điệp này đều được mã hóa.",Group:"Nhóm","From here on":"Từ đây trở đi","its key share":"phần khóa của nó","SHARED SECRET COMPUTED":"ĐÃ TÍNH BÍ MẬT CHUNG",Certificate:"Chứng chỉ","Who the server is, proven":"Máy chủ là ai, đã chứng minh","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Giờ đã mã hóa, chuyến bay tiếp tục: giao thức được chọn (http/1.1), chuỗi chứng chỉ, một chữ ký tạo bằng khóa riêng của chứng chỉ, và Finished.",Chain:"Chuỗi","Site → intermediate → root":"Trang → trung gian → gốc","Proves the private key":"Chứng minh khóa riêng",Checked:"Kiểm tra","Name, dates, trusted root":"Tên, ngày, gốc tin cậy","encrypted: http/1.1, certificates,":"đã mã hóa: http/1.1, chứng chỉ,","signature, Finished":"chữ ký, Finished","CHAIN LEADS TO A TRUSTED ROOT":"CHUỖI DẪN TỚI GỐC TIN CẬY","One round trip, then data":"Một lượt khứ hồi, rồi dữ liệu","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Trình duyệt gửi Finished của nó: một giá trị kiểm tra trên mọi thứ hai bên đã nói, tính bằng bí mật mới, nên mọi can thiệp vào các lời chào sẽ lộ ra. TLS 1.3 cần một lượt khứ hồi trước khi dữ liệu chạy; TLS 1.2 cần hai.",Covers:"Bao phủ","The whole handshake":"Toàn bộ bắt tay","For old middleboxes":"Cho thiết bị trung gian cũ","check value over":"giá trị kiểm tra trên","the whole handshake":"toàn bộ bắt tay","Encrypted Data":"Dữ liệu đã mã hóa","Records, tags and tickets":"Bản ghi, thẻ và vé","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"Giờ HTTP đi trong các bản ghi mã hóa, mỗi bản ghi có thẻ 16 byte để lộ mọi thay đổi. Máy chủ còn gửi hai vé phiên: lần sau trình duyệt có thể tiếp tục bằng một vé và bỏ qua chứng chỉ.","Per record":"Mỗi bản ghi","22 bytes of overhead":"22 byte phụ phí","2, for resuming later":"2, để tiếp tục sau",Visible:"Thấy được","IPs, SNI, sizes, timing":"IP, SNI, kích thước, thời gian","2 session tickets":"2 vé phiên","for resuming later":"để tiếp tục sau",Closing:"Đóng","close_notify, then TCP":"close_notify, rồi TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Sau 75 giây không hoạt động, máy chủ đóng kết nối. Trước tiên nó gửi cảnh báo close_notify, được mã hóa như mọi thứ khác, để trình duyệt biết dữ liệu kết thúc có chủ đích chứ không bị kẻ tấn công cắt ngang. Rồi TCP đóng như thường lệ.",Alert:"Cảnh báo",Why:"Tại sao","Shows nothing was cut off":"Cho thấy không có gì bị cắt","TCP FIN from both sides":"TCP FIN từ cả hai bên","alert: close_notify":"cảnh báo: close_notify",encrypted:"đã mã hóa","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ đã mã hóa)","Encrypted handshake (continued)":"Bắt tay đã mã hóa (tiếp)","Encrypted handshake (certificate, verify, Finished)":"Bắt tay đã mã hóa (chứng chỉ, xác minh, Finished)","Application Data (inside: close_notify alert)":"Application Data (bên trong: cảnh báo close_notify)","Alert: close_notify (the data ends here, on purpose)":"Cảnh báo: close_notify (dữ liệu kết thúc ở đây, có chủ đích)"},r={"Two-way web messaging":"Nhắn tin web hai chiều","Browser video calls":"Gọi video trên trình duyệt","HTTP/3 over UDP":"HTTP/3 qua UDP","Routing between networks":"Định tuyến giữa các mạng","Address setup, neighbour discovery":"Thiết lập địa chỉ, tìm láng giềng","Private DNS lookups":"Tra cứu DNS riêng tư","Signed DNS answers":"Câu trả lời DNS có chữ ký","Network Time Protocol":"Network Time Protocol","Joining a network (WPA2)":"Vào một mạng (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"Wi-Fi doanh nghiệp 802.1X","Hotel and café Wi-Fi logins":"Đăng nhập Wi-Fi nơi công cộng","Windows file sharing":"Chia sẻ tệp Windows","Forward proxy and CONNECT":"Proxy chuyển tiếp và CONNECT","Socket Secure proxy":"Proxy Socket Secure","TLS offloading":"Giảm tải TLS","A modern VPN":"Một VPN hiện đại","IKEv2 and ESP":"IKEv2 và ESP","Industrial control (OT)":"Điều khiển công nghiệp (OT)",Proxy:"Proxy","App Server":"Máy chủ ứng dụng","File Server":"Máy chủ tệp","ISP Router":"Router của ISP","Transit Router":"Router trung chuyển","Hosting Router":"Router của nhà lưu trữ","Their Router":"Router bên kia","Their Laptop":"Laptop bên kia",Transit:"Trung chuyển",Hosting:"Lưu trữ","The router itself.":"Chính router.","Mail in Sync":"Thư đồng bộ","Live Updates":"Cập nhật trực tiếp","From the browser":"Từ trình duyệt","From the server":"Từ máy chủ","The WebSocket Protocol":"The WebSocket Protocol","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"WebSocket giữ một kết nối mở giữa trang web và máy chủ, để bên nào cũng có thể gửi tin bất cứ lúc nào: chat, tỷ số trực tiếp, game, tài liệu dùng chung. Nó bắt đầu như một yêu cầu HTTP thông thường xin nâng cấp; sau đó tin nhắn đi trong các khung nhỏ với tiêu đề chỉ vài byte.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Một yêu cầu HTTP (Upgrade)","Frames both ways, any time":"Khung hai chiều, bất cứ lúc nào","Frame header":"Tiêu đề khung","2–14 bytes":"2–14 byte","One request, then messages":"Một yêu cầu, rồi tin nhắn","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Một yêu cầu HTTP đã biến một kết nối TCP bình thường thành kênh hai chiều. Từ đó mỗi tin nhắn chỉ tốn vài byte tiêu đề, và máy chủ có thể gửi bất cứ khi nào có gì để nói. Nhấn XEM LẠI để xem lại.","GET with Upgrade, then 101":"GET với Upgrade, rồi 101","Smallest frame":"Khung nhỏ nhất","2 bytes (a ping)":"2 byte (một ping)","Server push":"Máy chủ đẩy","Any time, unasked":"Bất cứ lúc nào, không cần hỏi","Real sites":"Trang thật","wss:// (inside TLS)":"wss:// (bên trong TLS)","TCP to the server, as for HTTP":"TCP tới máy chủ, như với HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'Trang chat đã mở, tải từ www.example.com. Script của nó gọi new WebSocket("ws://www.example.com/chat"), và trình duyệt bắt đầu bằng một kết nối TCP bình thường tới cổng 80. (Trang thật dùng wss://, tức cùng thứ đó bên trong TLS; ws:// thường cho bạn đọc được mọi byte.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Xin nâng cấp","An HTTP request with Upgrade: websocket":"Yêu cầu HTTP có Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Trình duyệt gửi HTTP GET với Upgrade: websocket và Connection: Upgrade. Sec-WebSocket-Key là 16 byte ngẫu nhiên viết bằng base64, mà máy chủ phải trả lời đúng. Trình duyệt cũng đề nghị nén tin nhắn (permessage-deflate).","Asks for":"Xin","16 random bytes, base64":"16 byte ngẫu nhiên, base64",UPGRADE:"UPGRADE","Switch Protocols":"Chuyển giao thức","101: from now on, WebSocket":"101: từ giờ là WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Máy chủ trả lời 101 Switching Protocols. Sec-WebSocket-Accept của nó là khóa cộng một chuỗi cố định, băm bằng SHA-1 và viết bằng base64: bằng chứng nó hiểu yêu cầu. Nó không nhận nén, nên tin nhắn đi dạng văn bản thường. HTTP đã xong trên kết nối này; từ giờ cả hai bên gửi khung WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 của khóa + chuỗi cố định",Compression:"Nén","Offered, not taken":"Đã đề nghị, không nhận","NOW A WEBSOCKET":"GIỜ LÀ WEBSOCKET","Small frames, from either side":"Khung nhỏ, từ cả hai bên",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Bạn gửi "Hello": tiêu đề 2 byte, khóa che 4 byte và 5 byte đã che, tổng cộng 11 byte thay vì cả một yêu cầu HTTP. Vài giây sau máy chủ đẩy tin của Bob mà không ai hỏi: kết nối vẫn mở, nên nó làm được. Khung từ trình duyệt luôn được che; khung từ máy chủ thì không bao giờ.',"You send":"Bạn gửi","Server pushes":"Máy chủ đẩy",'"bob: hi there"':'"bob: hi there"',Masked:"Được che","From the browser only":"Chỉ từ trình duyệt",TEXT:"TEXT",masked:"đã che",unasked:"không cần hỏi","Keeping It Alive":"Giữ kết nối sống","Ping and pong":"Ping và pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Sau nửa phút không có gì để nói, máy chủ gửi một ping, để router và tường lửa trên đường không quên kết nối đang im lặng. Trình duyệt tự trả lời bằng pong; script của trang không thấy cả hai.","Opcode 9, from either side":"Opcode 9, từ bên nào cũng được",Pong:"Pong","Opcode 10, by itself":"Opcode 10, tự động","How often":"Bao lâu một lần","Up to the server (30 s)":"Do máy chủ (30 s)","A close frame each way":"Mỗi chiều một khung đóng","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Khi bạn rời chat, script của trang đóng WebSocket với mã 1000 (đóng bình thường): trình duyệt gửi khung đóng và máy chủ trả lời bằng khung của nó. Rồi máy chủ đóng kết nối TCP. (Chỉ đóng tab sẽ gửi 1001, rời đi.)",Opcode:"Opcode","8 (close)":"8 (đóng)","1000 (normal closure)":"1000 (đóng bình thường)","TCP closes":"TCP đóng",CLOSE:"ĐÓNG","1000 normal closure":"1000 đóng bình thường","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: khung này là cả một tin nhắn. Opcode cho biết nó mang gì.","Mask, length":"Che, độ dài","Everything a browser sends is masked.":"Mọi thứ trình duyệt gửi đều được che.","Masking key":"Khóa che","Chosen at random for every frame.":"Chọn ngẫu nhiên cho mỗi khung.",Payload:"Payload","Each byte XORed with the masking key in turn; the server XORs it back.":"Mỗi byte lần lượt XOR với khóa che; máy chủ XOR lại.","A server never masks what it sends.":"Máy chủ không bao giờ che những gì nó gửi.","Status code":"Mã trạng thái","Joining a Network":"Vào một mạng","From the access point":"Từ điểm truy cập","4-way handshake":"Bắt tay 4 bước","Access Point":"Điểm truy cập","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) với WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Wi-Fi mang mạng qua sóng radio. Trước khi gửi được gì, thiết bị phải tìm mạng, vào mạng và chứng minh nó biết mật khẩu. Với WPA2-Personal, bằng chứng đó là bắt tay 4 bước: bốn thông điệp ngắn biến mật khẩu thành khóa mã hóa mới, mà mật khẩu không bao giờ đi qua sóng.","Data Link (Layer 2)":"Liên kết dữ liệu (tầng 2)",Standard:"Chuẩn",Joining:"Vào mạng","Probe, authenticate, associate":"Probe, xác thực, liên kết","Keys from":"Khóa từ","The 4-way handshake":"Bắt tay 4 bước",Connected:"Đã kết nối","Eleven frames to a secure link":"Mười một khung tới một liên kết an toàn","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"Laptop tìm thấy mạng, vào mạng qua hai thủ tục và chứng minh nó biết mật khẩu bằng một bắt tay bốn thông điệp, mà không hề gửi mật khẩu. Mọi thứ sau đó được mã hóa bằng khóa chỉ dành riêng cho kết nối này. Nhấn XEM LẠI để xem lại.","Frames to join":"Khung để vào mạng","Password sent":"Mật khẩu đã gửi",Never:"Không bao giờ","Session keys":"Khóa phiên","New every time":"Mới mỗi lần",Next:"Tiếp theo","DHCP, for an IP address":"DHCP, để có địa chỉ IP","Find the Network":"Tìm mạng","A beacon, then a probe":"Một beacon, rồi một probe",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Khoảng mười lần mỗi giây, Wi-Fi của router gửi một beacon: đây là "HomeNet", bảo vệ bằng WPA2, trên kênh 36. Laptop có thể chỉ chờ nghe một beacon; để nhanh hơn, nó còn hỏi to bằng probe request, và điểm truy cập trả lời bằng probe response.',"WPA2-Personal (password)":"WPA2-Personal (mật khẩu)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · kênh 36",PROBE:"PROBE","any networks here?":"có mạng nào ở đây không?","PROBE RESPONSE":"PROBE RESPONSE","Join the Network":"Vào mạng","Two formalities: hello, then join":"Hai thủ tục: chào, rồi vào","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"Xác thực Open System cho bất kỳ ai tới bước này: chưa cần mật khẩu. Rồi laptop xin liên kết, nhắc lại kiểu bảo mật đã chọn (CCMP, có mật khẩu), và điểm truy cập cấp cho nó ID liên kết 1. Laptop đã kết nối, nhưng thứ duy nhất nó được gửi là cuộc bắt tay tiếp theo.",Authentication:"Xác thực","Open System (no password)":"Open System (không mật khẩu)","Association ID":"ID liên kết","Allowed so far":"Được phép đến giờ",success:"thành công",ASSOCIATE:"LIÊN KẾT",'join "HomeNet"':'vào "HomeNet"',"CCMP, password":"CCMP, mật khẩu",ASSOCIATED:"ĐÃ LIÊN KẾT","association ID 1":"ID liên kết 1","Messages 1 and 2":"Thông điệp 1 và 2","The 4-way handshake: nonces":"Bắt tay 4 bước: các nonce","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Cả hai bên đã có cùng một khóa, tính từ mật khẩu và tên mạng (PMK); nó không bao giờ đi qua sóng. Điểm truy cập gửi một số ngẫu nhiên, ANonce. Laptop gửi số của mình, SNonce, kèm một giá trị kiểm tra (MIC). Từ PMK, hai nonce và cả hai địa chỉ MAC, mỗi bên giờ tính ra cùng các khóa phiên.","Shared key":"Khóa chung","PMK, from the password":"PMK, từ mật khẩu",Exchanged:"Đã trao đổi","Two random nonces":"Hai nonce ngẫu nhiên","Worked out":"Tính ra","Session keys (PTK)":"Khóa phiên (PTK)","MESSAGE 1":"THÔNG ĐIỆP 1","MESSAGE 2":"THÔNG ĐIỆP 2","Messages 3 and 4":"Thông điệp 3 và 4","The 4-way handshake: keys":"Bắt tay 4 bước: các khóa","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Thông điệp 3 cho thấy điểm truy cập có cùng khóa (MIC của nó khớp) và mang theo khóa nhóm (GTK) cho quảng bá, đã mã hóa. Thông điệp 4 cho biết laptop đã sẵn sàng, và cả hai đầu bắt đầu mã hóa.","Group key":"Khóa nhóm","GTK, sent encrypted":"GTK, gửi dạng mã hóa",Install:"Cài đặt","Both ends at once":"Cả hai đầu cùng lúc","MESSAGE 3":"THÔNG ĐIỆP 3","group key, encrypted":"khóa nhóm, đã mã hóa","MESSAGE 4":"THÔNG ĐIỆP 4","keys installed":"đã cài khóa","Encrypted Now":"Giờ đã mã hóa","And what a listener could still do":"Và kẻ nghe lén vẫn làm được gì","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Giờ mọi khung dữ liệu đều được mã hóa, như khung đầu tiên này mang một DHCP Discover: ai ở gần chỉ thấy địa chỉ MAC và kích thước. Nhưng ai đã ghi lại bốn thông điệp bắt tay có thể đoán mật khẩu tại nhà, nhanh như máy tính của họ cho phép: một lần đoán đúng khi cho ra cùng MIC. Một mật khẩu dài, ngẫu nhiên khiến việc đó vô vọng; WPA3 loại bỏ điểm yếu này.","Others see":"Người khác thấy","MAC addresses, sizes, timing":"Địa chỉ MAC, kích thước, thời gian","Weak point":"Điểm yếu","Offline password guessing":"Đoán mật khẩu ngoại tuyến",Defence:"Phòng vệ","A long password, or WPA3":"Mật khẩu dài, hoặc WPA3","DHCP Discover inside":"Bên trong là DHCP Discover","ENCRYPTED FROM HERE ON":"MÃ HÓA TỪ ĐÂY TRỞ ĐI","QoS Data (encrypted)":"QoS Data (đã mã hóa)","Seen over the air, on Wi-Fi channel 36":"Thấy qua sóng, trên kênh Wi-Fi 36","Frame type":"Loại khung","Management, Beacon":"Quản lý, Beacon",Duration:"Thời lượng","Nobody acknowledges a broadcast, so nothing is booked.":"Không ai xác nhận quảng bá, nên không đặt chỗ gì.",Receiver:"Bên nhận","Broadcast: every device in range listens.":"Quảng bá: mọi thiết bị trong vùng phủ đều nghe.",Transmitter:"Bên phát","The access point.":"Điểm truy cập.","The access point’s own address: which network this is about.":"Địa chỉ của chính điểm truy cập: cho biết đây là mạng nào.","Lets the receiver spot a repeat when a frame is sent again.":"Giúp bên nhận nhận ra khung lặp lại khi một khung được gửi lại.","The access point’s clock; devices on the network keep theirs in step with it.":"Đồng hồ của điểm truy cập; các thiết bị trong mạng giữ đồng hồ của mình khớp với nó.","Beacon interval":"Chu kỳ beacon","A beacon goes out about ten times a second.":"Khoảng mười lần mỗi giây có một beacon.","0x0011: access point network, encrypted":"0x0011: mạng có điểm truy cập, đã mã hóa","Privacy bit set: joining takes a key.":"Bật bit riêng tư: vào mạng cần có khóa.","The network’s name.":"Tên của mạng.","Supported rates":"Tốc độ hỗ trợ","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Chỉ những tốc độ cũ nhất, chậm nhất; tốc độ nhanh nằm trong các phần tử sau.","DTIM count 0, period 1":"Bộ đếm DTIM 0, chu kỳ 1","Tells sleeping devices whether frames are waiting for them.":"Báo cho thiết bị đang ngủ biết có khung nào đang chờ chúng không.","Robust Security Network: how this network is protected.":"Robust Security Network: mạng này được bảo vệ thế nào.","Element ID, length":"ID phần tử, độ dài","48, 20 bytes":"48, 20 byte","Group cipher":"Mã hóa nhóm","Encrypts broadcasts, which every device on the network can read.":"Mã hóa quảng bá, thứ mọi thiết bị trong mạng đều đọc được.","Pairwise cipher":"Mã hóa theo cặp","Encrypts each device’s own traffic, with keys only it and the access point have.":"Mã hóa lưu lượng riêng của từng thiết bị, bằng khóa chỉ nó và điểm truy cập có.","Key management":"Quản lý khóa","1: PSK (a shared password)":"1: PSK (mật khẩu dùng chung)","More elements":"Phần tử khác","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Khả năng và thiết lập Wi-Fi 4, 5 và 6 (HT, VHT, HE: kênh 36, rộng 80 MHz), và phần bổ sung của nhà sản xuất.","Management, Probe Request":"Quản lý, Probe Request","The laptop’s Wi-Fi card.":"Card Wi-Fi của laptop.","empty (any network)":"trống (mạng nào cũng được)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Điểm truy cập nào cũng có thể trả lời. (Trước đây thiết bị hỏi tên từng mạng nó từng vào, khiến ai nghe cũng biết nó đã ở đâu.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Radio của laptop làm được gì: khả năng Wi-Fi 4, 5 và 6, và phần bổ sung của nhà sản xuất.","Management, Probe Response":"Quản lý, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Kênh được giữ chỗ bao lâu cho cuộc trao đổi này; các thiết bị khác chờ.","The radio this frame is for.":"Radio mà khung này gửi tới.","Authentication · Open System":"Xác thực · Open System","Management, Authentication":"Quản lý, Authentication",Algorithm:"Thuật toán","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Open: ai cũng tới được bước này. Mật khẩu được kiểm tra sau, trong bắt tay 4 bước.",Transaction:"Giao dịch","0 (success)":"0 (thành công)","Management, Association Request":"Quản lý, Association Request","Listen interval":"Chu kỳ nghe","10 beacons":"10 beacon","How often the laptop wakes to check for waiting frames when saving power.":"Khi tiết kiệm pin, laptop thức dậy bao lâu một lần để xem có khung đang chờ.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Radio của laptop làm được gì (Wi-Fi 4, 5 và 6), và phần bổ sung của nhà sản xuất.","Management, Association Response":"Quản lý, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Số của laptop tại điểm truy cập này (hai bit cao nhất luôn bật).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Thiết lập điểm truy cập dùng (Wi-Fi 4, 5 và 6), và phần bổ sung của nhà sản xuất.","Data, QoS Data":"Dữ liệu, QoS Data","0x02 (from the access point)":"0x02 (từ điểm truy cập)","Sent by the access point itself.":"Do chính điểm truy cập gửi.","QoS control":"Điều khiển QoS","Priority 7, the highest: the handshake goes first.":"Ưu tiên 7, cao nhất: bắt tay đi trước.",Organization:"Tổ chức","0x888e (802.1X authentication)":"0x888e (xác thực 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"Cái gì theo sau: đóng vai trò mà trường loại Ethernet đóng trên dây cáp.","Descriptor type":"Loại mô tả","Key information":"Thông tin khóa","0x008a: pairwise, ACK":"0x008a: theo cặp, ACK","ACK: the laptop must answer.":"ACK: laptop phải trả lời.","Key length":"Độ dài khóa","The pairwise key is 16 bytes (AES-128).":"Khóa theo cặp dài 16 byte (AES-128).","Replay counter":"Bộ đếm chống phát lại","Counts up with each message from the access point; an old one sent again is ignored.":"Tăng sau mỗi thông điệp từ điểm truy cập; thông điệp cũ gửi lại sẽ bị bỏ qua.","A random number from the access point.":"Một số ngẫu nhiên từ điểm truy cập.","Key IV":"IV khóa",zeros:"toàn số 0","Key RSC":"RSC khóa","No keys yet, so nothing to check with.":"Chưa có khóa, nên chưa có gì để kiểm tra.","Key data length":"Độ dài dữ liệu khóa","0x01 (to the access point)":"0x01 (tới điểm truy cập)","The access point itself.":"Chính điểm truy cập.","0x010a: pairwise, MIC":"0x010a: theo cặp, MIC","MIC: this message carries a check value.":"MIC: thông điệp này mang một giá trị kiểm tra.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Một số ngẫu nhiên từ laptop. Từ cả hai số, cả hai địa chỉ MAC và khóa sinh ra từ mật khẩu, mỗi bên tính ra cùng các khóa phiên.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Tính bằng khóa mới: chứng minh bên gửi biết mật khẩu và thông điệp không bị sửa.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: theo cặp, cài đặt, ACK, MIC, an toàn, dữ liệu khóa đã mã hóa","Install: start using the keys. The group key comes encrypted.":"Cài đặt: bắt đầu dùng khóa. Khóa nhóm được gửi dạng mã hóa.","Where the group key’s packet numbers start.":"Nơi bắt đầu số thứ tự gói của khóa nhóm.","Key data":"Dữ liệu khóa","Encrypted with a key from the handshake.":"Mã hóa bằng một khóa từ bắt tay.","The access point’s RSN element":"Phần tử RSN của điểm truy cập","GTK: the group key, for broadcasts":"GTK: khóa nhóm, cho quảng bá","0x030a: pairwise, MIC, secure":"0x030a: theo cặp, MIC, an toàn","Secure: the keys are in place.":"An toàn: khóa đã sẵn sàng.","CCMP · encrypted":"CCMP · đã mã hóa","0x41 (protected, to the access point)":"0x41 (được bảo vệ, tới điểm truy cập)","Protected: what follows the header is encrypted.":"Được bảo vệ: phần sau tiêu đề đã được mã hóa.","Where the access point should pass it on to: everyone on the network.":"Điểm truy cập nên chuyển nó cho ai: mọi người trong mạng.","CCMP header":"Tiêu đề CCMP","packet number 1, key 0":"số gói 1, khóa 0","Counts up with every frame; one seen before is thrown away.":"Tăng theo mỗi khung; khung đã thấy rồi sẽ bị bỏ.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: một gói IPv4","Shows any change to the frame.":"Để lộ mọi thay đổi trên khung.","Safer Wi-Fi":"Wi-Fi an toàn hơn","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 là chuẩn bảo mật Wi-Fi hiện tại. Chế độ Personal của nó giữ mật khẩu dùng chung đơn giản nhưng thay đổi cách kiểm tra: SAE, một trao đổi mật khẩu mà không bản ghi nào tấn công ngoại tuyến được, cấp cho mỗi kết nối một khóa mới. Nó cũng bắt buộc khung quản lý được bảo vệ.","Password check":"Kiểm tra mật khẩu",Required:"Bắt buộc","Protected management frames":"Khung quản lý được bảo vệ",Since:"Từ năm","Connected with WPA3":"Đã kết nối bằng WPA3","Same password, better protocol":"Cùng mật khẩu, giao thức tốt hơn","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"Laptop và điểm truy cập chứng minh với nhau rằng chúng biết mật khẩu mà không cho ai cách thử đoán ngoại tuyến, rồi tạo khóa mới đúng như WPA2. Nhấn XEM LẠI để xem lại.","SAE frames":"Khung SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 khung EAPOL-Key","Offline guessing":"Đoán ngoại tuyến","Not possible":"Không thể","Forged disconnects":"Ngắt kết nối giả mạo",Ignored:"Bị bỏ qua","A WPA3 Network":"Một mạng WPA3","The beacon asks for SAE":"Beacon yêu cầu SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"Beacon trông giống của WPA2 với hai thay đổi trong phần tử RSN: quản lý khóa là SAE thay vì PSK, và khung quản lý được bảo vệ là bắt buộc. Mọi người vẫn dùng một mật khẩu chung.","Management frames":"Khung quản lý","Protected (required)":"Được bảo vệ (bắt buộc)","Still one for everyone":"Vẫn một cho mọi người","SAE Commit":"SAE Commit","Each side commits to the password":"Mỗi bên cam kết với mật khẩu","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Thay cho xác thực Open System, hai bên chạy SAE, một trao đổi mật khẩu ngang hàng. Mỗi bên chọn một bí mật ngẫu nhiên và gửi một vô hướng và một phần tử tính từ bí mật đó và mật khẩu. Mật khẩu ở hai bên giống nhau, bí mật thì không, nên mỗi kết nối kết thúc với một khóa mới.","19 (256-bit curve)":"19 (đường cong 256 bit)","Each sends":"Mỗi bên gửi","A scalar and an element":"Một vô hướng và một phần tử",Replaces:"Thay thế","Open System authentication":"Xác thực Open System",COMMIT:"COMMIT","scalar + element":"vô hướng + phần tử","SAE Confirm":"SAE Confirm","Proof, without the password":"Bằng chứng, không cần mật khẩu","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Giờ mỗi bên tính ra khóa chung và gửi một confirm, giá trị mà chỉ ai có đúng mật khẩu mới tạo ra được. Ghi lại cả bốn khung SAE không giúp kẻ tấn công thử đoán tại nhà: mỗi lần đoán cần một trao đổi trực tiếp với điểm truy cập, nơi có thể làm chậm hoặc chặn họ.","A new key (PMK) each time":"Mỗi lần một khóa mới (PMK)",Guessing:"Đoán","Live only, never offline":"Chỉ trực tiếp, không bao giờ ngoại tuyến","Password leaks":"Lộ mật khẩu","Past traffic stays safe":"Lưu lượng cũ vẫn an toàn",CONFIRM:"CONFIRM","proof of the key":"bằng chứng về khóa","Join, Handshake":"Vào mạng, bắt tay","Then the 4-way handshake, as in WPA2":"Rồi bắt tay 4 bước, như WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"Liên kết vẫn như trước, nhắc lại lựa chọn SAE. Bắt tay 4 bước theo sau là của WPA2, bắt đầu từ khóa SAE vừa tạo, chỉ khác là thông điệp 3 còn mang IGTK, một khóa ký các khung quản lý quảng bá.","Message 3 adds":"Thông điệp 3 thêm","Why It’s Safer":"Vì sao an toàn hơn","Forged disconnects stop working":"Ngắt kết nối giả mạo hết tác dụng","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Với WPA2, bất kỳ ai trong vùng phủ đều có thể giả một khung “ngắt kết nối” và đá thiết bị khỏi mạng, thường để ghi lại bắt tay khi nó vào lại. WPA3 bắt buộc khung quản lý được bảo vệ, nên ngắt kết nối giả mạo bị bỏ qua. Nhiều router còn có chế độ chuyển tiếp cho thiết bị WPA2 vào cùng; những thiết bị đó vẫn mang điểm yếu của WPA2.",Protected:"Được bảo vệ","Disconnects, other management":"Ngắt kết nối, quản lý khác","WPA2/3 mode":"Chế độ WPA2/3","WPA2 devices stay at risk":"Thiết bị WPA2 vẫn gặp rủi ro","Stronger still":"Mạnh hơn nữa","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 bit)","MANAGEMENT FRAMES PROTECTED":"KHUNG QUẢN LÝ ĐƯỢC BẢO VỆ","0x00c0: management frame protection required":"0x00c0: bắt buộc bảo vệ khung quản lý","Disconnect messages and other management frames are signed, so they can’t be forged.":"Thông điệp ngắt kết nối và các khung quản lý khác được ký, nên không giả mạo được.","Authentication · SAE Commit":"Xác thực · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: trao đổi mật khẩu của WPA3.","19 (256-bit elliptic curve)":"19 (đường cong elliptic 256 bit)",Scalar:"Vô hướng","Worked out from a random secret and the password.":"Tính từ một bí mật ngẫu nhiên và mật khẩu.",Element:"Phần tử","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Một điểm trên đường cong, cũng gắn với mật khẩu. Ghi lại vô hướng và phần tử không giúp ai thử đoán mật khẩu về sau.","Authentication · SAE Confirm":"Xác thực · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Chứng minh bên này tính ra cùng một khóa, mà không để lộ nó.","0x0088: pairwise, ACK":"0x0088: theo cặp, ACK","0x0108: pairwise, MIC":"0x0108: theo cặp, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: theo cặp, cài đặt, ACK, MIC, an toàn, dữ liệu khóa đã mã hóa","IGTK: the key that signs broadcast management frames":"IGTK: khóa ký các khung quản lý quảng bá","0x0308: pairwise, MIC, secure":"0x0308: theo cặp, MIC, an toàn","Sign-In":"Đăng nhập","From the router":"Từ router","From the test server":"Từ máy chủ kiểm tra","Hotel Router":"Router khách sạn","192.168.1.1 · captive portal":"192.168.1.1 · cổng đăng nhập","Wi-Fi login pages":"Trang đăng nhập Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Khách sạn, quán cà phê, sân bay và tàu thường đặt một trang đăng nhập trước Wi-Fi. Cho đến khi bạn chấp nhận điều khoản (hoặc trả tiền), router không cho gì ra Internet. Nó chặn yêu cầu HTTP thường đầu tiên của thiết bị và trả lời bằng một chuyển hướng tới trang của nó; thiết bị nhận ra vì một trang kiểm tra nó biết trả về sai.",Where:"Ở đâu","Hotels, cafés, airports":"Khách sạn, quán cà phê, sân bay",How:"Cách làm","Catches plain HTTP requests":"Chặn yêu cầu HTTP thường","Noticed by":"Phát hiện bởi","Your system’s test page":"Trang kiểm tra của hệ thống","Logging in":"Đăng nhập","Lets your MAC address through":"Cho địa chỉ MAC của bạn qua","Newer way":"Cách mới hơn","DHCP option 114 (RFC 8910)":"Tùy chọn DHCP 114 (RFC 8910)","Described In":"Mô tả trong",Online:"Đã lên mạng","Noticed, logged in, let through":"Phát hiện, đăng nhập, cho qua","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows hỏi một trang kiểm tra để lấy câu trả lời nó đã biết nhưng lại nhận được chuyển hướng, nên biết có cổng đăng nhập chắn đường và mở trang đăng nhập. Khi điều khoản đã được chấp nhận, router cho laptop qua, và cùng bước kiểm tra đó trả về đúng. Nhấn XEM LẠI để xem lại.","A plain HTTP test page":"Một trang kiểm tra HTTP thường","Faked by":"Giả mạo bởi","The router (TTL 64)":"Router (TTL 64)","Let through":"Cho qua","The laptop’s MAC address":"Địa chỉ MAC của laptop","Open Wi-Fi":"Wi-Fi mở","Use HTTPS, or a VPN":"Dùng HTTPS, hoặc VPN","Joined, Offline":"Đã vào mạng, chưa có Internet","An address, but no way out":"Có địa chỉ, nhưng không có lối ra","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"Laptop đã vào Wi-Fi của khách sạn, mạng không có mật khẩu, và nhận địa chỉ từ router qua DHCP. Router tự trả lời laptop và chuyển tiếp các tra cứu DNS, nhưng bỏ mọi thứ khác đi ra Internet cho đến khi khách đăng nhập. (Mạng mở cũng có nghĩa ai ở gần cũng đọc được những gì không được HTTPS bảo vệ.)","192.168.1.10 (by DHCP)":"192.168.1.10 (qua DHCP)","Wi-Fi password":"Mật khẩu Wi-Fi","None (open network)":"Không có (mạng mở)","Blocked until you log in":"Bị chặn đến khi đăng nhập","CONNECTED, NO INTERNET YET":"ĐÃ KẾT NỐI, CHƯA CÓ INTERNET","Internet Check":"Kiểm tra Internet","Windows checks a test page":"Windows kiểm tra một trang thử",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Sau khi vào bất kỳ mạng nào, Windows tra www.msftconnecttest.com (router chuyển tiếp tra cứu) và xin /connecttest.txt qua HTTP thường; câu trả lời đúng là dòng chữ "Microsoft Connect Test". Router chặn kết nối và tự trả lời bắt tay, nhân danh máy chủ kiểm tra. Laptop chưa nhận ra.',"Test page":"Trang thử","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Mong đợi","Answered by":"Người trả lời","The router, posing as the server":"Router, giả làm máy chủ",'from "203.0.113.30"':'từ "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Bị chuyển hướng","The wrong answer gives it away":"Câu trả lời sai để lộ",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':"Thay vì dòng chữ thử, “máy chủ” trả lời 302 Found, chỉ tới trang đăng nhập của router. TTL của nó là 64, hoàn toàn không giảm, vì nó đến thẳng từ router. Windows thấy câu trả lời sai, đánh dấu mạng cần thao tác và mở trình duyệt, yêu cầu đầu tiên của trình duyệt cũng bị router chuyển hướng như vậy, tới trang đăng nhập. Cách này chỉ hiệu quả với HTTP thường: router không giả được trang HTTPS mà không gây lỗi chứng chỉ.","302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Dấu hiệu","TTL 64, from one hop away":"TTL 64, chỉ cách một chặng","Why HTTP":"Vì sao HTTP","HTTPS can’t be faked":"HTTPS không giả được","302 FOUND":"302 FOUND","ACTION NEEDED":"CẦN THAO TÁC","The Login Page":"Trang đăng nhập","Served by the router itself":"Do chính router phục vụ","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Trình duyệt mở http://192.168.1.1/login, trang do chính router phục vụ: tên khách sạn, điều khoản sử dụng và nút Chấp nhận. Kết nối này thật sự đi tới router.",Page:"Trang","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Phục vụ bởi","The router":"Router",Size:"Kích thước","2,400 bytes of HTML":"2,400 byte HTML","/login":"/login","the login page":"trang đăng nhập","Accept the Terms":"Chấp nhận điều khoản","The router lets the laptop out":"Router cho laptop ra ngoài","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Bấm Chấp nhận sẽ gửi một biểu mẫu nhỏ về router. Router thêm địa chỉ MAC của laptop vào danh sách thiết bị được ra ngoài, thường trong suốt thời gian lưu trú, và chuyển trình duyệt đi tiếp.",Form:"Biểu mẫu","terms=accepted":"terms=accepted","Router allows":"Router cho phép","302 to where you were going":"302 tới nơi bạn định tới","you’re online":"bạn đã lên mạng","MAC ADDRESS ALLOWED":"ĐÃ CHO PHÉP ĐỊA CHỈ MAC","The same check, now real":"Cùng bước kiểm tra, giờ là thật","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows kiểm tra lại. Lần này router cho kết nối đi tới máy chủ kiểm tra thật, cách mười hai router (phản hồi đến với TTL 52), và câu trả lời là dòng chữ mong đợi. Mạng được đánh dấu là đã kết nối Internet.","Connected to the internet":"Đã kết nối Internet",ONLINE:"TRỰC TUYẾN","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, loại A, lớp IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Gửi với 64 và hoàn toàn không giảm: nó đến từ router ngay cạnh, không phải từ máy chủ cách 12 router.","2,400 bytes: the login page":"2,400 byte: trang đăng nhập","Via a Proxy":"Qua proxy","TLS, through the tunnel":"TLS, qua đường hầm","Forward proxy, and CONNECT for HTTPS":"Proxy chuyển tiếp, và CONNECT cho HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Proxy chuyển tiếp tải trang web thay bạn. Công ty và trường học dùng nó để lọc trang, giữ bản sao các trang phổ biến và ghi nhật ký những gì đi ra; các trang bạn truy cập thấy proxy, không thấy bạn. HTTP thường đi qua nó ở dạng đọc được. Với HTTPS, trình duyệt xin proxy một đường hầm, và kết nối mã hóa đi qua mà không bị đọc.","Common ports":"Cổng phổ biến","http:// pages":"Trang http://","Fetched by the proxy":"Proxy tải về","https:// pages":"Trang https://","Tunnelled with CONNECT":"Đi đường hầm bằng CONNECT","Used for":"Dùng để","Filtering, caching, logging":"Lọc, lưu đệm, ghi nhật ký","Two ways through":"Hai cách đi qua","Fetched for you, or tunnelled":"Tải thay bạn, hoặc đi đường hầm","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Với trang thường, proxy làm hết: đọc yêu cầu, tải trang bằng kết nối riêng và có thể giữ, sửa hoặc từ chối nó. Với HTTPS, nó chỉ mở đường hầm và sao chép byte đã mã hóa, không biết gì ngoài tên trang. Nhấn XEM LẠI để xem lại.","Server sees":"Máy chủ thấy","The proxy (192.0.2.80)":"Proxy (192.0.2.80)","Plain HTTP":"HTTP thường","The proxy reads it all":"Proxy đọc hết","Name and sizes only":"Chỉ tên và kích thước","DNS for the site":"DNS cho trang","Done by the proxy":"Do proxy làm","Proxy Settings":"Thiết lập proxy","The browser sends everything there":"Trình duyệt gửi mọi thứ tới đó","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Trình duyệt được đặt để gửi mọi thứ qua proxy tại 192.0.2.80, cổng 8080, như nhiều công ty và trường học yêu cầu. Bạn mở http://www.example.com. Trình duyệt không tự tra www.example.com: nó kết nối tới proxy và để proxy lo phần còn lại.","Left to the proxy":"Để proxy lo","To the Proxy":"Tới proxy","TCP to port 8080":"TCP tới cổng 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"Laptop mở một kết nối TCP bình thường, không phải tới trang web, mà tới cổng 8080 của proxy.","192.0.2.80, port 8080":"192.0.2.80, cổng 8080","Not to":"Không phải tới","The Whole URL":"Cả URL","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Khi gửi tới proxy, dòng yêu cầu mang cả địa chỉ, không chỉ đường dẫn: GET http://www.example.com/ HTTP/1.1. Nhờ đó proxy biết phải đi đâu. Chrome thêm Proxy-Connection: keep-alive, một tiêu đề chỉ proxy đọc.","Request line":"Dòng yêu cầu","To a server":"Tới máy chủ","Readable by":"Ai đọc được","The proxy (plain HTTP)":"Proxy (HTTP thường)","to the proxy":"tới proxy","Proxy Fetches It":"Proxy tải về","Its own connection to the server":"Kết nối riêng của nó tới máy chủ","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Proxy tự tra www.example.com (không hiện) và mở kết nối riêng tới máy chủ. Yêu cầu của nó là loại thông thường, GET /, với tiêu đề riêng: Via nêu tên proxy, và X-Forwarded-For cho biết yêu cầu đến từ địa chỉ nào (địa chỉ công khai của router ở nhà, vì laptop nằm sau NAT).","The proxy’s own":"Của proxy","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Chuyển tiếp cho","Page Passed On":"Đã chuyển trang","The page, passed on":"Trang, được chuyển tiếp","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Máy chủ trả lời proxy, và proxy chuyển trang cho laptop kèm tiêu đề Via của nó. Nó có thể giữ một bản sao và đưa cho người tiếp theo hỏi mà không làm phiền máy chủ (X-Cache: MISS cho biết nó chưa có bản nào), và có thể từ chối các trang không được phép.","The proxy, not the laptop":"Proxy, không phải laptop",Cache:"Bộ nhớ đệm","MISS (first request)":"MISS (yêu cầu đầu tiên)","Proxy can":"Proxy có thể","Cache, filter, log, change":"Lưu đệm, lọc, ghi nhật ký, sửa","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Giờ bạn mở https://www.example.com. Proxy không thể tải trang HTTPS thay bạn mà không phá mã hóa, nên trình duyệt xin một đường hầm: CONNECT www.example.com:443. Proxy mở kết nối TCP tới cổng 443 và trả lời 200 Connection established.","Proxy opens":"Proxy mở","TCP to port 443":"TCP tới cổng 443","200 Connection established":"200 Connection established","Connection established":"Đã thiết lập kết nối","In the Tunnel":"Trong đường hầm","The proxy copies, unread":"Proxy sao chép, không đọc","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Từ giờ proxy sao chép byte theo cả hai chiều mà không đọc. TLS Client Hello của trình duyệt đi vào trên kết nối của laptop và đi ra, giống hệt từng byte, trên kết nối của proxy tới máy chủ. TLS chạy từ đầu đến cuối, nên proxy chỉ biết tên trang và kích thước, không bao giờ thấy nội dung. (Một số proxy công ty vẫn mở HTTPS, bằng một tổ chức chứng thực cài trên mọi laptop công ty; khi đó chúng thấy hết.)","Proxy sees":"Proxy thấy","Site name, sizes, timing":"Tên trang, kích thước, thời gian","Hidden from it":"Bị giấu khỏi nó","Pages, passwords, cookies":"Trang, mật khẩu, cookie","TLS, laptop to server":"TLS, từ laptop tới máy chủ","the same bytes":"cùng những byte đó","COPIES BYTES, CAN’T READ THEM":"SAO CHÉP BYTE, KHÔNG ĐỌC ĐƯỢC","Any Connection":"Mọi kết nối","From the proxy":"Từ proxy","SOCKS Proxy":"Proxy SOCKS","Socket Secure, version 5":"Socket Secure, phiên bản 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS là một proxy đa năng. Proxy HTTP hiểu yêu cầu web, còn proxy SOCKS chỉ mở kết nối thay bạn và sao chép byte, bất kể giao thức: web, email, game, SSH. Ứng dụng dùng nó để vào một mạng qua một cổng duy nhất, hoặc để giấu địa chỉ của mình; ssh -D và Tor đều cung cấp nó.","Session (Layer 5)":"Phiên (tầng 5)","Any TCP, and UDP":"Mọi TCP, và UDP",Logins:"Đăng nhập","None, or user and password":"Không, hoặc người dùng và mật khẩu","Offered by":"Do ai cung cấp","ssh -D, Tor, proxy servers":"ssh -D, Tor, máy chủ proxy","Tunnel open":"Đã mở đường hầm","A few bytes, then just copying":"Vài byte, rồi chỉ sao chép","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Bốn thông điệp tí hon cho proxy biết phải kết nối đi đâu; sau đó nó chỉ sao chép byte. Trang web thấy địa chỉ của proxy, và vì laptop gửi tên chứ không phải địa chỉ, ngay cả tra cứu DNS cũng diễn ra ở proxy. Nhấn XEM LẠI để xem lại.","4 messages, 37 bytes":"4 thông điệp, 37 byte","DNS lookup":"Tra cứu DNS","At the proxy":"Tại proxy","Only the TLS inside":"Chỉ TLS bên trong","TCP to port 1080":"TCP tới cổng 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Một ứng dụng được đặt để dùng proxy SOCKS (trình duyệt, trình chạy game hoặc đường hầm tạo bằng ssh -D) mở kết nối TCP tới nó, cổng 1080. SOCKS không quan tâm thứ gì sẽ đi bên trong: nó mang được mọi kết nối TCP.","Any TCP connection":"Mọi kết nối TCP","Wants to reach":"Muốn tới","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Phiên bản 5, và cách đăng nhập","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"Laptop gửi ba byte: phiên bản 5, một cách đăng nhập được đề xuất, và cách đó là 0: không đăng nhập. Proxy trả lời hai byte: phiên bản 5, cách 0. Nếu nó chọn cách 2, ứng dụng sẽ gửi tiếp tên người dùng và mật khẩu, ở dạng văn bản thường.","Laptop sends":"Laptop gửi","05 01 00 (3 bytes)":"05 01 00 (3 byte)","Proxy answers":"Proxy trả lời","05 00 (2 bytes)":"05 00 (2 byte)","None needed here":"Ở đây không cần",GREETING:"CHÀO HỎI","no login, please":"không đăng nhập nhé",METHOD:"PHƯƠNG THỨC","no login needed":"không cần đăng nhập","Where To?":"Đi đâu?","Connect to www.example.com:443":"Kết nối tới www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"Laptop nhờ proxy kết nối tới www.example.com, cổng 443. Nó đưa tên thay vì địa chỉ, nên proxy làm tra cứu DNS và laptop không cần. Proxy mở kết nối TCP riêng tới máy chủ, rồi trả lời: thành công, kèm địa chỉ và cổng nó kết nối từ đó.","www.example.com (a name)":"www.example.com (một tên)","Succeeded, from 192.0.2.80:40220":"Thành công, từ 192.0.2.80:40220",SUCCEEDED:"THÀNH CÔNG","from 192.0.2.80:40220":"từ 192.0.2.80:40220","Copied both ways, unread":"Sao chép hai chiều, không đọc","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Giờ proxy chỉ sao chép. Ứng dụng bắt đầu TLS với máy chủ: Client Hello của nó đi vào trên kết nối của laptop và đi ra nguyên vẹn trên kết nối của proxy, và câu trả lời của máy chủ quay về theo cùng cách. Máy chủ chỉ luôn thấy địa chỉ của proxy; proxy chỉ thấy byte đã mã hóa.","The proxy’s address":"Địa chỉ của proxy","Encrypted bytes":"Byte đã mã hóa","Same bytes":"Cùng những byte","On both connections":"Trên cả hai kết nối",unchanged:"nguyên vẹn","+ encrypted handshake":"+ bắt tay đã mã hóa","Version 5, 1 method: no login":"Phiên bản 5, 1 phương thức: không đăng nhập","Version 5, method chosen: no login":"Phiên bản 5, phương thức đã chọn: không đăng nhập","Succeeded, bound to 192.0.2.80:40220":"Thành công, gắn với 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · chào hỏi","Methods offered":"Phương thức đề xuất","0 (no login)":"0 (không đăng nhập)","SOCKS5 · method chosen":"SOCKS5 · phương thức đã chọn","Method chosen":"Phương thức đã chọn","SOCKS5 · connect request":"SOCKS5 · yêu cầu kết nối","Open a TCP connection on my behalf.":"Mở giúp tôi một kết nối TCP.","Address type":"Loại địa chỉ","3 (domain name)":"3 (tên miền)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Proxy tự tra tên, nên laptop không cần tra cứu DNS riêng.","SOCKS5 · reply":"SOCKS5 · trả lời","0 (succeeded)":"0 (thành công)","The address the proxy connects from.":"Địa chỉ proxy kết nối từ đó.",Offloading:"Giảm tải","Reverse Proxy":"Reverse proxy","TLS (SSL) offloading":"Giảm tải TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Reverse proxy đứng trước các máy chủ của một trang web: khách kết nối tới nó, và nó chuyển yêu cầu của họ tới máy chủ ứng dụng phía sau. Nó có thể chia tải cho nhiều máy chủ, giữ bản sao trang và chặn tấn công. Thường nó còn làm phần việc TLS, giải mã HTTPS ở rìa để các máy chủ phía sau chỉ nói HTTP thường. Đó là giảm tải SSL (hay TLS).","Visitors reach":"Khách tới được","The proxy, never the app":"Proxy, không bao giờ là ứng dụng","TLS ends":"TLS kết thúc","At the proxy (offloading)":"Tại proxy (giảm tải)","Plain HTTP (or TLS again)":"HTTP thường (hoặc lại TLS)",Adds:"Thêm vào","For example":"Ví dụ","nginx, HAProxy, cloud LBs":"nginx, HAProxy, LB đám mây","Served from the edge":"Phục vụ từ rìa","Encrypted outside, plain inside":"Mã hóa bên ngoài, rõ bên trong","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"Laptop thấy một trang HTTPS duy nhất. Phía sau, reverse proxy giải mã yêu cầu, hỏi một máy chủ ứng dụng bằng HTTP thường qua mạng riêng và mã hóa câu trả lời cho chuyến về. Nhấn XEM LẠI để xem lại.","Laptop ↔ proxy only":"Chỉ laptop ↔ proxy","App learns visitor":"Ứng dụng biết khách","From X-Forwarded-For":"Từ X-Forwarded-For","Certificate kept":"Chứng chỉ được giữ","On the proxy":"Trên proxy","The Front Door":"Cửa trước","The proxy holds the certificate":"Proxy giữ chứng chỉ","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"Laptop mở https://www.example.com. Địa chỉ DNS cho tên đó thuộc về reverse proxy, nơi giữ chứng chỉ của trang và làm bắt tay TLS. Không có gì cho laptop biết phía sau còn một máy chủ khác.","Laptop connects to":"Laptop kết nối tới","On the reverse proxy":"Trên reverse proxy","Also called":"Còn gọi là","Load balancer, edge":"Bộ cân bằng tải, edge","TLS Ends Here":"TLS kết thúc ở đây","Offloading: the proxy does the TLS work":"Giảm tải: proxy làm phần việc TLS","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"Yêu cầu đến dạng mã hóa, và reverse proxy giải mã nó. Đó là giảm tải: phần việc TLS làm ở đây, một lần, thay vì trên từng máy chủ ứng dụng. Giờ proxy đọc được URL, tiêu đề và cookie, và chọn máy chủ dựa vào chúng.","At the reverse proxy":"Tại reverse proxy","Proxy can read":"Proxy đọc được","URL, headers, cookies":"URL, tiêu đề, cookie","Then picks":"Rồi chọn","An app server":"Một máy chủ ứng dụng","TLS ENDS HERE":"TLS KẾT THÚC Ở ĐÂY","In the Clear":"Dạng rõ","Passed on to the app server":"Chuyển tới máy chủ ứng dụng","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Proxy chuyển yêu cầu qua mạng riêng của trung tâm dữ liệu, dưới dạng HTTP thường tới cổng 8080. Nó thêm X-Forwarded-For, địa chỉ của khách, và X-Forwarded-Proto: https, cách khách đi vào; nếu không ứng dụng chỉ thấy proxy. Ai theo dõi được mạng riêng này cũng đọc được hết.","The App Answers":"Ứng dụng trả lời","In plain HTTP too":"Cũng bằng HTTP thường","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Máy chủ ứng dụng dựng trang và trả lời proxy bằng HTTP thường: nó không bao giờ phải lo TLS hay chứng chỉ.","text/html, 12,500 bytes":"text/html, 12,500 byte","readable inside":"đọc được bên trong","Encrypted Again":"Lại được mã hóa","An ordinary HTTPS answer":"Một câu trả lời HTTPS bình thường","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Reverse proxy mã hóa câu trả lời trong phiên TLS nó giữ với laptop và gửi đi. Nhìn từ ngoài, đó là một trang HTTPS bình thường.","Laptop sees":"Laptop thấy","One HTTPS server":"Một máy chủ HTTPS","App servers":"Máy chủ ứng dụng","Never handle TLS":"Không bao giờ xử lý TLS",Certificates:"Chứng chỉ","Renewed in one place":"Gia hạn ở một nơi","Three Options":"Ba lựa chọn","Offload, re-encrypt or pass through":"Giảm tải, mã hóa lại hoặc cho đi qua","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Giảm tải, như ở đây, đơn giản và nhanh nhưng để lưu lượng bên trong đọc được. Mã hóa lại mở kết nối TLS thứ hai từ proxy tới máy chủ ứng dụng, nên bên trong cũng được mã hóa. Cho đi qua chuyển tiếp byte TLS mà không mở: chứng chỉ nằm trên máy chủ ứng dụng, và proxy chỉ chọn máy chủ được theo địa chỉ và tên trong Client Hello, không theo URL.",Offload:"Giảm tải","Plain HTTP inside":"Bên trong là HTTP thường","Re-encrypt":"Mã hóa lại","TLS inside as well":"Bên trong cũng TLS","Pass through":"Cho đi qua","Proxy can’t read it":"Proxy không đọc được","PLAIN HTTP INSIDE":"BÊN TRONG LÀ HTTP THƯỜNG","A Modern VPN":"Một VPN hiện đại","WireGuard (encrypted)":"WireGuard (đã mã hóa)","TCP beyond the VPN":"TCP ngoài VPN",Keepalive:"Keepalive","VPN Server":"Máy chủ VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"VPN mang lưu lượng của bạn trong một đường hầm mã hóa tới máy chủ VPN, máy chủ này gửi tiếp ra Internet. Trên Wi-Fi quán cà phê, người khác chỉ thấy gói mã hóa đi tới máy chủ VPN; các trang web thấy địa chỉ máy chủ VPN thay vì của bạn. WireGuard là một VPN hiện đại: ít mã, một bộ thuật toán hiện đại cố định và bắt tay hai thông điệp.","UDP (51820 by default)":"UDP (mặc định 51820)","2 messages, 1 round trip":"2 thông điệp, 1 lượt khứ hồi",Crypto:"Mật mã",Identity:"Danh tính","Public keys, like SSH":"Khóa công khai, giống SSH","The WireGuard whitepaper":"Whitepaper của WireGuard","Tunnel up":"Đường hầm đã chạy","Encrypted to the VPN, plain beyond it":"Mã hóa tới VPN, rõ sau đó","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Hai thông điệp bắt tay tạo ra khóa. Sau đó mọi gói laptop gửi đều được niêm phong nguyên vẹn bên trong một gói UDP tới máy chủ VPN, và trang web chỉ thấy địa chỉ của máy chủ VPN. Sau máy chủ VPN, lưu lượng không được bảo vệ hơn so với khi không có VPN, nên HTTPS vẫn quan trọng. Nhấn XEM LẠI để xem lại.","Others nearby see":"Người ở gần thấy","UDP to 192.0.2.51":"UDP tới 192.0.2.51","Websites see":"Trang web thấy","The VPN server":"Máy chủ VPN","Beyond the VPN":"Sau VPN","Only HTTPS protects":"Chỉ HTTPS bảo vệ",Overhead:"Phụ phí","60 bytes + padding":"60 byte + đệm","Set Up Once":"Cài đặt một lần","Keys, not passwords":"Khóa, không phải mật khẩu","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"Laptop chạy ứng dụng WireGuard với một cấu hình ngắn: khóa riêng của nó, khóa công khai và địa chỉ của máy chủ (192.0.2.51, cổng UDP 51820), và AllowedIPs = 0.0.0.0/0, nghĩa là mọi thứ đều đi qua đường hầm. Trong đường hầm, địa chỉ của laptop là 10.8.0.2.","Inside address":"Địa chỉ bên trong","Through the tunnel":"Qua đường hầm","Everything (0.0.0.0/0)":"Mọi thứ (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"ĐỊA CHỈ ĐƯỜNG HẦM 10.8.0.2","Two messages, one round trip":"Hai thông điệp, một lượt khứ hồi","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Khi laptop lần đầu có gì để gửi, nó bắt đầu bắt tay: 148 byte với một khóa công khai mới, khóa dài hạn của nó (đã mã hóa, để chỉ máy chủ biết ai đang gọi) và thời gian (đã mã hóa, để bản ghi không phát lại được). Máy chủ chỉ trả lời những khóa nó biết, ở đây bằng 92 byte. Một lượt khứ hồi, và cả hai bên có khóa phiên mới.",Initiation:"Khởi tạo","Server answers":"Máy chủ trả lời","Only keys it knows":"Chỉ khóa nó biết",INITIATION:"INITIATION","fresh key + identity":"khóa mới + danh tính",RESPONSE:"RESPONSE","keys agreed":"đã thỏa thuận khóa","Into the Tunnel":"Vào đường hầm","A packet inside a packet":"Gói trong gói","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Bạn mở https://www.example.com; địa chỉ của nó cũng được tra qua đường hầm (không hiện). Gói đầu tiên của kết nối, một TCP SYN từ 10.8.0.2 tới máy chủ web, được mã hóa nguyên vẹn và gửi bên trong một gói UDP tới máy chủ VPN. Trên Wi-Fi quán cà phê chỉ thấy gói bên ngoài: từ laptop tới 192.0.2.51, cổng 51820.",Outside:"Bên ngoài","UDP to 192.0.2.51:51820":"UDP tới 192.0.2.51:51820","inside: TCP SYN to :443":"bên trong: TCP SYN tới :443","Out to the Web":"Ra web","Decrypted, then sent on":"Giải mã, rồi gửi tiếp","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Máy chủ VPN giải mã gói, thay 10.8.0.2 bằng địa chỉ công khai của nó (NAT) và gửi SYN đi tiếp, già thêm một chặng (TTL 127). SYN đề xuất đoạn tối đa 1380 byte, không phải 1460: đường hầm thêm 60 byte vào mỗi gói. Máy chủ web thấy một khách ở 192.0.2.51 và trả lời về đó.","Website sees":"Trang web thấy","192.0.2.51 (the VPN)":"192.0.2.51 (VPN)","Hidden from the site":"Giấu khỏi trang","127 (one hop, the VPN)":"127 (một chặng, VPN)","from 192.0.2.51":"từ 192.0.2.51","The Way Back":"Đường về","Sealed again, for the laptop":"Niêm phong lại, cho laptop","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"Câu trả lời quay về theo cùng đường. Máy chủ VPN niêm phong SYN-ACK trong một gói WireGuard cho laptop, laptop mở ra và giao cho Windows như thể nó đến thẳng từ máy chủ web.",Counter:"Bộ đếm","Each side counts its own":"Mỗi bên đếm riêng",Replays:"Phát lại","Thrown away":"Bị bỏ","inside: TCP SYN-ACK":"bên trong: TCP SYN-ACK","Keeping It Open":"Giữ mở","A keepalive, and new keys":"Một keepalive, và khóa mới","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Khi không có gì để gửi, đường hầm WireGuard im lặng. Vì laptop nằm sau NAT, nó được đặt gửi một gói rỗng mỗi 25 giây (PersistentKeepalive), một keepalive 32 byte, để router không quên kết nối. Cứ hai phút một bắt tay mới tạo khóa mới, và nếu laptop chuyển sang mạng khác, đường hầm cứ thế tiếp tục từ địa chỉ mới.","Every 25 s, 32 bytes":"Mỗi 25 s, 32 byte","New keys":"Khóa mới","Every 2 minutes":"Mỗi 2 phút","New network":"Mạng mới","The tunnel carries on":"Đường hầm tiếp tục",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"rỗng, 32 byte","Message type":"Loại thông điệp","Sender index":"Chỉ số bên gửi","A number this side picked for the session; the other side puts it in every packet it sends back.":"Một số bên này chọn cho phiên; bên kia đặt nó vào mọi gói gửi lại.","Ephemeral key":"Khóa tạm thời","A new public key, made just for this handshake.":"Một khóa công khai mới, chỉ tạo cho lần bắt tay này.","Encrypted static key":"Khóa tĩnh đã mã hóa","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"Khóa công khai dài hạn của laptop (32 byte) và một thẻ 16 byte, đã mã hóa: chỉ máy chủ biết ai đang gọi.","Encrypted timestamp":"Dấu thời gian đã mã hóa","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"Thời gian (12 byte) và một thẻ, đã mã hóa. Một lần khởi tạo cũ gửi lại sẽ bị từ chối.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Tính bằng khóa công khai của máy chủ: không có nó, máy chủ hoàn toàn không trả lời.","Used only when the server is busy and asks for a cookie first.":"Chỉ dùng khi máy chủ bận và đòi cookie trước.","Receiver index":"Chỉ số bên nhận","The other side’s index: which session this packet belongs to.":"Chỉ số của bên kia: gói này thuộc phiên nào.","The server’s new public key for this handshake.":"Khóa công khai mới của máy chủ cho lần bắt tay này.","Encrypted nothing":"Mã hóa rỗng","Only a tag: it proves the server holds its private key.":"Chỉ một thẻ: chứng minh máy chủ có khóa riêng của nó.","Counts up with every packet; one seen before is thrown away.":"Tăng theo mỗi gói; gói đã thấy rồi sẽ bị bỏ.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Toàn bộ gói bên trong, đệm tới bội số của 16 byte, rồi một thẻ 16 byte.","then 12 bytes of padding, and the tag":"rồi 12 byte đệm, và thẻ","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"Laptop gửi với 128; máy chủ VPN trừ 1 khi chuyển tiếp.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Chỉ có thẻ 16 byte: một gói rỗng giữ cho đường hầm mở.","ESP (encrypted)":"ESP (đã mã hóa)","TCP beyond the gateway":"TCP sau cổng","VPN Gateway":"Cổng VPN","IP Security":"IP Security","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec bảo vệ chính các gói IP. IKEv2 chuẩn bị mọi thứ: hai bên thỏa thuận thuật toán, tạo khóa và chứng minh danh tính bằng chứng chỉ hoặc thông tin xác thực khác. Rồi ESP mang mỗi gói đã mã hóa bên trong một gói khác. IPsec nối các văn phòng với nhau và đưa laptop vào mạng công ty, và được tích hợp trong hầu hết hệ điều hành và tường lửa.","Behind NAT":"Sau NAT","ESP (IP protocol 50)":"ESP (giao thức IP 50)","Certificates, EAP, keys":"Chứng chỉ, EAP, khóa","IKE to set up, ESP to carry":"IKE để thiết lập, ESP để mang","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Bốn thông điệp IKE đã thỏa thuận thuật toán, phát hiện NAT, chứng minh cả hai danh tính và thiết lập đường hầm. Sau đó mỗi gói đi nguyên vẹn bên trong ESP, được mã hóa và kiểm tra, và gói trong UDP để qua được router ở nhà. Nhấn XEM LẠI để xem lại.","IKE messages":"Thông điệp IKE","4 (2 exchanges)":"4 (2 lần trao đổi)","NAT traversal":"Vượt NAT","One SPI each way":"Mỗi chiều một SPI","Agree on algorithms, swap keys":"Thỏa thuận thuật toán, trao đổi khóa","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Máy khách VPN mở đầu bằng IKE trên cổng UDP 500. Thông điệp đầu tiên đề xuất thuật toán (AES-GCM với khóa 256 bit, SHA-256, Curve25519) và mang một khóa công khai và một nonce ngẫu nhiên; cổng chọn đề xuất và gửi khóa và nonce của nó. Giờ cả hai có chung một bí mật, nhưng chưa bên nào chứng minh mình là ai.",Proposed:"Đề xuất","After this":"Sau bước này","Shared keys, no identities":"Khóa chung, chưa có danh tính","proposal, key, nonce":"đề xuất, khóa, nonce","NAT detection":"phát hiện NAT","chosen proposal, key, nonce":"đề xuất đã chọn, khóa, nonce","A NAT in the Way":"Có NAT cản đường","So everything moves to port 4500":"Nên mọi thứ chuyển sang cổng 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Cả hai thông điệp còn mang giá trị băm của địa chỉ và cổng mỗi bên gửi đi. Tại cổng, chúng không khớp với những gì đến: router ở nhà đã viết lại địa chỉ laptop trên đường (NAT). ESP không có số cổng, nên NAT không cho nó qua được; cả hai bên chuyển sang cổng UDP 4500 và từ giờ gói ESP trong UDP.","Hashes of":"Giá trị băm của","Address and port sent from":"Địa chỉ và cổng gửi đi",Mismatch:"Không khớp","The router rewrote them":"Router đã viết lại",Fix:"Cách khắc phục","Everything over UDP 4500":"Mọi thứ qua UDP 4500","NAT DETECTED":"PHÁT HIỆN NAT","Prove who you are, encrypted":"Chứng minh danh tính, đã mã hóa","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Giờ đã mã hóa, mỗi bên gửi danh tính, chứng chỉ và một chữ ký trên mọi thứ đã nói đến giờ, nên ai đứng giữa cũng sẽ bị phát hiện. Laptop xin một địa chỉ bên trong mạng và nhận 10.8.0.2. Cùng lần trao đổi đó thiết lập chính đường hầm ESP, với khóa riêng và một SPI cho mỗi chiều.","UDP 4500 (NAT traversal)":"UDP 4500 (vượt NAT)","Identity, by certificate":"Danh tính, bằng chứng chỉ","Laptop gets":"Laptop nhận","10.8.0.2, and a DNS server":"10.8.0.2, và một máy chủ DNS","identity, certificate":"danh tính, chứng chỉ",signature:"chữ ký","address 10.8.0.2":"địa chỉ 10.8.0.2","The whole packet, encrypted":"Cả gói, đã mã hóa","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Bạn mở https://www.example.com, được tra qua đường hầm tại máy chủ DNS mà cổng cấp (không hiện). SYN từ 10.8.0.2 được mã hóa nguyên vẹn vào một gói ESP: một SPI chỉ định đường hầm, một số thứ tự, rồi gói đã mã hóa và một giá trị kiểm tra, tất cả bên trong cổng UDP 4500. Checksum UDP của nó bằng 0: ESP tự kiểm tra nội dung của mình.","Names the tunnel":"Chỉ định đường hầm","The whole IP packet":"Cả gói IP","62 bytes + padding":"62 byte + đệm","Out and Back":"Đi và về","Through the gateway and home again":"Qua cổng và trở về","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"Cổng giải mã gói và gửi SYN đi tiếp từ địa chỉ của nó, già thêm một chặng. Câu trả lời quay về cổng và đi lại qua đường hầm dưới dạng một gói ESP khác, với SPI của chiều về laptop và số thứ tự riêng.","192.0.2.51 (the gateway)":"192.0.2.51 (cổng)","Each direction":"Mỗi chiều","Its own SPI and keys":"SPI và khóa riêng","Which VPN?":"VPN nào?","IPsec or WireGuard":"IPsec hay WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec lâu đời hơn và rất linh hoạt: nó thương lượng thuật toán, nhận nhiều loại thông tin xác thực và được tích hợp trong Windows, macOS, iOS, Android và hầu hết tường lửa, nên là cách thường dùng để vào mạng công ty hay nối hai văn phòng. WireGuard làm ít hơn, với ít mã hơn nhiều và một bộ thuật toán cố định.","Built into":"Tích hợp trong","Also links":"Còn nối","Office to office":"Văn phòng với văn phòng",Negotiates:"Thương lượng","Its algorithms (WireGuard: no)":"Thuật toán của nó (WireGuard: không)","Initiator SPI":"SPI bên khởi tạo","Picked by the laptop: which IKE session this is.":"Do laptop chọn: đây là phiên IKE nào.","Responder SPI":"SPI bên trả lời","0 (not known yet)":"0 (chưa biết)","Next payload":"Payload kế tiếp","Exchange type":"Loại trao đổi","0x08 (initiator)":"0x08 (bên khởi tạo)","Message ID":"ID thông điệp","Each request and its response share a number; the next exchange counts up.":"Mỗi yêu cầu và phản hồi của nó dùng chung một số; lần trao đổi sau đếm tăng lên.","SA payload":"Payload SA","Next payload, length":"Payload kế tiếp, độ dài",Proposal:"Đề xuất","What the laptop offers; a real client often offers several.":"Những gì laptop đưa ra; máy khách thật thường đưa ra vài đề xuất.","KE payload":"Payload KE","DH group":"Nhóm DH","This side’s public key. From the two, both work out the same secret.":"Khóa công khai của bên này. Từ hai khóa, cả hai tính ra cùng một bí mật.","Nonce payload":"Payload nonce","Notify payload":"Payload notify",Notify:"Notify",Hash:"Giá trị băm","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Băm của các SPI và địa chỉ, cổng mà bên này gửi đi. Nếu thứ đến nơi không khớp, một NAT đã thay đổi nó trên đường.","The same for the address and port it sent to.":"Tương tự cho địa chỉ và cổng nó gửi tới.","0x20 (response)":"0x20 (phản hồi)","The one the server chose from the laptop’s offer.":"Đề xuất máy chủ chọn từ những gì laptop đưa ra.","Non-ESP marker":"Dấu hiệu không phải ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Bốn byte 0: một thông điệp IKE, không phải gói ESP (chúng dùng chung cổng 4500).","Encrypted payload":"Payload đã mã hóa","Encrypted payloads":"Các payload đã mã hóa","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Mọi thứ còn lại trong thông điệp này, mã hóa bằng khóa từ IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: laptop là ai, đã chứng minh","CP: asks for an inside address and DNS":"CP: xin địa chỉ bên trong và DNS","SA: what to use for ESP (AES-GCM)":"SA: dùng gì cho ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: lưu lượng nào đi vào đường hầm","Integrity check":"Kiểm tra toàn vẹn","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: cổng là ai, đã chứng minh","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: địa chỉ bên trong 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP với AES-GCM, và các SPI","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: mọi thứ (0.0.0.0/0)","0 (not used)":"0 (không dùng)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP tự kiểm tra nội dung của mình, nên ESP đi trong UDP để trường này bằng 0.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Gói này thuộc đường hầm (security association) nào; bên nhận đã chọn nó trong IKE_AUTH.","Different for every packet.":"Khác nhau cho mỗi gói.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Toàn bộ gói bên trong, rồi phần đệm, độ dài đệm và tiêu đề kế tiếp (4: một gói IPv4).","then padding, pad length and next header (4)":"rồi phần đệm, độ dài đệm và tiêu đề kế tiếp (4)","Shows any change to the packet.":"Để lộ mọi thay đổi trên gói.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"Laptop gửi với 128; cổng trừ 1 khi chuyển tiếp.","HTTP/3 over QUIC":"HTTP/3 qua QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC là giao thức giao vận mới hơn chạy trên UDP và tích hợp sẵn TLS 1.3. Các gói đầu tiên của nó làm cùng lúc bắt tay giao vận và bắt tay mã hóa, nên yêu cầu trang có thể đi sau một lượt khứ hồi. Nó mang nhiều luồng cùng lúc, nên mất một gói không làm nghẽn các luồng khác, và nó sống sót khi đổi mạng. HTTP/3 là HTTP chạy trên QUIC.","Runs over":"Chạy trên","UDP, port 443":"UDP, cổng 443","TLS 1.3, always":"TLS 1.3, luôn luôn","1 round trip (0 when returning)":"1 lượt khứ hồi (0 khi quay lại)",Streams:"Luồng","Many, independent":"Nhiều, độc lập","One round trip, then the request":"Một lượt khứ hồi, rồi yêu cầu","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC gộp bắt tay giao vận và TLS vào một lượt khứ hồi, nên yêu cầu đi 36 ms sau gói đầu tiên; với TCP và TLS nó phải chờ gấp đôi. Mọi thứ sau các gói đầu đều được mã hóa, kể cả phần lớn tiêu đề của mỗi gói. Nhấn XEM LẠI để xem lại.","1 before the request (TCP + TLS: 2)":"1 trước yêu cầu (TCP + TLS: 2)","Lost packet":"Mất gói","Holds up one stream only":"Chỉ nghẽn một luồng","Choosing HTTP/3":"Chọn HTTP/3","An earlier visit said it can":"Lần truy cập trước nói là được",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Ở lần truy cập trước, máy chủ trả lời với Alt-Svc: h3=":443", nghĩa là nó cũng nói HTTP/3 trên cổng UDP 443 (DNS cũng có thể nói vậy trong bản ghi HTTPS). Nên lần này trình duyệt bỏ qua TCP và dùng QUIC.',"Learned from":"Biết được từ","Alt-Svc header, or DNS":"Tiêu đề Alt-Svc, hoặc DNS","QUIC over UDP 443":"QUIC qua UDP 443","TLS 1.3, built in":"TLS 1.3, tích hợp sẵn","Initial Packets":"Gói Initial","The Client Hello, straight away":"Client Hello, ngay lập tức","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Không có bắt tay TCP riêng: ngay các gói đầu tiên đã mang TLS Client Hello. Với phần khóa hậu lượng tử, nó dài 1,880 byte, quá lớn cho một gói, nên chiếm hai gói Initial. Mỗi datagram được đệm tới ít nhất 1,200 byte; máy chủ chỉ được gửi lại tối đa gấp ba những gì nó nhận, nên địa chỉ gửi giả mạo không biến nó thành bộ khuếch đại.","2 × 1,250 bytes":"2 × 1,250 byte","The TLS Client Hello":"TLS Client Hello","Readable?":"Đọc được?","Yes (Initial keys are public)":"Có (khóa Initial là công khai)","Client Hello, part 1":"Client Hello, phần 1","Client Hello, part 2":"Client Hello, phần 2",padding:"phần đệm","Then the certificate, encrypted":"Rồi chứng chỉ, đã mã hóa","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Máy chủ trả lời bằng Server Hello trong một gói Initial. Giờ cả hai bên tính được khóa bắt tay, nên phần còn lại (chứng chỉ, chữ ký và Finished) đến trong các gói Handshake mà chỉ laptop đọc được. Bốn datagram, thấp hơn nhiều so với gấp ba những gì laptop gửi.","Certificate, signature, Finished":"Chứng chỉ, chữ ký, Finished","Server limit":"Giới hạn máy chủ","3× the bytes received":"3× số byte nhận được","certificate, Finished":"chứng chỉ, Finished","The request, one round trip in":"Yêu cầu, sau một lượt khứ hồi","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"Laptop kiểm tra chứng chỉ và gửi Finished, đồng thời gửi luôn yêu cầu HTTP/3 đầu tiên trong một gói 1-RTT: một khung HEADERS trên luồng 0, với tiêu đề nén bằng QPACK. Một lượt khứ hồi sau gói đầu, yêu cầu đã lên đường; TCP và TLS cộng lại cần hai.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS trên luồng 0",Headers:"Tiêu đề","Compressed (QPACK)":"Đã nén (QPACK)","HTTP/3, stream 0":"HTTP/3, luồng 0","The Response":"Phản hồi","On its own stream":"Trên luồng riêng","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Máy chủ xác nhận bắt tay đã xong (HANDSHAKE_DONE) và trả lời trên luồng 0: tiêu đề, rồi trang. Mỗi yêu cầu có luồng riêng, nên mất gói chỉ làm nghẽn luồng chứa nó. Với TCP, thiếu một đoạn là mọi thứ phía sau phải chờ.","Frames on QUIC streams":"Khung trên luồng QUIC","Holds up one stream":"Nghẽn một luồng","All but a few header bits":"Tất cả trừ vài bit tiêu đề","the page":"trang","New Network":"Mạng mới","Known by ID, not by address":"Nhận diện bằng ID, không bằng địa chỉ","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Kết nối QUIC được nhận diện bằng ID kết nối, không bằng địa chỉ và cổng. Nếu laptop chuyển từ Wi-Fi sang điểm phát của điện thoại, địa chỉ đổi nhưng kết nối vẫn tiếp tục: máy chủ kiểm tra đường mới và đi tiếp. Và ở lần truy cập sau, trình duyệt có thể gửi yêu cầu ngay trong các gói đầu tiên (0-RTT).","Known by":"Nhận diện bằng","Connection ID":"ID kết nối","New address":"Địa chỉ mới","The connection carries on":"Kết nối vẫn tiếp tục","Next visit":"Lần truy cập sau","0-RTT: request at once":"0-RTT: yêu cầu ngay","SAME CONNECTION ON ANY NETWORK":"CÙNG KẾT NỐI TRÊN MỌI MẠNG","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, phần 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, phần 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (chứng chỉ, phần 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (chứng chỉ, phần 2)","Initial packet":"Gói Initial","Header type":"Loại tiêu đề","long header, Initial":"tiêu đề dài, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"Các bit cao cho biết loại gói; các bit cuối được ngụy trang (bảo vệ tiêu đề).","Destination connection ID":"ID kết nối đích","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"Gói này thuộc kết nối nào. Mỗi bên chọn ID riêng; bên kia ghi nó vào đây.","Source connection ID":"ID kết nối nguồn","Token length":"Độ dài token","No token: the server hasn’t asked this client to prove its address first.":"Không có token: máy chủ chưa yêu cầu máy khách này chứng minh địa chỉ trước.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Số gói và payload. Thứ theo sau là một gói khác trong cùng datagram.","Packet number":"Số gói","Hidden by header protection, so nobody on the way can read or change it.":"Bị giấu bởi bảo vệ tiêu đề, nên không ai trên đường đọc hay sửa được.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Mã hóa bằng khóa mà ai cũng tính được từ ID kết nối, nên nó chống sự cố chứ không chống nghe lén: Client Hello bên trong vẫn đọc được trên đường.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, byte 1–1,203 trên 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, phần khóa X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, byte 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, tới 1,250 byte","ACK: packets 0–1 arrived":"ACK: gói 0–1 đã đến","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, kèm nửa phần khóa của nó (1,120 byte)","Handshake packet":"Gói Handshake","long header, Handshake":"tiêu đề dài, Handshake","Encrypted with keys from the key exchange so far.":"Mã hóa bằng khóa từ phần trao đổi khóa đến giờ.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (đầu)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (tiếp)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: Initial của máy chủ đã đến","ACK: the Handshake packets arrived":"ACK: các gói Handshake đã đến","1-RTT packet":"Gói 1-RTT","short header":"tiêu đề ngắn","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Chỉ có ID của bên nhận, và không có độ dài: bên nhận biết ID của chính mình dài bao nhiêu. Nó giữ nguyên nếu laptop đổi mạng.","Encrypted with the session keys.":"Mã hóa bằng khóa phiên.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (luồng điều khiển)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (nén QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: bắt tay đã xong","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, rồi DATA: trang (1,000 byte)","ACK: the response arrived":"ACK: phản hồi đã đến","Address Setup":"Thiết lập địa chỉ","No IPv6 address":"Chưa có địa chỉ IPv6","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC và tìm láng giềng","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"Địa chỉ IPv6 dài 128 bit, đủ để mọi thiết bị có địa chỉ riêng. Một thiết bị thường tự cấu hình được mà không cần máy chủ DHCP: nó tạo địa chỉ link-local, hỏi tìm router và dựng địa chỉ toàn cầu từ tiền tố router quảng bá (SLAAC). Tìm láng giềng, một phần của ICMPv6, tìm địa chỉ MAC và làm việc mà ARP làm cho IPv4.","128 bits":"128 bit",Addresses:"Địa chỉ","SLAAC: no server needed":"SLAAC: không cần máy chủ","Replaces ARP":"Thay thế ARP","Neighbour discovery":"Tìm láng giềng",Optional:"Tùy chọn","Two addresses, no DHCP":"Hai địa chỉ, không DHCP","Made by the laptop itself":"Do chính laptop tạo","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"Laptop tạo một địa chỉ link-local và một địa chỉ toàn cầu, kiểm tra không ai khác dùng chúng, và biết router, MTU và máy chủ DNS từ một lần quảng bá. Khi có gói gửi tới nó, tìm láng giềng đã tìm ra địa chỉ MAC của nó. Nhấn XEM LẠI để xem lại.","Link-local":"Link-local",Global:"Toàn cầu","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + ID riêng","Router, DNS":"Router, DNS","From one advertisement":"Từ một lần quảng bá","6, all ICMPv6":"6, toàn ICMPv6","Link-Local First":"Link-local trước","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Mọi giao diện IPv6 đều có địa chỉ link-local, chỉ dùng được trong mạng của nó. Laptop tạo một địa chỉ từ fe80:: và một ID giao diện 64 bit trông như ngẫu nhiên. Trước hết nó kiểm tra chưa ai dùng: một Neighbor Solicitation hỏi địa chỉ đó, gửi từ :: vì nó chưa được dùng địa chỉ. Không ai trả lời, nên địa chỉ là của laptop.",Check:"Kiểm tra","Duplicate address detection":"Phát hiện địa chỉ trùng","None: the address is free":"Không có: địa chỉ còn trống","IS IT TAKEN?":"CÓ AI DÙNG CHƯA?","from ::":"từ ::","target fe80::8d2e:4f61:a9b0:7c13":"đích fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"KHÔNG AI TRẢ LỜI: ĐỊA CHỈ TRỐNG","Any Routers?":"Có router không?","A Router Solicitation":"Một Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Địa chỉ link-local không ra được Internet. Laptop gửi Router Solicitation tới ff02::2, địa chỉ mà mọi router trong mạng lắng nghe, kèm địa chỉ MAC của nó.","ff02::2 (all routers)":"ff02::2 (mọi router)",Includes:"Kèm theo","ROUTERS?":"ROUTER?","Router Answers":"Router trả lời","Prefix, MTU and DNS in one message":"Tiền tố, MTU và DNS trong một thông điệp","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Router trả lời tới ff02::1, mọi thiết bị trong mạng, bằng Router Advertisement: dùng tôi làm lối ra trong 30 phút, đây là địa chỉ MAC của tôi, MTU là 1500, tiền tố của mạng là 2001:db8:1234:5678::/64 và bạn được tự tạo địa chỉ trong đó, và hỏi DNS ở 2001:4860:4860::8888. Router cũng tự gửi các thông điệp này vài phút một lần.",Prefix:"Tiền tố","Make your own":"Tự tạo địa chỉ","Yes (flag A)":"Có (cờ A)",ADVERTISEMENT:"QUẢNG BÁ","prefix 2001:db8:1234:5678::/64":"tiền tố 2001:db8:1234:5678::/64","A Global Address":"Một địa chỉ toàn cầu","Prefix + interface ID":"Tiền tố + ID giao diện","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"Laptop ghép tiền tố và ID giao diện thành địa chỉ toàn cầu 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, và kiểm tra theo cùng cách. Windows còn tạo một địa chỉ tạm thời với ID ngẫu nhiên đổi mỗi ngày, dùng cho kết nối đi ra để các trang web không theo dõi được một thiết bị qua địa chỉ.","Also made":"Còn tạo","A temporary address":"Một địa chỉ tạm thời","target the global address":"đích là địa chỉ toàn cầu","Neighbour Lookup":"Tra láng giềng","Who has this address? (ARP’s job)":"Ai có địa chỉ này? (việc của ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Một phản hồi từ Internet đến router cho địa chỉ toàn cầu của laptop. Để giao nó, router cần địa chỉ MAC tương ứng: nó gửi Neighbor Solicitation tới nhóm solicited-node của địa chỉ đó, nên chỉ thiết bị có địa chỉ kết thúc giống vậy mới để ý. Laptop trả lời bằng Neighbor Advertisement mang địa chỉ MAC của nó.","Asked to":"Hỏi tới","Instead of":"Thay vì","ARP broadcasts to everyone":"ARP quảng bá cho mọi người","WHO HAS?":"AI CÓ?","the global address":"địa chỉ toàn cầu","Ready, No DHCP":"Sẵn sàng, không DHCP","And no NAT either":"Và cũng không NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"Laptop đã lên Internet với địa chỉ toàn cầu của riêng nó, và không NAT nào đổi nó trên đường: địa chỉ trang web thấy chính là của laptop. Tường lửa của router ở nhà vẫn chặn các kết nối mà không ai bên trong yêu cầu. Mạng nào muốn cấp địa chỉ tập trung có thể dùng DHCPv6.","Not needed":"Không cần",Incoming:"Chiều vào","Blocked by the firewall":"Tường lửa chặn","Optional (flags M, O)":"Tùy chọn (cờ M, O)","ONLINE OVER IPv6":"TRỰC TUYẾN QUA IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Một địa chỉ MAC multicast: 33:33, rồi bốn byte cuối của địa chỉ IPv6.","Version, class, flow":"Phiên bản, lớp, luồng","IPv6, ordinary traffic, no flow label.":"IPv6, lưu lượng thường, không nhãn luồng.","Payload length":"Độ dài payload","What follows this 40-byte header.":"Phần theo sau tiêu đề 40 byte này.","Next header":"Tiêu đề kế tiếp","Hop limit":"Giới hạn chặng","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"Tìm láng giềng phải đến với 255, bằng chứng không router nào chuyển tiếp: nó đến từ mạng này.","Unspecified: the laptop has no address it may use yet.":"Chưa xác định: laptop chưa có địa chỉ nào được dùng.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Multicast solicited-node: chỉ thiết bị có địa chỉ kết thúc bằng cùng 24 bit mới lắng nghe.","Covers the message and both IPv6 addresses.":"Bao phủ thông điệp và cả hai địa chỉ IPv6.",Target:"Đích","The address the laptop wants to use. If anyone answers, it’s taken.":"Địa chỉ laptop muốn dùng. Nếu có ai trả lời, nó đã bị dùng.","A link-local address: usable only on this network.":"Một địa chỉ link-local: chỉ dùng được trong mạng này.","Every router on this network.":"Mọi router trong mạng này.","Source link-layer address":"Địa chỉ tầng liên kết nguồn","The sender’s MAC address, so nobody has to ask for it.":"Địa chỉ MAC của bên gửi, để không ai phải hỏi.","Every device on this network.":"Mọi thiết bị trong mạng này.","The hop limit devices here should put on their packets.":"Giới hạn chặng mà thiết bị ở đây nên đặt cho gói của mình.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: lấy địa chỉ từ DHCPv6. O: lấy thiết lập khác từ DHCPv6. Cả hai tắt: quảng bá này có đủ mọi thứ.","Router lifetime":"Thời gian dùng router","How long the laptop may use this router as its way out.":"Laptop được dùng router này làm lối ra bao lâu.","Reachable time":"Thời gian tới được","0 (not set)":"0 (chưa đặt)","Retransmit timer":"Bộ hẹn giờ truyền lại","The largest packet this network carries.":"Gói lớn nhất mạng này mang được.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, hiệu lực 86,400 s, ưu tiên 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Cờ L và A: địa chỉ trong tiền tố này nằm trên mạng này, và thiết bị được tự tạo địa chỉ (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, trong 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Máy chủ DNS đệ quy: hỏi bộ phân giải nào, nên việc này cũng không cần DHCP.","Whose MAC address is wanted.":"Cần địa chỉ MAC của ai.","The device this frame is for.":"Thiết bị mà khung này gửi tới.","0x60000000: solicited, override":"0x60000000: solicited, override","Solicited: this answers a question. Override: replace any older entry for this address.":"Solicited: đây là trả lời cho một câu hỏi. Override: thay mọi mục cũ hơn của địa chỉ này.","Target link-layer address":"Địa chỉ tầng liên kết đích","The answer: the MAC address that goes with the target.":"Câu trả lời: địa chỉ MAC đi cùng đích.","Setting the Clock":"Chỉnh đồng hồ","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Đồng hồ máy tính lệch vài giây mỗi tuần, mà nhiều thứ phụ thuộc vào nó: chứng chỉ có ngày, đăng nhập và thanh toán có hạn, nhật ký từ nhiều máy phải khớp nhau. NTP chỉnh đồng hồ theo một máy chủ thời gian trên Internet. Một yêu cầu và một phản hồi nhỏ mang bốn dấu thời gian, đủ để tính đồng hồ lệch bao nhiêu và mạng mất bao lâu.",Accuracy:"Độ chính xác","A few milliseconds online":"Vài mili giây khi trực tuyến","Clock set":"Đã chỉnh đồng hồ","Four timestamps, one answer":"Bốn dấu thời gian, một câu trả lời","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Một yêu cầu và một phản hồi cho bốn dấu thời gian. Từ đó laptop tính ra đồng hồ của nó chậm 0.25 s và mạng mất 24 ms cả đi lẫn về, rồi bắt đầu chỉnh dần đồng hồ cho khớp. Nhấn XEM LẠI để xem lại.",Offset:"Độ lệch","250.0 ms (slow)":"250.0 ms (chậm)","Stratum 2":"Stratum 2","Next check":"Lần kiểm tra sau","Minutes to days later":"Vài phút đến vài ngày sau","Clocks Drift":"Đồng hồ bị lệch","The laptop’s clock is a little slow":"Đồng hồ laptop hơi chậm","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Máy tính giữ giờ bằng tinh thể thạch anh chạy hơi nhanh hoặc hơi chậm, nên các đồng hồ lệch nhau vài giây mỗi tuần. Đồng hồ của laptop này chậm một phần tư giây. Windows chỉnh nó theo time.windows.com, địa chỉ đã được tra bằng DNS.","Laptop clock":"Đồng hồ laptop","0.25 s slow":"Chậm 0.25 s","Time server":"Máy chủ thời gian","Why it matters":"Vì sao quan trọng","Certificates, logins, logs":"Chứng chỉ, đăng nhập, nhật ký","CLOCK 0.250 s SLOW":"ĐỒNG HỒ CHẬM 0.250 s","Ask for the Time":"Hỏi giờ","T1: when the request leaves":"T1: khi yêu cầu rời đi","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"Laptop gửi một yêu cầu 48 byte tới cổng 123. Nó ghi vào đó giờ theo đồng hồ của mình lúc yêu cầu rời đi: T1, 09:40:59.750. Mọi thứ khác để trống.","T1 (laptop)":"T1 (laptop)",Mode:"Chế độ","3 (client)":"3 (máy khách)","The Answer":"Câu trả lời","T2 and T3 from the server, T4 on arrival":"T2 và T3 từ máy chủ, T4 khi đến","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Máy chủ chép lại T1, thêm T2, lúc yêu cầu đến, và T3, lúc câu trả lời rời đi, cả hai theo đồng hồ chính xác của nó. Khi câu trả lời đến, laptop ghi T4 theo đồng hồ của mình. Máy chủ là stratum 2: nó chỉnh đồng hồ theo một máy chủ stratum 1, nơi có bộ thu GPS hoặc đồng hồ nguyên tử.","T4 (laptop)":"T4 (laptop)",Stratum:"Stratum","The Offset":"Độ lệch","Four times, two answers":"Bốn thời điểm, hai đáp số","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Thời gian trên mạng, cả đi lẫn về, là (T4 − T1) − (T3 − T2) = 24.0 ms. Độ lệch giả định chiều đi và chiều về mất cùng thời gian: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. Đồng hồ laptop chậm một phần tư giây. Một tuyến không đều (chiều này chậm hơn chiều kia) sẽ làm lệch kết quả tới một nửa chênh lệch.",Assumes:"Giả định","Equal time each way":"Hai chiều bằng nhau","OFFSET +250.0 ms":"ĐỘ LỆCH +250.0 ms","Ease It In":"Chỉnh dần","No jumps backwards":"Không nhảy lùi","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Sai số nhỏ không được sửa bằng một bước nhảy: đồng hồ được cho chạy nhanh hơn chút cho đến khi bắt kịp, nên với chương trình đang chạy, thời gian không bao giờ dừng hay lùi lại. Chỉ sai số lớn mới được đặt lại ngay. Khi đồng hồ ổn định, máy khách NTP hỏi thưa dần, từ mỗi 64 giây đến khoảng mỗi 17 phút; riêng Windows kiểm tra time.windows.com thưa hơn nhiều, vài giờ một lần hoặc ít hơn.","Small offsets":"Độ lệch nhỏ","Eased in gradually":"Chỉnh dần dần","Large offsets":"Độ lệch lớn","Set at once":"Đặt lại ngay","Asks again":"Hỏi lại","Less often as it settles":"Thưa dần khi ổn định","CLOCK IN STEP":"ĐỒNG HỒ ĐÃ KHỚP","Leap, version, mode":"Leap, phiên bản, chế độ","Mode 3: a client asking for the time.":"Chế độ 3: một máy khách hỏi giờ.",Poll:"Poll","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Máy khách định hỏi bao lâu một lần (2 mũ 6 giây). Nó tăng dần khi đồng hồ ổn định.",Precision:"Độ chính xác","How finely this clock can be read.":"Đồng hồ này đọc được mịn tới đâu.","Root delay":"Độ trễ tới gốc","Root dispersion":"Độ phân tán tới gốc","Reference ID":"ID tham chiếu","Reference time":"Thời điểm tham chiếu","Origin time":"Thời điểm gốc","Receive time":"Thời điểm nhận","Transmit time":"Thời điểm gửi","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: lúc yêu cầu rời đi, theo đồng hồ (sai) của chính laptop.","Mode 4: an answer from a server.":"Chế độ 4: câu trả lời từ máy chủ.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Cách đồng hồ tham chiếu hai bước: nó theo một máy chủ stratum 1 có GPS hoặc đồng hồ nguyên tử riêng.","Round-trip time from this server to the reference clock.":"Thời gian khứ hồi từ máy chủ này tới đồng hồ tham chiếu.","How far off this server could be, at most.":"Máy chủ này có thể lệch tối đa bao nhiêu.","192.0.2.123 (its own time source)":"192.0.2.123 (nguồn thời gian của nó)","When this server last set its own clock.":"Lần cuối máy chủ này chỉnh đồng hồ của mình.","T1, copied from the request: the client can match the answer to its question.":"T1, chép từ yêu cầu: máy khách ghép được câu trả lời với câu hỏi của mình.","T2: when the request arrived, by the server’s clock.":"T2: lúc yêu cầu đến, theo đồng hồ máy chủ.","T3: when this answer left.":"T3: lúc câu trả lời này rời đi.",Private:"Riêng tư","Plain DNS":"DNS thường","DNS inside HTTPS":"DNS bên trong HTTPS","DNS queries inside HTTPS":"Truy vấn DNS bên trong HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"DNS thông thường đi dạng rõ: ai cùng Wi-Fi, và nhà mạng của bạn, đều đọc được mọi tên bạn tra và thậm chí sửa câu trả lời. DNS over HTTPS (DoH) gửi cùng các thông điệp DNS đó bên trong một kết nối HTTPS mã hóa tới bộ phân giải, nên trên đường chúng trông như mọi lưu lượng web khác. Trình duyệt và hệ điều hành có thể bật nó.","Ordinary DNS messages":"Thông điệp DNS thông thường",Hides:"Giấu","Which names you look up":"Bạn tra tên nào",Similar:"Tương tự","DNS over TLS (port 853)":"DNS over TLS (cổng 853)","Looked up in private":"Tra cứu riêng tư","Same question, sealed":"Cùng câu hỏi, đã niêm phong","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"Tra cứu thường ai trên đường cũng đọc được. Qua HTTPS, cùng thông điệp DNS đó được niêm phong trong TLS, chỉ bộ phân giải đọc được. Bộ phân giải vẫn thấy mọi câu hỏi, nên lòng tin chuyển sang nó, và trang bạn truy cập sau đó vẫn bị thấy qua địa chỉ. Nhấn XEM LẠI để xem lại.","On the way":"Trên đường","Only “HTTPS to dns.google”":"Chỉ “HTTPS tới dns.google”","The resolver":"Bộ phân giải","Still sees every name":"Vẫn thấy mọi tên","The site’s address you then visit":"Địa chỉ của trang bạn truy cập sau đó","Can’t be changed on the way":"Không sửa được trên đường","Readable by anyone on the way":"Ai trên đường cũng đọc được","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Đây là tra cứu trong các bài khác: một gói UDP tới cổng 53 hỏi www.example.com, và câu trả lời. Cả hai đều không mã hóa, nên mọi người trên Wi-Fi quán cà phê, và nhà mạng, đều thấy laptop tra tên nào, và thậm chí có thể trả lời bằng địa chỉ giả.","UDP port 53":"Cổng UDP 53","Can be changed":"Có thể bị sửa","Yes, on the way":"Có, trên đường",readable:"đọc được","ANYONE HERE CAN READ IT":"AI Ở ĐÂY CŨNG ĐỌC ĐƯỢC","An HTTPS Link":"Một liên kết HTTPS","TCP and TLS to dns.google":"TCP và TLS tới dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Khi bật DNS over HTTPS, trình duyệt mở một kết nối HTTPS tới bộ phân giải: TCP tới cổng 443 và bắt tay TLS cho dns.google. Nó giữ kết nối này mở và gửi mọi lượt tra cứu qua đó.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, như mọi trang web","Kept open":"Giữ mở","For every lookup":"Cho mọi lượt tra cứu","Sealed Question":"Câu hỏi đã niêm phong","A DNS message in an HTTP request":"Thông điệp DNS trong yêu cầu HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"Câu hỏi vẫn là thông điệp DNS như trước. Nó đi trong một yêu cầu HTTP/2, GET /dns-query?dns= theo sau là thông điệp dạng base64url, xin câu trả lời kiểu application/dns-message. Bên trong TLS, không ai trên đường đọc được.",Format:"Định dạng","application/dns-message":"application/dns-message","Encrypted (TLS)":"Đã mã hóa (TLS)","DoH QUERY":"TRUY VẤN DoH","inside: GET /dns-query?dns=…":"bên trong: GET /dns-query?dns=…","Sealed Answer":"Câu trả lời đã niêm phong","The DNS answer in an HTTP response":"Câu trả lời DNS trong phản hồi HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Bộ phân giải trả lời 200 với phần thân kiểu application/dns-message: cùng câu trả lời DNS như tra cứu thường, A 203.0.113.10. Vì nó đến qua TLS từ dns.google, không ai trên đường sửa được.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"Câu trả lời DNS (49 byte)",Tampering:"Can thiệp","Impossible on the way":"Không thể trên đường","DoH ANSWER":"TRẢ LỜI DoH","inside: A 203.0.113.10":"bên trong: A 203.0.113.10","What Still Shows":"Những gì vẫn lộ","Hidden on the way, not from the resolver":"Giấu trên đường, không giấu bộ phân giải","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Trên đường, các lượt tra cứu giờ trông như lưu lượng HTTPS thường tới dns.google. Nhưng chính bộ phân giải đọc mọi câu hỏi, nên bạn tin nó thay vì người quản lý mạng của bạn. Và trang bạn truy cập sau đó vẫn bị thấy qua địa chỉ IP, và qua tên trong TLS Client Hello trừ khi nó hỗ trợ Encrypted Client Hello. DNS over TLS làm cùng việc trên cổng 853.","Sees every name":"Thấy mọi tên","Then visible":"Sau đó lộ ra","The site’s IP, maybe its name":"IP của trang, có thể cả tên",Alternative:"Lựa chọn khác","TRUST MOVES TO THE RESOLVER":"LÒNG TIN CHUYỂN SANG BỘ PHÂN GIẢI","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: truy vấn DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: trả lời DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: phần mở đầu kết nối và thiết lập, rồi yêu cầu","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: thiết lập, tiêu đề phản hồi, rồi câu trả lời DNS","Signed Answers":"Câu trả lời có chữ ký","Question and answer":"Câu hỏi và câu trả lời","To the name servers":"Tới máy chủ tên","Signed answers":"Câu trả lời có chữ ký","DNS Security Extensions":"DNS Security Extensions","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Câu trả lời DNS thường có thể bị giả mạo: ai trả lời trước, hoặc đứng giữa, có thể gửi địa chỉ giả. DNSSEC cho bộ phân giải kiểm tra câu trả lời có thật sự đến từ chủ tên miền không. Mỗi tập bản ghi đều được ký; khóa của mỗi vùng được vùng cha bảo đảm, lên tới gốc, khóa của gốc được tích hợp sẵn trong bộ phân giải. DNSSEC chứng minh câu trả lời là thật; nó không giấu chúng.","Adds records":"Thêm bản ghi","Checked by":"Kiểm tra bởi","Trust anchor":"Mốc tin cậy","The root’s key (built in)":"Khóa của gốc (tích hợp sẵn)","Hides queries":"Giấu truy vấn","No (that’s DoH)":"Không (đó là DoH)","Answer checked":"Đã kiểm tra câu trả lời","A chain of signatures to the root":"Chuỗi chữ ký tới gốc","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Bộ phân giải lần theo một chuỗi: địa chỉ được ký bằng khóa của example.com, khóa đó được ký bằng khóa ký khóa, được .com bảo đảm bằng bản ghi DS có chữ ký, và khóa của .com được gốc bảo đảm, khóa của gốc được tích hợp sẵn trong bộ phân giải. Một câu trả lời giả sẽ làm đứt chuỗi. Nhấn XEM LẠI để xem lại.","Signatures checked":"Chữ ký đã kiểm tra","3 here (plus cached ones)":"3 ở đây (cộng các chữ ký đã lưu đệm)","The AD flag":"Cờ AD","Forged answer":"Câu trả lời giả","Fails the check":"Không qua kiểm tra","Ask as Usual":"Hỏi như thường","The laptop’s question doesn’t change":"Câu hỏi của laptop không đổi","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"Laptop hỏi bộ phân giải www.example.com như mọi khi. Việc kiểm tra diễn ra ở bộ phân giải, nó hỏi các máy chủ tên với cờ DNSSEC OK bật: gửi kèm cả chữ ký.","Checking done by":"Ai kiểm tra","The resolver (8.8.8.8)":"Bộ phân giải (8.8.8.8)","Resolver sets":"Bộ phân giải đặt","Signed Answer":"Câu trả lời có chữ ký","An RRSIG comes with the A record":"Kèm bản ghi A là một RRSIG","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Bộ phân giải đã biết máy chủ tên của example.com từ các lần tra trước. Máy chủ đó gửi địa chỉ kèm bản ghi RRSIG: chữ ký trên bản ghi A, tạo bằng khóa riêng của vùng. RRSIG cho biết khóa nào đã ký (khóa 47362, khóa ký vùng) và khi nào chữ ký hết hạn. Để kiểm tra, bộ phân giải cần khóa đó.","RRSIG by key 47362":"RRSIG bằng khóa 47362",Valid:"Hiệu lực","31 Oct to 21 Nov 2026":"31/10 đến 21/11/2026","signed by key 47362":"ký bằng khóa 47362","The Zone’s Keys":"Khóa của vùng","DNSKEY records, signed too":"Bản ghi DNSKEY, cũng có chữ ký","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Bộ phân giải xin các khóa của example.com. Có hai khóa: khóa ký vùng (cờ 256) đã ký bản ghi A, và khóa ký khóa (cờ 257), chỉ ký tập các khóa. Với chúng, bộ phân giải kiểm tra cả hai chữ ký. Nhưng ai nói các khóa này thuộc về example.com?","47362, zone-signing (256)":"47362, ký vùng (256)","61845, key-signing (257)":"61845, ký khóa (257)","Keys signed by":"Khóa được ký bởi","The key-signing key":"Khóa ký khóa","two keys":"hai khóa","signed by key 61845":"ký bằng khóa 61845","Vouched by .com":".com bảo đảm","The parent’s DS record":"Bản ghi DS của vùng cha","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"Vùng cha trả lời câu đó. Các máy chủ .com giữ một bản ghi DS cho example.com: băm của khóa ký khóa của nó, ký bằng khóa của chính .com. Nếu băm khớp với khóa 61845, các khóa là của example.com, theo .com xác nhận.","Hash of key 61845":"Băm của khóa 61845","Signed by":"Ký bởi",".com (key 19718)":".com (khóa 19718)",Matches:"Khớp với","hash of key 61845":"băm của khóa 61845","signed by .com":"ký bởi .com","Up to the Root":"Lên tới gốc","Where the chain ends":"Nơi chuỗi kết thúc","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Phía trên cũng vậy: các khóa của .com được một bản ghi DS trong vùng gốc bảo đảm, ký bằng khóa của gốc, và khóa đó được tích hợp trong mọi bộ phân giải có xác thực: mốc tin cậy. Bộ phân giải đã lưu đệm các mắt xích đó, nên chuỗi đầy đủ: gốc → .com → example.com → địa chỉ.",".com’s key":"Khóa của .com","Vouched for by the root":"Được gốc bảo đảm","Root’s key":"Khóa của gốc","Built in (trust anchor)":"Tích hợp sẵn (mốc tin cậy)","Root → .com → example.com":"Gốc → .com → example.com","CHAIN OF TRUST CHECKED":"ĐÃ KIỂM TRA CHUỖI TIN CẬY","A Checked Answer":"Câu trả lời đã kiểm tra","With the AD flag":"Kèm cờ AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Bộ phân giải trả lời laptop bằng địa chỉ và cờ AD: dữ liệu đã xác thực. Nếu có chữ ký nào sai, laptop sẽ nhận lỗi (SERVFAIL) thay vì một địa chỉ giả. DNSSEC không giấu câu hỏi hay câu trả lời; việc đó dành cho DNS over HTTPS.",Flag:"Cờ","AD (authenticated data)":"AD (dữ liệu đã xác thực)","Bad signature":"Chữ ký sai","SERVFAIL, no address":"SERVFAIL, không có địa chỉ","AD: checked":"AD: đã kiểm tra","UDP size 1232, DNSSEC OK = 1":"Kích thước UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Cho biết câu trả lời UDP có thể lớn đến đâu, và DNSSEC OK: gửi kèm cả chữ ký.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, ký bằng khóa 47362 của example.com, hiệu lực 2026-10-31 đến 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Chữ ký trên các bản ghi phía trên, tạo bằng khóa riêng của vùng.","example.com, type DNSKEY, class IN":"example.com, loại DNSKEY, lớp IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (khóa ký vùng 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Một trong các khóa công khai của vùng; ai kiểm tra chữ ký cũng cần nó.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (khóa ký khóa 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, ký bằng khóa 61845 của example.com, hiệu lực 2026-10-31 đến 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, loại DS, lớp IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS khóa 61845, băm SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Băm của khóa ký khóa của vùng con, do vùng cha giữ và ký.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, ký bằng khóa 19718 của com, hiệu lực 2026-10-31 đến 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: phản hồi, RD (yêu cầu đệ quy), RA (có hỗ trợ đệ quy), AD (dữ liệu đã xác thực)","Wi-Fi Logins":"Đăng nhập Wi-Fi","EAP over Wi-Fi":"EAP qua Wi-Fi","RADIUS Server":"Máy chủ RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS và 802.1X (Wi-Fi doanh nghiệp)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"Ở nhà mọi người dùng chung một mật khẩu Wi-Fi. Văn phòng, trường đại học và eduroam dùng WPA2- hoặc WPA3-Enterprise: mỗi người hoặc thiết bị đăng nhập bằng tài khoản hay chứng chỉ riêng, do một máy chủ RADIUS kiểm tra. Điểm truy cập không biết mật khẩu nào. Nó chuyển phần đăng nhập, một loạt thông điệp EAP, giữa laptop và máy chủ, và chỉ cho laptop vào khi máy chủ đồng ý.","EAP (here EAP-TLS)":"EAP (ở đây là EAP-TLS)",Keys:"Khóa","Different for every login":"Khác nhau mỗi lần đăng nhập","Let in":"Đã cho vào","Its own login, its own keys":"Đăng nhập riêng, khóa riêng","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"Laptop chứng minh danh tính bằng chứng chỉ. Máy chủ RADIUS kiểm tra và bảo điểm truy cập cho nó vào, trên VLAN 20, với một khóa chỉ dành cho lần đăng nhập này. Điểm truy cập không hề thấy mật khẩu: nó chỉ chuyển các thông điệp. Nhấn XEM LẠI để xem lại.","EAP-TLS (certificates)":"EAP-TLS (chứng chỉ)","17, then the 4-way handshake":"17, rồi bắt tay 4 bước","20 (staff)":"20 (nhân viên)","A user leaves":"Một người rời đi","Disable one account":"Vô hiệu hóa một tài khoản","Who Are You?":"Bạn là ai?","The access point asks for an identity":"Điểm truy cập hỏi danh tính","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"Laptop đã vào “Office”, một mạng WPA2-Enterprise, nhưng cho đến khi đăng nhập, điểm truy cập không cho qua gì ngoài thông điệp đăng nhập. Nó hỏi laptop là ai bằng yêu cầu EAP Identity, và laptop trả lời alex@example.org. Điểm truy cập không biết tài khoản nào: nó sẽ chuyển câu trả lời tới máy chủ RADIUS.","Before login":"Trước khi đăng nhập","Only EAP gets through":"Chỉ EAP đi qua","IDENTITY?":"DANH TÍNH?","EAP Identity request":"Yêu cầu EAP Identity",IDENTITY:"DANH TÍNH","Ask RADIUS":"Hỏi RADIUS","The login goes to the server":"Phần đăng nhập tới máy chủ","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Điểm truy cập chép thông điệp EAP vào một RADIUS Access-Request và gửi tới máy chủ RADIUS trên cổng UDP 1812, kèm địa chỉ MAC của laptop và tên mạng. Một bí mật chỉ hai bên biết bảo vệ mọi gói. Máy chủ trả lời bằng Access-Challenge: thông điệp tiếp theo cho laptop, tức “bắt đầu EAP-TLS”.","RADIUS server, UDP 1812":"Máy chủ RADIUS, UDP 1812","A shared secret":"Một bí mật dùng chung","from the access point":"từ điểm truy cập","EAP-TLS start":"bắt đầu EAP-TLS","TLS START":"BẮT ĐẦU TLS","TLS Inside EAP":"TLS bên trong EAP","The server proves who it is":"Máy chủ chứng minh danh tính","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"Giờ laptop và máy chủ chạy bắt tay TLS 1.3 bên trong EAP; điểm truy cập đóng gói lại mỗi thông điệp, EAPOL qua sóng và RADIUS qua dây. Máy chủ gửi chứng chỉ và xin chứng chỉ của laptop. Laptop kiểm tra rằng nó do tổ chức chứng thực của chính công ty cấp cho radius.example.org. Bước kiểm tra đó ngăn điểm truy cập giả bắt được phần đăng nhập.","TLS 1.3, inside EAP":"TLS 1.3, bên trong EAP","Its certificate":"Chứng chỉ của nó","Laptop checks":"Laptop kiểm tra","Issuer and name":"Nơi cấp và tên","TLS inside EAP":"TLS bên trong EAP","certificate (encrypted)":"chứng chỉ (đã mã hóa)","Laptop’s Proof":"Bằng chứng của laptop","Its own certificate":"Chứng chỉ của chính nó","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"Laptop trả lời bằng chứng chỉ của nó, do công ty cấp cho người dùng này, và một chữ ký tạo bằng khóa riêng; khóa không bao giờ rời laptop. Không cần mật khẩu. Máy chủ kiểm tra chứng chỉ và chữ ký rồi tra tài khoản. Nhiều mạng, trong đó có eduroam, dùng mật khẩu thay vào đó, gửi bên trong đường hầm TLS (PEAP hoặc EAP-TTLS).","Its certificate, a signature":"Chứng chỉ, một chữ ký","None with EAP-TLS":"Không có với EAP-TLS","Or instead":"Hoặc thay vào đó","PEAP: a password in TLS":"PEAP: mật khẩu trong TLS",CERTIFICATE:"CHỨNG CHỈ","laptop’s certificate":"chứng chỉ của laptop","Handshake Done":"Bắt tay xong","Nothing more to send":"Không còn gì để gửi","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Với TLS 1.3, máy chủ sau đó gửi một thông điệp mã hóa tí hon, một byte 0, để báo bắt tay đã xong, và laptop trả lời bằng một thông điệp EAP rỗng. Giờ cả hai đầu có cùng 64 byte vật liệu khóa, tính ra trong lúc bắt tay. Không ai trên đường thấy nó, kể cả điểm truy cập.","Server sends":"Máy chủ gửi","One encrypted 0 byte":"Một byte 0 đã mã hóa","An empty EAP-TLS reply":"Một trả lời EAP-TLS rỗng","Both hold":"Cả hai có","64 bytes of key material":"64 byte vật liệu khóa","handshake over":"bắt tay xong","one encrypted byte":"một byte đã mã hóa",EMPTY:"RỖNG","nothing more":"không còn gì","empty EAP-TLS":"EAP-TLS rỗng","And a key for the access point":"Và một khóa cho điểm truy cập","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Máy chủ trả lời Access-Accept. Bên trong có EAP Success cho laptop; 32 byte đầu của vật liệu khóa cho điểm truy cập, mã hóa bằng bí mật dùng chung (MS-MPPE-Recv-Key); và VLAN 20, để người dùng này vào mạng nhân viên. Cùng điểm truy cập đó có thể đặt người dùng khác vào VLAN khác.","AP gets":"AP nhận","The key (MS-MPPE-Recv-Key)":"Khóa (MS-MPPE-Recv-Key)","key, VLAN 20":"khóa, VLAN 20","4-Way Handshake":"Bắt tay 4 bước","As at home, from a different key":"Như ở nhà, từ một khóa khác","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Giờ điểm truy cập và laptop có cùng một khóa 32 byte, PMK. Tiếp theo là bắt tay 4 bước trong bài Wi-Fi; chỉ nguồn gốc của PMK khác. Ở nhà nó đến từ mật khẩu chung, ở đây từ chính lần đăng nhập này, nên mỗi người dùng có khóa khác nhau.","PMK from":"PMK từ","This login":"Lần đăng nhập này","At home":"Ở nhà","From the shared password":"Từ mật khẩu chung","Encrypted data (CCMP)":"Dữ liệu đã mã hóa (CCMP)","group key, MIC":"khóa nhóm, MIC","Why Enterprise":"Vì sao Enterprise","One account per person":"Mỗi người một tài khoản","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Khi ai đó rời đi, tài khoản của họ bị vô hiệu hóa và không ai khác phải đổi mật khẩu. Mỗi lần đăng nhập có khóa riêng, nên người dùng không đọc được lưu lượng của nhau, và máy chủ RADIUS ghi lại ai đã kết nối và khi nào. eduroam hoạt động cùng cách: lần đăng nhập của một khách cho user@trường-của-họ được chuyển từ máy chủ RADIUS này sang máy chủ RADIUS khác cho đến khi tới trường của họ.","Different for every user":"Khác nhau cho mỗi người dùng",eduroam:"eduroam","Login passed home":"Đăng nhập được chuyển về nhà","ONE ACCOUNT PER PERSON":"MỖI NGƯỜI MỘT TÀI KHOẢN","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, chứng chỉ","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, bắt tay đã mã hóa","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: bắt tay đã mã hóa","Access-Request id=83: encrypted handshake":"Access-Request id=83: bắt tay đã mã hóa","0 (EAP packet)":"0 (gói EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Mang một thông điệp EAP. Điểm truy cập chép nó vào một gói RADIUS cho máy chủ, và ngược lại.","A response carries the same number as the request it answers.":"Phản hồi mang cùng số với yêu cầu mà nó trả lời.","Who are you?":"Bạn là ai?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Ai đang đăng nhập. Realm sau dấu @ cho máy chủ RADIUS (hoặc các máy chủ chuyển tiếp yêu cầu) biết tài khoản nằm ở đâu.","Seen on the office network":"Thấy trên mạng văn phòng","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Máy chủ. Nó ở cùng mạng, nên khung đi thẳng tới nó, không qua router.","The access point’s wired port.":"Cổng có dây của điểm truy cập.","Should this device be let in?":"Có nên cho thiết bị này vào không?","A reply carries the number of the request it answers.":"Phản hồi mang số của yêu cầu mà nó trả lời.",Authenticator:"Authenticator","Random, new in every request.":"Ngẫu nhiên, mới trong mỗi yêu cầu.",Attributes:"Thuộc tính","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Một HMAC-MD5 của cả gói, tính bằng bí mật dùng chung. Mọi gói mang EAP đều phải có; từ vụ tấn công Blast-RADIUS năm 2024, nó được đặt đầu tiên.","The identity the laptop gave.":"Danh tính laptop đã đưa.","The access point asking.":"Điểm truy cập đang hỏi.","The access point’s MAC address and the network’s name.":"Địa chỉ MAC của điểm truy cập và tên mạng.","The laptop’s MAC address.":"Địa chỉ MAC của laptop.","Keep each EAP message small enough for one frame.":"Giữ mỗi thông điệp EAP đủ nhỏ để vừa một khung.","The EAP packet, passed on unchanged.":"Gói EAP, chuyển nguyên vẹn.","The server’s network card.":"Card mạng của máy chủ.","Not yet: here is the next message for the device.":"Chưa: đây là thông điệp tiếp theo cho thiết bị.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Băm của phản hồi này, authenticator của yêu cầu và bí mật dùng chung: chỉ máy chủ thật mới tạo được.","A TLS handshake, carried inside EAP.":"Một bắt tay TLS, được mang bên trong EAP.","0x20 (start)":"0x20 (bắt đầu)","Start: the server is ready for the laptop’s Client Hello.":"Bắt đầu: máy chủ sẵn sàng nhận Client Hello của laptop.","The server’s bookmark for this login: the access point sends it back with the next request.":"Dấu trang của máy chủ cho lần đăng nhập này: điểm truy cập gửi lại nó trong yêu cầu tiếp theo.","0x80 (length included)":"0x80 (có kèm độ dài)","TLS length":"Độ dài TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Thông điệp TLS dài hơn được chia thành các mảnh khoảng 1,000 byte, mỗi mảnh được xác nhận.","TLS records":"Bản ghi TLS","The same TLS records as over TCP, only carried in EAP.":"Cùng bản ghi TLS như qua TCP, chỉ là mang trong EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, phần khóa của laptop","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Gói EAP (1,008 byte), chia thành 4 thuộc tính tối đa 253 byte.","EAP-Message, continued":"EAP-Message, tiếp","TLS records, continued":"Bản ghi TLS, tiếp","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, phần khóa của máy chủ","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Đã mã hóa: chứng chỉ cho radius.example.org, yêu cầu chứng chỉ của laptop, chữ ký, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Đã mã hóa: chứng chỉ của laptop (cho alex@example.org), chữ ký của nó, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Gói EAP (822 byte), chia thành 4 thuộc tính tối đa 253 byte.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Đã mã hóa: một byte 0, “thông điệp cam kết”: không còn thông điệp bắt tay nào","0x00 (no data)":"0x00 (không dữ liệu)","Nothing to send: an empty answer that keeps the conversation going.":"Không có gì để gửi: một câu trả lời rỗng để cuộc trao đổi tiếp tục.","Yes: let it in.":"Có: cho nó vào.","Put this device on VLAN 20, the staff network.":"Đặt thiết bị này vào VLAN 20, mạng nhân viên.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"32 byte đầu của vật liệu khóa mà cả hai đầu của bắt tay TLS đã tính ra. Điểm truy cập dùng nó làm PMK, khóa khởi đầu cho bắt tay 4 bước.","Salt, encrypted key":"Salt, khóa đã mã hóa","Encrypted with the shared secret, so only the access point can read the key.":"Mã hóa bằng bí mật dùng chung, nên chỉ điểm truy cập đọc được khóa.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"32 byte tiếp theo của vật liệu khóa. Wi-Fi không cần chúng.","The RADIUS server accepted the login.":"Máy chủ RADIUS đã chấp nhận đăng nhập.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (đăng nhập do máy chủ RADIUS kiểm tra)","Shared Folders":"Thư mục dùng chung",Responses:"Phản hồi","nas (File Server)":"nas (máy chủ tệp)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB là cách Windows chia sẻ tệp và máy in: \\\\server\\share trong File Explorer, một ổ mạng đã ánh xạ, một NAS ở nhà. macOS và Linux cũng nói được. Qua một kết nối TCP tới cổng 445, máy khách thỏa thuận phiên bản, đăng nhập và kết nối tới một thư mục chia sẻ, rồi mở, đọc, ghi và đóng tệp bằng các yêu cầu được đánh số.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM hoặc Kerberos",Protection:"Bảo vệ","Signing, optional encryption":"Ký, mã hóa tùy chọn","File read":"Đã đọc tệp","Seven requests, one connection":"Bảy yêu cầu, một kết nối","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Qua một kết nối TCP, laptop thỏa thuận SMB 3.1.1, đăng nhập bằng NTLM mà không gửi mật khẩu, kết nối tới thư mục chia sẻ và đọc một tệp 240 KB chỉ bằng một yêu cầu. Mọi thông điệp sau khi đăng nhập đều được ký. Nhấn XEM LẠI để xem lại.","7 on one connection":"7 trên một kết nối","NTLMv2, no password sent":"NTLMv2, không gửi mật khẩu","240 KB in 169 segments":"240 KB trong 169 đoạn",Signed:"Được ký","Every message after login":"Mọi thông điệp sau đăng nhập","Port 445":"Cổng 445","A TCP connection to the NAS":"Một kết nối TCP tới NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"Laptop mở \\\\nas\\Documents, một thư mục chia sẻ trên NAS. Nó tìm địa chỉ của nas bằng tra tên cục bộ và mở kết nối TCP tới cổng 445. Các gói đi qua router ở nhà tới NAS và không bao giờ rời mạng gia đình.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Nằm lại","On the home network":"Trong mạng gia đình",Negotiate:"Negotiate","Agree on a version":"Thỏa thuận phiên bản","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"Laptop liệt kê mọi phiên bản SMB nó nói được, từ 2.0.2 đến 3.1.1, và nói nó yêu cầu ký. NAS chọn 3.1.1, mới nhất. Cả hai bên giữ một giá trị băm SHA-512 của mọi thứ trao đổi từ đây cho tới khi đăng nhập xong. Nó đi vào khóa, nên nếu ai sửa các thông điệp này trên đường, chẳng hạn để ép dùng phiên bản cũ hơn, việc đăng nhập sẽ thất bại.",Chosen:"Đã chọn","Tamper check":"Chống can thiệp","SHA-512 of the exchange":"SHA-512 của cuộc trao đổi","signing required":"bắt buộc ký","NTLM Challenge":"Thử thách NTLM","The NAS sends a random number":"NAS gửi một số ngẫu nhiên","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"NAS ở nhà không có miền, nên không có Kerberos: laptop đăng nhập bằng NTLM. SESSION_SETUP đầu tiên của nó nói nó muốn đăng nhập, và NAS trả lời “cần xử lý thêm” kèm một thử thách 8 byte ngẫu nhiên. Nó cũng cấp cho lần đăng nhập này một ID phiên.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (trong miền: Kerberos)",Challenge:"Thử thách","More processing required":"Cần xử lý thêm","NTLM: let me log in":"NTLM: cho tôi đăng nhập","a session ID":"một ID phiên","NTLM Response":"Trả lời NTLM","Proof, not the password":"Bằng chứng, không phải mật khẩu","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"Laptop trả lời bằng tên người dùng, alex, và một trả lời NTLMv2: một HMAC của thử thách và vài giá trị khác, tính bằng giá trị băm của mật khẩu. NAS có cùng giá trị băm và tính ra cùng kết quả. Bản thân mật khẩu không bao giờ đi qua mạng, và giờ cả hai bên có một khóa phiên để ký thông điệp.",User:"Người dùng",alex:"alex",Sends:"Gửi","An HMAC of the challenge":"Một HMAC của thử thách","Never sent":"Không bao giờ gửi","user alex":"người dùng alex","NTLMv2 response":"trả lời NTLMv2","LOGGED IN":"ĐÃ ĐĂNG NHẬP",signed:"đã ký","Connect a Share":"Kết nối thư mục chia sẻ","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT xin thư mục chia sẻ bằng tên đầy đủ, \\\\nas\\Documents. Câu trả lời cấp cho nó một tree ID và cho biết người dùng này được làm gì ở đó. Giờ mọi thông điệp đều được ký: mỗi thông điệp mang một thẻ trên toàn bộ thông điệp, tạo bằng khóa từ lần đăng nhập, nên thông điệp bị sửa hay giả mạo sẽ bị phát hiện.",Share:"Thư mục chia sẻ","Every message":"Mọi thông điệp","Signed (AES-GMAC)":"Được ký (AES-GMAC)","tree ID 0x2a51":"tree ID 0x2a51","Open the File":"Mở tệp","With CREATE":"Bằng CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB mở tệp bằng CREATE, lệnh này cũng có thể tạo tệp mới. Lần này nó mở report.pdf để đọc, và thất bại nếu tệp không tồn tại. Câu trả lời cho biết kích thước và ngày của tệp, cùng một file ID mà lệnh đọc và đóng sẽ dùng.",Handle:"Handle","A 16-byte file ID":"Một file ID 16 byte","open to read":"mở để đọc","file ID":"file ID","Read It":"Đọc tệp","The whole file in one request":"Cả tệp trong một yêu cầu","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Một READ xin cả tệp, 245,760 byte từ vị trí 0. Nó tốn 4 credit, mỗi 64 KB một credit. Câu trả lời là 80 byte tiêu đề rồi đến tệp, trong 169 đoạn TCP. Tệp lớn hơn được đọc bằng nhiều yêu cầu, nhiều yêu cầu đi cùng lúc, trong giới hạn credit cho phép.","245,760 bytes from 0":"245,760 byte từ 0",Credits:"Credit","4 (one per 64 KB)":"4 (mỗi 64 KB một)","Arrives in":"Đến trong","from offset 0":"từ vị trí 0","Close the File":"Đóng tệp","And keep 445 at home":"Và giữ cổng 445 trong nhà","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE trả lại file ID; kết nối vẫn mở cho tệp tiếp theo. SMB 3 còn có thể mã hóa mọi thông điệp bằng AES-GCM, cho một thư mục chia sẻ hay cả máy chủ. Ở đây chỉ chữ ký bảo vệ thông điệp, nên ai trong mạng cũng đọc được tệp khi nó đi qua. Cổng 445 không bao giờ nên mở ra Internet: sâu WannaCry (2017) lây lan qua một lỗ hổng trong SMB1 cũ.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, tùy chọn","Switched off: old, unsafe":"Đã tắt: cũ, không an toàn","Never open to the internet":"Không bao giờ mở ra Internet",done:"xong","KEEP PORT 445 OFF THE INTERNET":"ĐỪNG ĐỂ CỔNG 445 RA INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Trên cổng 445, mọi thông điệp SMB bắt đầu bằng độ dài của nó, di sản của NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 hoặc 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'Thông điệp SMB1 bắt đầu bằng 0xFF "SMB". Ngày nay SMB1 bị tắt trong Windows.',"Header size":"Kích thước tiêu đề","Credit charge":"Phí credit","Channel sequence":"Thứ tự kênh","Credits asked for":"Credit xin","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Credit giới hạn số yêu cầu laptop được để chờ cùng lúc. Máy chủ cấp phát chúng.","Next command":"Lệnh kế tiếp","0 (none chained)":"0 (không nối chuỗi)","Counts up with each request; the response carries the same number.":"Tăng theo mỗi yêu cầu; phản hồi mang cùng số.","0 (no share yet)":"0 (chưa có thư mục chia sẻ)","Session ID":"ID phiên","0 (not logged in yet)":"0 (chưa đăng nhập)","zeros (not signed)":"toàn số 0 (chưa ký)","Structure size":"Kích thước cấu trúc","Dialect count":"Số phương ngữ","Security mode":"Chế độ bảo mật","0x0002 (signing required)":"0x0002 (bắt buộc ký)","Recent versions of Windows 11 require signing by default.":"Các phiên bản Windows 11 gần đây mặc định yêu cầu ký.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, lease, đọc và ghi lớn, đa kênh, handle bền vững, lease thư mục, mã hóa.","Client GUID":"GUID máy khách","A random ID for this computer.":"Một ID ngẫu nhiên cho máy tính này.","Negotiate contexts":"Ngữ cảnh thương lượng","at offset 112, 4 of them":"ở vị trí 112, gồm 4 cái",Dialects:"Phương ngữ","Every version the laptop speaks. The server picks the newest it also knows.":"Mọi phiên bản laptop nói được. Máy chủ chọn bản mới nhất mà nó cũng biết.",Contexts:"Ngữ cảnh","SMB 3.1.1 extras, each in its own small block.":"Phần bổ sung của SMB 3.1.1, mỗi phần trong một khối nhỏ riêng.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Toàn vẹn trước xác thực: SHA-512, và một salt ngẫu nhiên 32 byte","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Mã hóa: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Ký: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Tên máy chủ: nas","Credits granted":"Credit được cấp","0x00000001 (response)":"0x00000001 (phản hồi)","0x0001 (signing enabled)":"0x0001 (đã bật ký)",Dialect:"Phương ngữ","The newest version both sides speak.":"Phiên bản mới nhất cả hai bên đều nói được.","Context count":"Số ngữ cảnh","Server GUID":"GUID máy chủ","Leases, large reads and writes.":"Lease, đọc và ghi lớn.","Largest read, write":"Đọc, ghi tối đa","8 MB each":"8 MB mỗi loại","The most data one request may carry: transactions, reads and writes.":"Lượng dữ liệu tối đa một yêu cầu được mang: giao dịch, đọc và ghi.","System time":"Giờ hệ thống","7 Nov 2026, 09:41:00":"7/11/2026, 09:41:00","Security buffer":"Bộ đệm bảo mật","Context offset":"Vị trí ngữ cảnh","Security blob":"Khối bảo mật","GSS-API and SPNEGO wrapping, around NTLMSSP.":"Lớp bọc GSS-API và SPNEGO, quanh NTLMSSP.","The login methods the server accepts: NTLMSSP":"Các cách đăng nhập máy chủ chấp nhận: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Toàn vẹn trước xác thực: SHA-512, và salt riêng của máy chủ","Encryption: AES-128-GCM":"Mã hóa: AES-128-GCM","Signing: AES-GMAC":"Ký: AES-GMAC","0x02 (signing required)":"0x02 (bắt buộc ký)","Previous session":"Phiên trước","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: các tùy chọn NTLM laptop hỗ trợ","Not an error: the login needs another round.":"Không phải lỗi: đăng nhập cần thêm một vòng.","The server’s number for this login, from now on in every message.":"Số của máy chủ cho lần đăng nhập này, từ giờ có trong mọi thông điệp.","Session flags":"Cờ phiên","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: một thử thách ngẫu nhiên 8 byte","The NAS’s names and its clock":"Tên của NAS và đồng hồ của nó","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: người dùng alex, máy tính ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"Trả lời NTLMv2: một HMAC của thử thách, tính bằng giá trị băm của mật khẩu","A key for signing, encrypted":"Một khóa để ký, đã mã hóa","0x00000009 (response, signed)":"0x00000009 (phản hồi, đã ký)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC trên toàn bộ thông điệp, bằng khóa từ lần đăng nhập: thông điệp bị sửa hay giả mạo sẽ bị phát hiện.","The login is complete.":"Đăng nhập đã hoàn tất.","0x00000008 (signed)":"0x00000008 (đã ký)","Server and share name, in UTF-16.":"Tên máy chủ và thư mục chia sẻ, dạng UTF-16.","The number for this share; later requests carry it.":"Số của thư mục chia sẻ này; các yêu cầu sau mang nó.","Share type":"Loại chia sẻ","1 (disk)":"1 (ổ đĩa)","Share flags":"Cờ chia sẻ","Encryption not required for this share; signing still protects every message.":"Thư mục chia sẻ này không yêu cầu mã hóa; chữ ký vẫn bảo vệ mọi thông điệp.","0x001f01ff (full control)":"0x001f01ff (toàn quyền)","What this user may do in the share.":"Người dùng này được làm gì trong thư mục chia sẻ.","Oplock, impersonation":"Oplock, mạo danh","none, 2 (impersonation)":"không, 2 (mạo danh)","Desired access":"Quyền truy cập mong muốn","0x00120089 (read)":"0x00120089 (đọc)","Read the data, its attributes and its permissions.":"Đọc dữ liệu, thuộc tính và quyền của nó.","File attributes":"Thuộc tính tệp","Share access":"Truy cập dùng chung","0x00000001 (read)":"0x00000001 (đọc)","Others may read the file while it is open, but not change it.":"Người khác được đọc tệp khi nó đang mở, nhưng không được sửa.",Disposition:"Cách xử lý","1 (open, fail if missing)":"1 (mở, báo lỗi nếu không có)","0x00000040 (a file, not a folder)":"0x00000040 (một tệp, không phải thư mục)",Name:"Tên","Create contexts":"Ngữ cảnh tạo","File name":"Tên tệp","Relative to the share.":"Tương đối với thư mục chia sẻ.","Oplock, flags":"Oplock, cờ","none, 0":"không, 0",Action:"Hành động","1 (opened)":"1 (đã mở)",Times:"Thời gian","created, accessed, written, changed":"tạo, truy cập, ghi, thay đổi","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME của Windows: bước 100 nano giây kể từ năm 1601.","Allocation size":"Kích thước cấp phát","File size":"Kích thước tệp","0x00000020 (archive)":"0x00000020 (lưu trữ)","File ID":"File ID","The handle for the open file: reads and the close name it.":"Handle của tệp đang mở: lệnh đọc và đóng đều dùng nó.","A big read costs one credit per 64 KB.":"Một lần đọc lớn tốn một credit cho mỗi 64 KB.","Padding, flags":"Đệm, cờ","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Máy chủ nên đặt dữ liệu ở đâu trong câu trả lời: cách đầu 80 byte, ngay sau các tiêu đề.","The whole file in one request.":"Cả tệp trong một yêu cầu.","Minimum, channel, remaining":"Tối thiểu, kênh, còn lại","Channel info":"Thông tin kênh","Data offset":"Vị trí dữ liệu","Data length":"Độ dài dữ liệu","Remaining, flags":"Còn lại, cờ","The file itself; its contents are not part of the lesson.":"Chính tệp đó; nội dung của nó không thuộc bài học.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"Laptop không xin chi tiết của tệp, nên phần còn lại là số 0.","Times, sizes, attributes":"Thời gian, kích thước, thuộc tính","Talking to a PLC":"Nói chuyện với PLC",Switch:"Switch","Plant network":"Mạng nhà máy","Modbus/TCP, for industrial control":"Modbus/TCP, cho điều khiển công nghiệp","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus là một trong những giao thức lâu đời và phổ biến nhất trong điều khiển công nghiệp (OT, công nghệ vận hành): PLC, cảm biến, bộ truyền động động cơ và đồng hồ đo trong nhà máy, trạm nước và tòa nhà đều nói nó. Máy khách đọc và ghi các thanh ghi và coil được đánh số trên một thiết bị. Modbus/TCP mang cùng các thông điệp nhỏ đó qua cổng TCP 502, không đăng nhập và không mã hóa.","1979, by Modicon":"1979, do Modicon","16-bit registers, on/off coils":"Thanh ghi 16 bit, coil bật/tắt","None built in":"Không tích hợp sẵn","Modbus.org specifications":"Đặc tả của Modbus.org","Pump running":"Bơm đang chạy","Simple, and wide open":"Đơn giản, và mở toang","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"Laptop đọc bốn thanh ghi, đổi một giá trị đặt và khởi động một máy bơm, mỗi việc bằng một yêu cầu 12 byte và một câu trả lời ngắn. Không thông điệp nào mang mật khẩu và không cái nào được mã hóa: Modbus tin bất kỳ ai tới được nó, nên mạng xung quanh phải lo việc bảo vệ. Nhấn XEM LẠI để xem lại.","4 requests, 4 answers":"4 yêu cầu, 4 câu trả lời",Biggest:"Lớn nhất","17 bytes (the read answer)":"17 byte (câu trả lời đọc)","Protect with":"Bảo vệ bằng","Separate networks":"Tách riêng mạng","Port 502":"Cổng 502","A TCP connection to the PLC":"Một kết nối TCP tới PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Một PLC (bộ điều khiển logic lập trình được) vận hành một trạm bơm nhỏ: nó đọc cảm biến và bật tắt máy bơm. Laptop của một kỹ sư trên mạng nhà máy nói chuyện với nó bằng Modbus/TCP, nên mở kết nối TCP tới cổng 502. Theo cách gọi của Modbus, laptop là máy khách còn PLC là máy chủ.",Roles:"Vai trò","Client asks, server answers":"Máy khách hỏi, máy chủ trả lời","Read Registers":"Đọc thanh ghi","Function 3: four numbers":"Hàm 3: bốn con số","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"Laptop xin 4 holding register bắt đầu từ địa chỉ 0, với mã hàm 3. PLC trả lời bằng 8 byte: bốn số 16 bit. Ý nghĩa của chúng (mực nước bồn tính bằng xăng-ti-mét, nhiệt độ tính bằng phần mười độ) chỉ được ghi trong tài liệu của PLC; thông điệp không mang tên hay đơn vị. Một màn hình HMI gửi các lệnh đọc như vậy khoảng mỗi giây.",Function:"Hàm","4 registers from 0":"4 thanh ghi từ 0","function 3":"hàm 3","registers 0–3":"thanh ghi 0–3",VALUES:"GIÁ TRỊ","Write a Setpoint":"Ghi giá trị đặt","Function 6: one register":"Hàm 6: một thanh ghi","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"Kỹ sư nâng giá trị đặt mực nước bồn từ 4.50 m lên 5.00 m: hàm 6, ghi một thanh ghi, thanh ghi 3, giá trị 500. PLC trả lời bằng cách lặp lại yêu cầu, nghĩa là đã xong. Từ giờ chương trình của nó giữ bồn đầy hơn.","Register 3":"Thanh ghi 3","The request, repeated":"Lặp lại yêu cầu",WRITE:"GHI","register 3 = 500":"thanh ghi 3 = 500","Start a Pump":"Khởi động bơm","Function 5: a coil":"Hàm 5: một coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Coil là các đầu ra bật/tắt đơn lẻ. Hàm 5 ghi một coil: coil 0, bơm 2, giá trị 0xFF00, nghĩa là bật. PLC bật bơm và lặp lại yêu cầu. Trong nhà máy thật, thường chính chương trình của PLC quyết định việc này, kèm các khóa liên động an toàn.","Coil 0":"Coil 0","Pump 2: on":"Bơm 2: bật","0xFF00 (off: 0x0000)":"0xFF00 (tắt: 0x0000)","COIL ON":"BẬT COIL","coil 0: pump 2":"coil 0: bơm 2","pump 2 on":"bơm 2 bật","PUMP 2 RUNNING":"BƠM 2 ĐANG CHẠY","An Exception":"Một ngoại lệ","No such register":"Không có thanh ghi đó","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Một yêu cầu đọc thanh ghi không tồn tại, ở đây là 100 và 101, nhận về một ngoại lệ: mã hàm với bit cao nhất bật (3 + 128 = 131) và mã ngoại lệ 2, địa chỉ dữ liệu không hợp lệ. Các mã khác báo hàm không được hỗ trợ hoặc thiết bị đang bận.",Exception:"Ngoại lệ",Means:"Nghĩa là","No register there":"Không có thanh ghi ở đó","registers 100–101":"thanh ghi 100–101",EXCEPTION:"NGOẠI LỆ","code 2: no such register":"mã 2: không có thanh ghi đó","No Security":"Không bảo mật","Anyone who can reach it":"Ai tới được cũng dùng được","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Không gì trong các thông điệp này cho biết ai gửi chúng: Modbus, ra đời năm 1979, không có đăng nhập và không mã hóa, nên mọi thiết bị tới được cổng 502 đều đọc được giá trị và khởi động được bơm. Nhà máy bảo vệ nó bằng mạng tách riêng, tường lửa giữa văn phòng và nhà máy, danh sách ai được nói chuyện với từng PLC, và giám sát. Modbus/TCP Security bọc cùng các thông điệp đó trong TLS, trên cổng 802.","Separate networks, TLS":"Tách riêng mạng, TLS","NO LOGIN, NO ENCRYPTION":"KHÔNG ĐĂNG NHẬP, KHÔNG MÃ HÓA","Seen on the plant network":"Thấy trên mạng nhà máy","Picked by the client; the answer carries the same number.":"Do máy khách chọn; câu trả lời mang cùng số.","Protocol ID":"ID giao thức","The unit ID and everything after it.":"ID đơn vị và mọi thứ sau nó.","Unit ID":"ID đơn vị","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Thiết bị nào. Quan trọng khi một gateway chuyển yêu cầu tới các thiết bị trên đường nối tiếp.","Function code":"Mã hàm","Starting address":"Địa chỉ bắt đầu","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus đếm từ 0, dù sách hướng dẫn thường đánh số cùng thanh ghi đó từ 40001 trở lên.",Quantity:"Số lượng","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, câu trả lời","The same number as the request.":"Cùng số với yêu cầu.","Byte count":"Số byte","Register 0":"Thanh ghi 0","412 (tank level, 4.12 m)":"412 (mực nước bồn, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Số 16 bit thuần túy. Ý nghĩa của từng số được ghi trong tài liệu của PLC, không ở trong thông điệp.","Register 1":"Thanh ghi 1","183 (temperature, 18.3 °C)":"183 (nhiệt độ, 18.3 °C)","Register 2":"Thanh ghi 2","1450 (pump speed, 1,450 rpm)":"1450 (tốc độ bơm, 1,450 vòng/phút)","450 (level setpoint, 4.50 m)":"450 (giá trị đặt mực nước, 4.50 m)","Register address":"Địa chỉ thanh ghi","3 (level setpoint)":"3 (giá trị đặt mực nước)",Value:"Giá trị","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, câu trả lời","The answer repeats the request: done.":"Câu trả lời lặp lại yêu cầu: đã xong.","Coil address":"Địa chỉ coil","0 (pump 2)":"0 (bơm 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Coil là một đầu ra bật/tắt đơn lẻ. 0xFF00 bật nó.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, câu trả lời","Modbus/TCP · exception":"Modbus/TCP · ngoại lệ","131 (3 + 128: an exception)":"131 (3 + 128: một ngoại lệ)","The top bit set: the request failed.":"Bit cao nhất bật: yêu cầu thất bại.","Exception code":"Mã ngoại lệ","There is no register at that address.":"Không có thanh ghi nào ở địa chỉ đó.","Internet Routes":"Tuyến đường Internet",Routes:"Tuyến đường","The laptop’s packets":"Gói của laptop","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Internet là mạng của các mạng: hàng chục nghìn mạng, do nhà mạng, đám mây, trường đại học và công ty vận hành, mỗi mạng có số AS riêng. BGP là cách các router biên của chúng báo cho nhau biết chúng tới được những địa chỉ nào. Mỗi router chuyển tiếp những gì nó biết kèm thêm số của mình, nên mỗi mạng tự dựng bản đồ đường đi tới mọi địa chỉ trên Internet.",Between:"Giữa","Networks (ASes)":"Các mạng (AS)",Table:"Bảng","About a million IPv4 routes":"Khoảng một triệu tuyến IPv4","Path choice":"Chọn đường","Policy, then shortest":"Chính sách, rồi ngắn nhất","Route learned":"Đã học tuyến","Announced, passed on, used":"Quảng bá, chuyển tiếp, sử dụng","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Mạng hosting quảng bá địa chỉ của nó, mạng trung chuyển chuyển tiếp chúng kèm số của mình, và router của nhà mạng dùng đường đó cho gói của laptop. Khi tuyến bị rút, tin tức lan theo cùng cách. Không có bản đồ trung tâm: mỗi mạng tự dựng bản đồ từ những gì láng giềng nói. Nhấn XEM LẠI để xem lại.",Map:"Bản đồ","Each network makes its own":"Mỗi mạng tự dựng","RPKI and filters":"RPKI và bộ lọc","Many Networks":"Nhiều mạng","Each with its own number":"Mỗi mạng một số","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Internet gồm hơn 75,000 mạng riêng biệt, gọi là hệ tự trị (AS): nhà mạng, đám mây, trường đại học, công ty lớn, mỗi mạng có một số. Đây là ba mạng: nhà mạng của laptop (AS 64500), một mạng trung chuyển mang lưu lượng của người khác (AS 64510) và mạng hosting của www.example.com (AS 64511). BGP là cách router của chúng báo cho nhau biết mỗi địa chỉ tới được ở đâu.",Networks:"Mạng","More than 75,000 ASes":"Hơn 75,000 AS",Here:"Ở đây","3 ASes, a router each":"3 AS, mỗi AS một router",Numbers:"Số","TCP to port 179":"TCP tới cổng 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"Router BGP không tự tìm nhau: kỹ sư ở cả hai đầu cấu hình chúng làm láng giềng. Router của nhà mạng mở kết nối TCP tới router trung chuyển trên cổng 179. Chúng nối trực tiếp, nên gói của chúng đi với TTL bằng 1: không thể vượt qua thêm dù chỉ một router, nên phiên chỉ chạy giữa các láng giềng trực tiếp.",Neighbours:"Láng giềng","Set up by hand":"Cấu hình thủ công","1: the next router only":"1: chỉ router kế tiếp","OPEN, then KEEPALIVE":"OPEN, rồi KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Mỗi router gửi một OPEN: số AS, hold time 180 giây, ID router và những gì nó hỗ trợ, chẳng hạn số AS 4 byte. Mỗi bên trả lời bằng KEEPALIVE, và phiên được thiết lập. Từ giờ cứ 60 giây có một KEEPALIVE khi không có gì khác để gửi; sau 180 giây im lặng, phiên sẽ bị ngắt.","AS, hold time, ID":"AS, hold time, ID","KEEPALIVE: established":"KEEPALIVE: đã thiết lập","Hold time":"Hold time","hold 180 s":"hold 180 s","SESSION ESTABLISHED":"ĐÃ THIẾT LẬP PHIÊN","Announce a Route":"Quảng bá tuyến","The hosting network: “I have these”":"Mạng hosting: “tôi có những địa chỉ này”","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Router của mạng hosting quảng bá 203.0.113.0/24, 256 địa chỉ bao gồm www.example.com, tới mạng trung chuyển mà nó trả tiền để mang lưu lượng. UPDATE cho biết cách tới đó: AS_PATH 64511, đến giờ chỉ có mạng của nó, và NEXT_HOP, địa chỉ của nó trên liên kết giữa hai bên.","path 64511":"đường 64511","Passed On":"Chuyển tiếp","Each network adds its number":"Mỗi mạng thêm số của mình","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Router trung chuyển chấp nhận tuyến và chuyển cho các láng giềng khác, trong đó có nhà mạng, với số của nó thêm vào phía trước: AS_PATH 64510 64511, và chính nó là chặng kế tiếp. Router của nhà mạng có thể nghe về cùng tiền tố từ nhiều láng giềng. Nó chọn một tuyến trước hết theo chính sách riêng (ví dụ tuyến qua khách hàng trả tiền được ưu tiên), rồi theo đường AS ngắn nhất.","Best path":"Đường tốt nhất","path 64510 64511":"đường 64510 64511","ROUTE TO 203.0.113.0/24":"TUYẾN TỚI 203.0.113.0/24","Follow the Route":"Đi theo tuyến","Packets go where BGP said":"Gói đi nơi BGP chỉ","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Khi laptop kết nối tới www.example.com (địa chỉ tìm qua DNS như thường), gói của nó tới nhà mạng, router của nhà mạng giờ gửi mọi thứ cho 203.0.113.0/24 tới router trung chuyển, và router trung chuyển chuyển tiếp tới mạng hosting. Câu trả lời quay về theo tuyến mà mạng hosting chọn hướng về nhà mạng của laptop: trên Internet, đường về thường khác đường đi.","Way back":"Đường về","Chosen separately":"Chọn riêng","the way back":"đường về",Withdrawn:"Đã rút","Routes can be taken back":"Tuyến có thể bị rút lại","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Sau đó mạng hosting rút tiền tố lại, như khi một liên kết hỏng: một UPDATE liệt kê nó trong mục tuyến đã rút. Router trung chuyển chuyển tiếp, và trong vài giây đến vài phút các mạng khắp nơi quên đường đó. Phiên nào im lặng quá hold time sẽ mất toàn bộ tuyến cùng lúc. Năm 2021 Facebook rút các tuyến tới máy chủ DNS của chính mình và biến mất khỏi Internet trong sáu giờ.","Spreads in":"Lan trong","Seconds to minutes":"Vài giây đến vài phút","Session lost":"Mất phiên","All its routes go":"Mọi tuyến của nó biến mất",WITHDRAW:"RÚT TUYẾN","Trust Problems":"Vấn đề lòng tin","BGP believes its neighbours":"BGP tin láng giềng","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Router chấp nhận những gì láng giềng quảng bá. Một mạng quảng bá địa chỉ không phải của mình, do nhầm hay cố ý, sẽ kéo lưu lượng của chúng về phía nó: năm 2008 một nhà mạng Pakistan đã làm YouTube ngừng hoạt động toàn cầu theo cách này. Với RPKI, chủ của tiền tố ký xác nhận AS nào được quảng bá nó, và router có kiểm tra sẽ bỏ mọi AS khác. Bộ lọc những gì từng láng giềng được quảng bá lo phần còn lại.",Risk:"Rủi ro","Hijacks and leaks":"Chiếm tuyến và rò rỉ","Signed: who may announce":"Đã ký: ai được quảng bá",Also:"Thêm nữa","Filters per neighbour":"Bộ lọc theo láng giềng","CHECK WHO MAY ANNOUNCE":"KIỂM TRA AI ĐƯỢC QUẢNG BÁ","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: rút 203.0.113.0/24",Marker:"Dấu","16 bytes of 0xFF":"16 byte 0xFF","All ones: where a message starts.":"Toàn số 1: nơi một thông điệp bắt đầu.","The first message on a session: who this router is and what it supports.":"Thông điệp đầu tiên của phiên: router này là ai và hỗ trợ gì.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Mạng của router này. (Số AS 4 byte nằm trong capability bên dưới, còn ở đây là 23456.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Nếu hoàn toàn không có gì đến trong khoảng này, phiên bị ngắt. Hai bên dùng đề xuất thấp hơn.","BGP identifier":"Định danh BGP","The router’s ID, usually one of its addresses.":"ID của router, thường là một trong các địa chỉ của nó.","Optional parameters":"Tham số tùy chọn","parameter 2, 14 bytes":"tham số 2, 14 byte","What this router can do beyond the basics.":"Router này làm được gì ngoài phần cơ bản.",Multiprotocol:"Đa giao thức","Which kinds of routes it will exchange on this session.":"Những loại tuyến nó sẽ trao đổi trong phiên này.","Route refresh":"Làm mới tuyến","It can ask the other side to send all its routes again.":"Nó có thể xin bên kia gửi lại toàn bộ tuyến.","4-byte AS numbers":"Số AS 4 byte","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"Số AS 2 byte cạn dần, nên các số mới dài 4 byte.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Chỉ có tiêu đề: “vẫn còn đây”. Gửi khi không có gì khác để nói, mỗi một phần ba hold time.","Routes: paths to new addresses, and ones taken back.":"Tuyến: đường tới địa chỉ mới, và những tuyến bị rút.","Withdrawn routes":"Tuyến đã rút","Path attributes":"Thuộc tính đường","0 (IGP: from inside the network that announced it)":"0 (IGP: từ bên trong mạng đã quảng bá)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Mọi mạng mà tuyến đã đi qua, mạng gần nhất trước. Nếu các yếu tố khác như nhau, đường ngắn hơn thắng; router nào thấy số của mình ở đây sẽ bỏ tuyến, nên tuyến không thể chạy vòng.","Send packets for these addresses to this router.":"Gửi gói cho các địa chỉ này tới router này.",Reachable:"Tới được","The addresses this route leads to: a prefix, here 256 addresses.":"Các địa chỉ tuyến này dẫn tới: một tiền tố, ở đây là 256 địa chỉ.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (rút tuyến)","These addresses can no longer be reached through this router.":"Không còn tới được các địa chỉ này qua router này.","A Video Call":"Cuộc gọi video",Signalling:"Báo hiệu","STUN and ICE":"STUN và ICE",Media:"Media","STUN Server":"Máy chủ STUN","Sam’s Router":"Router của Sam","Sam’s Laptop":"Laptop của Sam","Web Real-Time Communication":"Web Real-Time Communication","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"WebRTC cho hai trình duyệt gọi nhau, với âm thanh, video và dữ liệu đi thẳng giữa chúng, không qua máy chủ. Máy chủ chỉ giới thiệu hai bên: chúng trao đổi mô tả về những gì có thể gửi và nơi có thể tới được (báo hiệu), tìm đường qua cả hai router ở nhà bằng ICE và STUN, mã hóa bằng DTLS, và gửi media qua UDP dưới dạng SRTP.","Media over":"Media qua","Always on":"Luôn bật","Works in":"Chạy trên","Every major browser":"Mọi trình duyệt lớn","W3C; RFC 8825 and others":"W3C; RFC 8825 và các RFC khác","On the call":"Đang gọi","Introduced by a server, then direct":"Máy chủ giới thiệu, rồi đi thẳng","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Máy chủ báo hiệu chuyển lời mời và câu trả lời giữa hai trình duyệt, một máy chủ STUN cho laptop biết địa chỉ công khai của nó, và một lần kiểm tra ICE tìm được đường qua cả hai router ở nhà. Sau bắt tay DTLS, âm thanh và video đã mã hóa đi thẳng từ laptop này sang laptop kia. Nhấn XEM LẠI để xem lại.","Via call.example.com":"Qua call.example.com","Media path":"Đường media","Direct, through 2 NATs":"Trực tiếp, qua 2 NAT","DTLS, then SRTP":"DTLS, rồi SRTP","If blocked":"Nếu bị chặn","A TURN relay":"Một relay TURN","Join the Call":"Vào cuộc gọi","Through a signalling server":"Qua máy chủ báo hiệu","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"Laptop mở một trang gọi trên call.example.com, và trang giữ một WebSocket mở tới máy chủ, bên trong TLS. Nó vào phòng 42, nơi Sam đang chờ. Máy chủ sẽ chuyển thông điệp giữa hai trình duyệt. WebRTC không quy định cách làm: mỗi ứng dụng làm phần báo hiệu này theo cách riêng.","The app’s own server":"Máy chủ riêng của ứng dụng","A WebSocket in TLS":"Một WebSocket trong TLS",Room:"Phòng","42, with Sam":"42, với Sam",JOIN:"VÀO","room 42":"phòng 42","SAM IS HERE":"SAM ĐANG Ở ĐÂY","peer: Sam":"bên kia: Sam","Public Address?":"Địa chỉ công khai?","Ask a STUN server":"Hỏi máy chủ STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Sau router ở nhà, laptop chỉ biết địa chỉ riêng 192.168.1.10, mà không ai trên Internet tới được. Nên nó hỏi một máy chủ STUN ghi trong thiết lập của trang gọi, bằng một yêu cầu UDP nhỏ. Câu trả lời cho biết yêu cầu dường như đến từ đâu, 198.51.100.7 cổng 61022: địa chỉ công khai của router và cổng mà NAT của nó mở cho cuộc trao đổi này.",Public:"Công khai","what is my address?":"địa chỉ của tôi là gì?","YOUR ADDRESS":"ĐỊA CHỈ CỦA BẠN","The Offer":"Lời mời","An SDP description, via the server":"Một mô tả SDP, qua máy chủ","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Trình duyệt viết lời mời bằng SDP: media nó muốn gửi (âm thanh Opus; video VP8, H.264 và các loại khác), dấu vân tay chứng chỉ DTLS của nó, tên người dùng và mật khẩu ICE, và các ứng viên, tức những địa chỉ có thể tới được nó. Địa chỉ riêng được giấu sau một tên .local ngẫu nhiên. Máy chủ báo hiệu chuyển lời mời tới Sam.","SDP, in a JSON message":"SDP, trong một thông điệp JSON",Candidates:"Ứng viên",".local name, 198.51.100.7":"tên .local, 198.51.100.7","About 4.7 KB":"Khoảng 4.7 KB","SDP: audio, video":"SDP: âm thanh, video",candidates:"ứng viên","to Sam":"tới Sam","Sam’s browser replies":"Trình duyệt của Sam trả lời","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam nhận cuộc gọi. Trình duyệt của Sam trả lời bằng SDP của mình: các codec chọn từ lời mời, dấu vân tay chứng chỉ, tên người dùng và mật khẩu ICE, và các ứng viên, gồm cả địa chỉ công khai 198.51.100.200 cổng 49170, biết được từ một máy chủ STUN theo cùng cách. Nó cũng nói nó sẽ bắt đầu bắt tay mã hóa. Giờ mỗi trình duyệt biết bên kia có thể tới được ở đâu.",Codecs:"Codec","Sam’s address":"Địa chỉ của Sam","Starts DTLS":"Bắt đầu DTLS","Sam’s browser":"Trình duyệt của Sam","from Sam":"từ Sam","Punch Through":"Xuyên qua","Checks straight to each other":"Kiểm tra trực tiếp với nhau","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Giờ các trình duyệt thử từng cặp địa chỉ bằng các lần kiểm tra STUN gửi thẳng cho nhau (ICE). Mỗi lần kiểm tra còn mở một đường về qua router của chính bên gửi, nên khi cả hai bên đã gửi một lần, các kiểm tra đi qua được cả hai NAT. Lần này có trả lời: đường trực tiếp hoạt động. Laptop rồi lặp lại kiểm tra với USE-CANDIDATE, chọn cặp này cho cuộc gọi.",Checks:"Kiểm tra","STUN, peer to peer":"STUN, ngang hàng","The ICE password":"Mật khẩu ICE","A direct path":"Một đường trực tiếp",CHECK:"KIỂM TRA","IT WORKS":"HOẠT ĐỘNG","direct path":"đường trực tiếp","THROUGH BOTH ROUTERS":"QUA CẢ HAI ROUTER","DTLS Handshake":"Bắt tay DTLS","Keys for the media":"Khóa cho media","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Trên cùng đường đó, các trình duyệt chạy bắt tay DTLS: TLS cho UDP. Chứng chỉ của chúng tự ký, nên mỗi bên kiểm tra chứng chỉ bên kia bằng dấu vân tay trong SDP, thứ đã đi qua máy chủ báo hiệu bên trong TLS. Cuộc bắt tay cũng thỏa thuận khóa cho SRTP, thứ mã hóa âm thanh và video. WebRTC không bao giờ gửi media chưa mã hóa.","1.2, TLS over UDP":"1.2, TLS qua UDP","Checked by fingerprint":"Kiểm tra bằng dấu vân tay",Gives:"Cho ra","The SRTP keys":"Khóa SRTP",certificate:"chứng chỉ","Media Flows":"Media chạy","Audio and video, direct":"Âm thanh và video, trực tiếp","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"Âm thanh đi trong một gói SRTP mỗi 20 ms, còn video là các khung hình chia ra nhiều gói. Mỗi gói có tiêu đề RTP đọc được (số thứ tự, dấu thời gian, ID luồng) và media đã mã hóa. Không gì trong đó đi qua call.example.com. Cả hai trình duyệt theo dõi độ trễ và mất gói rồi điều chỉnh chất lượng video cho phù hợp, và một kênh dữ liệu cho chat hay tệp có thể dùng chung đường đó.","Opus, a packet per 20 ms":"Opus, một gói mỗi 20 ms",Video:"Video","VP8, adapts to the network":"VP8, thích ứng với mạng","None of it":"Không gì cả",AUDIO:"ÂM THANH","Opus, every 20 ms":"Opus, mỗi 20 ms",VIDEO:"VIDEO","VP8, a frame in 3 packets":"VP8, một khung trong 3 gói","Peer to Peer":"Ngang hàng","And when it can’t be":"Và khi không thể","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Máy chủ giúp hai trình duyệt tìm thấy nhau, rồi lui ra: cuộc gọi đi thẳng giữa hai nhà. Khi một mạng không cho gói trực tiếp đi qua (một số tường lửa công ty, một số mạng di động), ICE chuyển sang một máy chủ TURN chuyển tiếp media đã mã hóa mà không đọc được. Cuộc gọi nhóm cũng thường gửi media qua một máy chủ, gọi là SFU.","Laptop to laptop":"Từ laptop tới laptop",Fallback:"Dự phòng","TURN relay (encrypted)":"Relay TURN (đã mã hóa)","Group calls":"Cuộc gọi nhóm","Usually via an SFU":"Thường qua một SFU","NO SERVER IN THE MIDDLE":"KHÔNG CÓ MÁY CHỦ Ở GIỮA","A WebSocket text message":"Một thông điệp văn bản WebSocket","The attributes; the 20-byte header isn’t counted.":"Các thuộc tính; không tính tiêu đề 20 byte.","Always this value: tells STUN apart from the other traffic on the same port.":"Luôn là giá trị này: phân biệt STUN với lưu lượng khác trên cùng cổng.","Random; the response carries the same ID.":"Ngẫu nhiên; phản hồi mang cùng ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Yêu cầu đến từ đâu, theo những gì máy chủ thấy: địa chỉ công khai của router ở nhà, và cổng mà NAT của nó chọn cho cuộc trao đổi này.","Their internet provider’s router, the next hop.":"Router của nhà mạng bên kia, chặng kế tiếp.","Their router’s internet-facing port.":"Cổng của router bên kia hướng ra Internet.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"Tên người dùng ICE từ lời mời và câu trả lời, của bên kia trước: chứng minh lần kiểm tra thuộc cuộc gọi này.","The priority a new candidate found by this check would get.":"Mức ưu tiên mà một ứng viên mới tìm được qua lần kiểm tra này sẽ có.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Bên này, bên gọi, quyết định cuối cùng về đường đi. Số ngẫu nhiên phân xử khi hòa.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 của thông điệp, tính bằng mật khẩu ICE trao đổi qua máy chủ báo hiệu, nên người lạ không giả được lần kiểm tra hay câu trả lời.","A CRC-32 of the message: marks it clearly as STUN.":"Một CRC-32 của thông điệp: đánh dấu rõ nó là STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Lần kiểm tra đến từ đâu, theo những gì laptop bên kia thấy: địa chỉ công khai và cổng của router ở nhà.",Epoch:"Epoch","Counts this side’s records, so repeats and stale ones can be spotted.":"Đếm các bản ghi của bên này, để phát hiện bản ghi lặp lại hay cũ.","Message length":"Độ dài thông điệp","Message sequence":"Thứ tự thông điệp","Handshake messages are numbered, so they can be put back in order.":"Các thông điệp bắt tay được đánh số, để có thể xếp lại đúng thứ tự.",Fragment:"Mảnh","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Bộ mã hóa: ECDHE-ECDSA với AES-GCM, và các bộ khác","use_srtp: the SRTP protection it supports":"use_srtp: kiểu bảo vệ SRTP nó hỗ trợ","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Đã chọn: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Một chứng chỉ tự ký do trình duyệt tạo; dấu vân tay của nó có trong lời mời","Its half of an X25519 key exchange, signed":"Nửa phần của nó trong một trao đổi khóa X25519, có chữ ký","Asks Sam’s browser for its certificate too":"Cũng xin chứng chỉ của trình duyệt của Sam","Sam’s self-signed certificate; its fingerprint was in the answer":"Chứng chỉ tự ký của Sam; dấu vân tay của nó có trong câu trả lời","Its half of the X25519 key exchange":"Nửa phần của nó trong trao đổi khóa X25519","A signature that proves it holds the certificate’s key":"Một chữ ký chứng minh nó giữ khóa của chứng chỉ","From the next record on, this side encrypts.":"Từ bản ghi tiếp theo, bên này mã hóa.","Finished (encrypted)":"Finished (đã mã hóa)","Epoch 1: protected with the keys just agreed.":"Epoch 1: được bảo vệ bằng khóa vừa thỏa thuận.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Một nonce 8 byte, thông điệp Finished và một thẻ 16 byte (AES-128-GCM).","SRTP · audio":"SRTP · âm thanh","2, no padding, extension, no CSRCs":"2, không đệm, có mở rộng, không CSRC","X set: a header extension follows the fixed header.":"Bật X: một phần mở rộng tiêu đề theo sau tiêu đề cố định.","One more for each packet, so a lost or late one shows.":"Tăng một sau mỗi gói, để thấy gói bị mất hay đến muộn.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Đồng hồ âm thanh, 48,000 nhịp mỗi giây: +960 mỗi 20 ms.","Which stream this is; announced in the SDP.":"Đây là luồng nào; được thông báo trong SDP.","Header extension":"Phần mở rộng tiêu đề","0xbede, 2 words":"0xbede, 2 từ","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Các phần tử một byte: một ID (từ các dòng a=extmap của SDP) và một độ dài.","Audio level":"Mức âm thanh","How loud this packet is, so a group call can show who is talking without decrypting.":"Gói này to đến đâu, để cuộc gọi nhóm hiện được ai đang nói mà không cần giải mã.","Transport sequence":"Thứ tự giao vận","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Đánh số mọi gói của cuộc gọi; bên nhận báo cáo gói nào đến lúc nào, để kiểm soát tắc nghẽn.","Encrypted media":"Media đã mã hóa","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms âm thanh Opus, mã hóa bằng khóa từ bắt tay DTLS (AES-128-GCM).","Authentication tag":"Thẻ xác thực","Proves the packet came from the other side unchanged; the header is covered too.":"Chứng minh gói đến từ bên kia nguyên vẹn; tiêu đề cũng được bao phủ.","SRTP · video":"SRTP · video","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Đồng hồ video, 90,000 nhịp mỗi giây: +3,000 mỗi khung ở 30 khung mỗi giây.","Absolute send time":"Thời điểm gửi tuyệt đối","When the packet was sent, so the receiver can tell when the network is filling up.":"Gói được gửi lúc nào, để bên nhận biết khi nào mạng đang đầy lên.","1 byte":"1 byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Một phần của khung video VP8, mã hóa bằng khóa từ bắt tay DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Bật marker: gói cuối cùng của một khung video.","8 ports":"8 cổng","Frames and switches":"Khung và switch","Broadband logins":"Đăng nhập băng rộng","The laptop sent it with 128; the router took 1 when it passed it on.":"Laptop gửi nó với 128; router trừ đi 1 khi chuyển tiếp.","Frames & Switches":"Khung và switch","To the NAS":"Tới NAS","To the internet":"Ra Internet","Ethernet and Switches":"Ethernet và switch","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet chở gần như mọi mạng có dây, và các điểm truy cập Wi-Fi cũng chuyển lưu lượng của chúng sang đó. Mỗi card mạng có một địa chỉ MAC 48 bit. Một khung cho biết nó dành cho card nào và card nào đã gửi, còn switch thì chuyển giao nó: từ các khung nó thấy, switch học được mỗi địa chỉ nằm sau cổng nào, và chỉ gửi mỗi khung tới nơi nó cần đến.","48-bit MAC":"MAC 48 bit","14 bytes, plus a 4-byte FCS":"14 byte, cộng FCS 4 byte","Frame size":"Kích thước khung","64 to 1,518 bytes":"Từ 64 đến 1.518 byte",Speeds:"Tốc độ",Switched:"Đã chuyển mạch","Learned, flooded, forwarded":"Học, phát tràn, chuyển tiếp","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Switch học vị trí của laptop và NAS từ các khung chúng gửi, chỉ phát tràn gói quảng bá, và gửi mọi khung khác chỉ qua cổng cần thiết. Địa chỉ MAC đưa mỗi khung qua một liên kết; tại router, gói tin chuyển sang một khung mới. Nhấn XEM LẠI để xem lại.",Learned:"Đã học","2 addresses, 2 ports":"2 địa chỉ, 2 cổng",Flooded:"Phát tràn","Only the broadcast":"Chỉ gói quảng bá",Frame:"Khung","14-byte header, 4-byte FCS":"Tiêu đề 14 byte, FCS 4 byte","Forgets after":"Quên sau","5 minutes unused":"5 phút không dùng","Who Has the NAS?":"Ai giữ NAS?","A broadcast asks for a MAC address":"Gói quảng bá hỏi địa chỉ MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"Laptop muốn tới NAS ở 192.168.1.20. Trong mạng cục bộ, khung được giao theo địa chỉ MAC, và laptop chưa biết MAC của NAS. Vì vậy nó gửi một yêu cầu ARP tới ff:ff:ff:ff:ff:ff, địa chỉ quảng bá, vào cổng 1 của switch.","Looking for":"Đang tìm","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (tất cả)",Into:"Vào qua","Switch port 1":"Cổng 1 của switch","who has 192.168.1.20?":"ai có 192.168.1.20?","Learn, Then Flood":"Học rồi phát tràn","The switch notes where the laptop is":"Switch ghi lại vị trí của laptop","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Switch đọc địa chỉ nguồn của mỗi khung và ghi vào bảng MAC: 00:00:5e:00:53:10 ở cổng 1. Gói quảng bá dành cho mọi người, nên nó gửi một bản sao qua mọi cổng khác: tới NAS ở cổng 2 và router ở cổng 8. Khung gửi tới địa chỉ chưa biết cũng bị phát tràn.","…:53:10 is on port 1":"…:53:10 ở cổng 1",Copies:"Bản sao","Out of every other port":"Qua mọi cổng khác","Unknown address":"Địa chỉ chưa biết","Flooded the same way":"Cũng phát tràn","…:53:10 IS ON PORT 1":"…:53:10 Ở CỔNG 1","copies out of ports 2 and 8":"bản sao qua cổng 2 và 8","Only the NAS Answers":"Chỉ NAS trả lời","The reply goes to one port":"Câu trả lời tới một cổng","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Mọi thiết bị đều đọc yêu cầu, nhưng chỉ NAS có 192.168.1.20, nên chỉ nó trả lời, thẳng tới MAC của laptop; router bỏ qua. Switch học được rằng 00:00:5e:00:53:20 ở cổng 2. Nó đã biết laptop ở đâu, nên câu trả lời chỉ ra qua cổng 1.","To the laptop only":"Chỉ tới laptop","…:53:20 is on port 2":"…:53:20 ở cổng 2","Out of":"Ra qua","Port 1":"Cổng 1","…:53:20 IS ON PORT 2":"…:53:20 Ở CỔNG 2","port 1 only":"chỉ cổng 1","Port to Port":"Từ cổng tới cổng","Frames go only where they must":"Khung chỉ đi tới đúng nơi","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"Laptop kết nối tới NAS. Mỗi khung bắt đầu bằng MAC của NAS, rồi MAC của chính nó, rồi một kiểu: 0x0800, tức gói IPv4. Sau gói tin, card thêm một checksum 4 byte. Switch tra đích và gửi mỗi khung chỉ qua cổng 2. Router không bao giờ thấy chúng.","To, from, type: 14 bytes":"Tới, từ, kiểu: 14 byte","4 bytes, added by the card":"4 byte, do card thêm","Router sees":"Router thấy",Nothing:"Không gì cả","type 0x0800 (IPv4)":"kiểu 0x0800 (IPv4)","out of port 2 only":"chỉ qua cổng 2","Off the Network":"Ra khỏi mạng","A frame for the router":"Một khung cho router","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Tiếp theo laptop mở một trang web ở 203.0.113.10. Địa chỉ đó không thuộc mạng cục bộ, nên khung đi tới router: đích là MAC của router, đã biết từ một lần ARP trước, còn gói tin bên trong vẫn ghi 203.0.113.10. Switch gửi nó qua cổng 8.","Frame to":"Khung tới","The router’s MAC":"MAC của router","Packet to":"Gói tới","Port 8":"Cổng 8","IP packet to 203.0.113.10":"gói IP tới 203.0.113.10","out of port 8":"qua cổng 8","A New Frame":"Một khung mới","Every hop rewraps the packet":"Mỗi chặng gói lại gói tin","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Router lấy gói tin ra khỏi khung, giảm TTL và thay địa chỉ công khai của nó vào (NAT). Rồi nó đặt gói tin vào một khung mới cho liên kết kế tiếp: MAC phía Internet của nó làm nguồn, router của nhà mạng làm đích. Địa chỉ MAC không bao giờ đi qua quá một liên kết.","The router’s internet port":"Cổng Internet của router","The provider’s router":"Router của nhà mạng","Still 203.0.113.10":"Vẫn là 203.0.113.10","NEW FRAME":"KHUNG MỚI","from the router’s internet port":"từ cổng Internet của router","IP still to 203.0.113.10":"IP vẫn tới 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Vào, cổng 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Ra, cổng 2 (phát tràn) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Ra, cổng 8 (phát tràn) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Vào, cổng 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Chỉ ra cổng 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Vào, cổng 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Ra, cổng 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Vào, cổng 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Ra, cổng 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Vào, cổng 1 · 52344 → 443 [SYN] (khung tới router)","Out port 8 · 52344 → 443 [SYN]":"Ra, cổng 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (khung mới, sau NAT)","Seen going into the switch, port 1":"Thấy khi đi vào switch, cổng 1","Seen leaving the switch, port 2":"Thấy khi rời switch, cổng 2","Seen leaving the switch, port 8":"Thấy khi rời switch, cổng 8","Seen going into the switch, port 2":"Thấy khi đi vào switch, cổng 2","Seen leaving the switch, port 1":"Thấy khi rời switch, cổng 1","Broadband Logins":"Đăng nhập băng rộng",Discovery:"Khám phá","PPP setup":"Thiết lập PPP","Home Router":"Router gia đình","Access Server":"Máy chủ truy cập","Point-to-Point Protocol over Ethernet":"Giao thức điểm-điểm qua Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Nhiều nhà mạng DSL và cáp quang buộc router gia đình đăng nhập trước khi lên mạng. PPPoE là cách làm điều đó: router tìm máy chủ truy cập của nhà mạng và mở một phiên với nó, rồi chạy PPP bên trong, thỏa thuận các thiết lập của liên kết, đăng nhập bằng tên người dùng và mật khẩu nhà mạng cấp, và nhận địa chỉ IP công khai. Sau đó mỗi gói tin đều mang một tiêu đề PPPoE 8 byte.","CHAP or PAP":"CHAP hoặc PAP","From IPCP":"Từ IPCP","8 bytes (MTU 1,492)":"8 byte (MTU 1.492)","Logged in":"Đã đăng nhập","Found, agreed, checked, addressed":"Tìm thấy, thỏa thuận, xác minh, có địa chỉ","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"Router đã tìm thấy máy chủ truy cập của nhà mạng, có được một phiên, thỏa thuận thiết lập liên kết, chứng minh mật khẩu mà không gửi nó và được cấp địa chỉ công khai. Giờ mọi gói tin đều đi trong phiên đó, cho tới khi một PADT kết thúc nó. Nhấn XEM LẠI để xem lại.","17 to get online":"17 để lên mạng","Public IP":"IP công khai","8 bytes per packet":"8 byte mỗi gói","Anyone There?":"Có ai không?","The router looks for an access server":"Router tìm máy chủ truy cập","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"Router gia đình được cắm vào đường cáp quang hoặc DSL của nhà mạng. Trước khi đăng nhập, nó phải tìm máy chủ truy cập của nhà mạng, nên nó quảng bá một PADI: “PPPoE Active Discovery Initiation”. Một máy chủ truy cập trả lời bằng PADO, một lời đề nghị có tên của nó: bng-1.example.net.","PADI, to everyone":"PADI, tới mọi người","PADO, from the server":"PADO, từ máy chủ","Ethernet type":"Kiểu Ethernet","0x8863 (discovery)":"0x8863 (khám phá)","is there an access server?":"có máy chủ truy cập không?","and a cookie":"và một cookie","Pick a Server":"Chọn máy chủ","A session number for the line":"Số phiên cho đường truyền","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Nếu nhiều máy chủ trả lời, router chọn một và hỏi thẳng nó bằng PADR, gửi lại cookie đã nhận. Máy chủ đáp bằng PADS mang ID phiên 0x2f1c. Từ giờ mỗi khung giữa hai bên đều mang số đó.",Confirmed:"Đã xác nhận","this server, please":"máy chủ này nhé","with its cookie":"kèm cookie của nó","session ID 0x2f1c":"ID phiên 0x2f1c","SESSION 0x2F1C":"PHIÊN 0x2F1C","Link Settings":"Thiết lập liên kết","LCP agrees on size and login":"LCP thỏa thuận kích thước và đăng nhập","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Giờ PPP chạy bên trong phiên, bắt đầu bằng LCP. Mỗi bên yêu cầu thiết lập của mình: gói tin tối đa 1.492 byte, vì 8 byte của PPPoE phải nằm vừa trong 1.500 byte của Ethernet, và một magic number ngẫu nhiên để phát hiện vòng lặp. Máy chủ còn yêu cầu đăng nhập bằng CHAP. Cả hai đồng ý.","Largest packet":"Gói lớn nhất","1,492 bytes (MRU)":"1.492 byte (MRU)","CHAP with MD5":"CHAP với MD5","0x8864 (session)":"0x8864 (phiên)","LCP REQUEST":"YÊU CẦU LCP","magic number":"magic number","MRU 1492, log in with CHAP":"MRU 1492, đăng nhập bằng CHAP","LCP ACK":"LCP ACK","A password check without the password":"Kiểm tra mật khẩu mà không có mật khẩu","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Máy chủ gửi một thử thách ngẫu nhiên. Router trả lời bằng tên người dùng alex@fibre.example và một hash MD5 của thử thách và mật khẩu, nên bản thân mật khẩu không bao giờ đi qua đường truyền. Máy chủ kiểm tra câu trả lời với máy chủ RADIUS của nhà mạng, rồi đáp Success.",Username:"Tên người dùng","A hash, not the password":"Một hash, không phải mật khẩu","The provider’s RADIUS":"RADIUS của nhà mạng","MD5(id, password, challenge)":"MD5(id, mật khẩu, thử thách)","CHECKED WITH RADIUS":"ĐÃ KIỂM TRA VỚI RADIUS","Get an Address":"Nhận địa chỉ","IPCP hands out the public IP":"IPCP cấp IP công khai","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Máy chủ trước tiên cho router biết đầu bên kia của nó, 198.51.100.1. Router xin địa chỉ và máy chủ DNS, đưa ra 0.0.0.0: “gì cũng được”. Máy chủ từ chối và gợi ý 198.51.100.7 cùng hai máy chủ DNS. Router xin lại với các giá trị đó, và máy chủ đồng ý.","Other end":"Đầu bên kia","IPCP REQUEST":"YÊU CẦU IPCP","my end: 198.51.100.1":"đầu của tôi: 198.51.100.1","address? 0.0.0.0":"địa chỉ? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"dùng 198.51.100.7","198.51.100.7, please":"198.51.100.7 nhé",agreed:"đồng ý","Every packet in an 8-byte wrapper":"Mỗi gói trong một lớp bọc 8 byte","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"Laptop mở một trang web. Router thay địa chỉ công khai của nó vào (NAT) và gửi gói tin bên trong phiên: một tiêu đề PPPoE 6 byte, rồi 2 byte cho biết “IPv4”. Nó cũng hạ MSS mà laptop đề nghị từ 1460 xuống 1452, để các câu trả lời vừa trong 1.492 byte.",Wrapper:"Lớp bọc","6 + 2 bytes":"6 + 2 byte","1460 → 1452 (clamped)":"1460 → 1452 (bị kẹp)","in session 0x2f1c":"trong phiên 0x2f1c","MSS now 1452":"MSS giờ là 1452","Seen on the router’s line to the provider":"Thấy trên đường truyền từ router tới nhà mạng","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 byte","PADI, 2 tags":"PADI, 2 thẻ","Broadcast: everything on the line receives it.":"Quảng bá: mọi thứ trên đường truyền đều nhận.","0x8863 (PPPoE discovery)":"0x8863 (khám phá PPPoE)","Version, type":"Phiên bản, kiểu","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: ngoài kia có máy chủ truy cập nào không?","0 (none yet)":"0 (chưa có)","What follows this header.":"Phần đi sau tiêu đề này.","The service the router wants; empty means any.":"Dịch vụ router muốn; để trống nghĩa là gì cũng được.","Type, length":"Kiểu, độ dài","A value the router made up. Answers carry it back, so the router can match them to its request.":"Một giá trị do router tự đặt. Các câu trả lời mang nó trở lại, để router ghép chúng với yêu cầu của mình.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 byte","PADO, 4 tags":"PADO, 4 thẻ","The access server’s port.":"Cổng của máy chủ truy cập.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: một máy chủ truy cập trả lời.","The access server’s name.":"Tên của máy chủ truy cập.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Một giá trị máy chủ sẽ nhận ra khi router xin lại, nên một cơn lũ yêu cầu giả cũng không làm nó tốn gì.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 byte","PADR, 3 tags":"PADR, 3 thẻ","The access server that answered.":"Máy chủ truy cập đã trả lời.","Active Discovery Request: the router picks this server.":"Active Discovery Request: router chọn máy chủ này.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 byte","PADS, 2 tags":"PADS, 2 thẻ","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: đây là ID phiên.","Given by the server in its PADS; every frame of the session carries it.":"Do máy chủ cấp trong PADS của nó; mọi khung của phiên đều mang nó.","PPPoE · 6 bytes":"PPPoE · 6 byte","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 byte","0x8864 (PPPoE session)":"0x8864 (phiên PPPoE)","0x00 (Session)":"0x00 (phiên)","Session data: one PPP packet.":"Dữ liệu phiên: một gói PPP.","Link Control Protocol: the link’s settings.":"Link Control Protocol: các thiết lập của liên kết.","The settings this side wants.":"Các thiết lập bên này muốn.","The answer carries the same number.":"Câu trả lời mang cùng số đó.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Gói lớn nhất bên này nhận: 1.500 byte của Ethernet trừ 8 byte của PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Ngẫu nhiên. Thấy số của chính mình quay lại nghĩa là đường truyền bị vòng ngược về chính nó.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 byte","How the server wants the router to log in.":"Cách máy chủ muốn router đăng nhập.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 byte","Every setting accepted, exactly as asked.":"Mọi thiết lập đều được chấp nhận, đúng như đã yêu cầu.","The number of the request this answers.":"Số của yêu cầu mà câu này trả lời.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 byte","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 byte","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: việc đăng nhập.","A random value for the router to prove its password with.":"Một giá trị ngẫu nhiên để router chứng minh mật khẩu của mình.","The response must carry the same number.":"Câu trả lời phải mang cùng số đó.","Value size":"Kích thước giá trị","Random, new for every login.":"Ngẫu nhiên, mới cho mỗi lần đăng nhập.","The server’s name.":"Tên của máy chủ.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 byte","The proof, and who is logging in.":"Bằng chứng, và ai đang đăng nhập.","The number of the challenge this answers.":"Số của thử thách mà câu này trả lời.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 của mã định danh, mật khẩu và thử thách: chứng minh mật khẩu mà không gửi nó.","The username the provider gave.":"Tên người dùng nhà mạng cấp.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 byte","The login worked.":"Đăng nhập thành công.","Text for people to read; any words will do.":"Văn bản cho người đọc; chữ gì cũng được.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 byte","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: địa chỉ IP và các máy chủ DNS.","The address of the server’s end of the link.":"Địa chỉ đầu liên kết phía máy chủ.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 byte","Zero: “please give me an address”.":"Số không: “làm ơn cho tôi một địa chỉ”.","Zero: “which DNS server should I use?”":"Số không: “tôi nên dùng máy chủ DNS nào?”","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 byte","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 byte","Not these values: here are ones that would be accepted.":"Không phải các giá trị này: đây là những giá trị sẽ được chấp nhận.","The address for the router.":"Địa chỉ cho router.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 byte","PPP · 2 bytes":"PPP · 2 byte","An IPv4 packet follows.":"Tiếp theo là một gói IPv4.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Router đã hạ nó từ 1460, để các gói trả về vừa trong 1.492 byte mà PPPoE để lại.","Internet phone calls":"Gọi điện qua internet","IP camera streams":"Luồng camera IP","Live streaming upload":"Tải lên phát trực tiếp","Multicast and TV channels":"Multicast và kênh truyền hình","IP Camera":"Camera IP","TV Box":"TV box",Camera:"Camera","Internet Phone Calls":"Gọi điện qua internet","Voice (RTP)":"Giọng nói (RTP)","SIP Server":"Máy chủ SIP","Bob’s Router":"Router của Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP thiết lập các cuộc gọi qua internet: điện thoại bàn ở văn phòng, ứng dụng gọi điện và các nhà cung cấp đứng sau. Điện thoại đăng nhập vào máy chủ SIP của nhà cung cấp. Để gọi ai đó, nó gửi INVITE; điện thoại bên kia đổ chuông và nhấc máy, hai bên thống nhất cách gửi giọng nói, sau đó giọng nói chạy dưới dạng RTP. Các thông điệp là văn bản thuần, rất giống HTTP.","UDP or TCP 5060":"UDP hoặc TCP 5060","Call setup":"Thiết lập cuộc gọi",Voice:"Giọng nói","RTP, described by SDP":"RTP, mô tả bằng SDP","Codec here":"Codec ở đây","Call ended":"Đã kết thúc","Signed in, rang, talked, hung up":"Đăng ký, đổ chuông, nói chuyện, gác máy","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Điện thoại của Alice đăng nhập bằng một mật khẩu nó chưa từng gửi đi, mời điện thoại của Bob qua máy chủ SIP, nghe nó đổ chuông và nói chuyện qua RTP cho đến khi Bob gác máy bằng BYE. SIP chỉ thiết lập rồi kết thúc cuộc gọi; giọng nói đi trong các gói riêng. Nhấn XEM LẠI để xem lại.","50 packets a second each way":"50 gói mỗi giây mỗi chiều",Through:"Đi qua","The provider’s server":"Máy chủ của nhà cung cấp","No (SIPS and SRTP add it)":"Không (SIPS và SRTP bổ sung)","Sign In":"Đăng nhập","The phone tells the server where it is":"Điện thoại báo cho máy chủ biết nó ở đâu","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Điện thoại của Alice, một ứng dụng trên laptop của cô, đăng ký với máy chủ SIP của nhà cung cấp: có thể liên lạc alice@example.net ở đây. Máy chủ trả lời 401 kèm một thử thách, nên điện thoại hỏi lại với một hash tạo từ thử thách và mật khẩu. 200 OK: đã đăng ký trong một giờ.","Good for":"Hiệu lực","3600 s, then again":"3600 s, rồi đăng ký lại","is here":"đang ở đây","with a challenge":"kèm thử thách","again, with a hash":"hỏi lại, kèm hash",registered:"đã đăng ký","Call Bob":"Gọi Bob","An INVITE, passed on by the server":"Một INVITE, được máy chủ chuyển tiếp","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice gọi bob@example.net. INVITE của cô mang SDP: âm thanh G.711, gửi về điện thoại của cô. Máy chủ trả lời 100 Trying, tìm nơi điện thoại của Bob đã đăng ký rồi chuyển tiếp INVITE với Via và Record-Route của riêng nó và địa chỉ của nó trong SDP: giọng nói sẽ đi qua nó.","Offer (SDP)":"Đề nghị (SDP)","G.711, port 49170":"G.711, cổng 49170","Stops Alice resending":"Alice thôi gửi lại","call bob@example.net":"gọi bob@example.net","SDP: G.711 audio":"SDP: âm thanh G.711","passed on to Bob":"chuyển tiếp tới Bob","voice via the server":"giọng nói qua máy chủ",Ringing:"Đổ chuông","The answer retraces the route":"Phản hồi đi lại đúng đường cũ","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Điện thoại của Bob bắt đầu đổ chuông và báo lại: 180 Ringing. Phản hồi đi theo các header Via ngược về đường yêu cầu đã đến, nên nó tới máy chủ, máy chủ gỡ Via của mình rồi chuyển cho Alice. Điện thoại của cô phát tiếng chuông chờ.","Route back":"Đường về","The Via headers, in reverse":"Các header Via, theo thứ tự ngược","Alice hears":"Alice nghe thấy","The ringing tone":"Tiếng chuông chờ","Bob’s phone rings":"điện thoại của Bob đổ chuông","to Alice":"tới Alice",Answered:"Đã nhấc máy","200 OK, then ACK":"200 OK, rồi ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob nhấc máy. 200 OK của anh mang câu trả lời SDP: G.711, gửi về điện thoại của anh. Máy chủ lại thay bằng địa chỉ của mình trước khi chuyển cho Alice. Điện thoại của cô xác nhận bằng ACK, máy chủ chuyển nó cho Bob. Cuộc gọi đã thiết lập.","Answer (SDP)":"Trả lời (SDP)","G.711, port 49172":"G.711, cổng 49172","Confirmed by":"Xác nhận bằng","Voice goes to":"Giọng nói đến","The server, ports 40000, 40002":"Máy chủ, cổng 40000, 40002","Bob answers":"Bob nhấc máy",answered:"đã nhấc máy",Talking:"Đang nói chuyện","Voice flows as RTP":"Giọng nói chạy dưới dạng RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Giờ là giọng nói: cứ 20 ms mỗi điện thoại gửi một gói RTP chứa 160 byte âm thanh G.711, một số thứ tự và một dấu thời gian, qua UDP. Chúng tới máy chủ, máy chủ chuyển sang điện thoại kia. SIP im lặng trong lúc họ nói chuyện.",Every:"Mỗi","20 ms, 160 bytes of sound":"20 ms, 160 byte âm thanh","Carried by":"Được chở bởi","RTP over UDP":"RTP qua UDP","SIP meanwhile":"Trong lúc đó SIP","Nothing to say":"Không có gì để nói",VOICE:"GIỌNG NÓI","20 ms of Alice":"20 ms của Alice","20 ms of Bob":"20 ms của Bob","Hang Up":"Gác máy","BYE, and 200 OK":"BYE, và 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob gác máy: điện thoại của anh gửi BYE, đi qua máy chủ như Record-Route yêu cầu, và điện thoại của Alice trả lời 200 OK. Cả hai ngừng gửi giọng nói. Cuộc gọi cần bốn loại yêu cầu; bản thân giọng nói chưa bao giờ là một phần của SIP.","No more RTP":"Hết RTP","Bob hangs up":"Bob gác máy","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 luật μ, codec điện thoại kinh điển)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Đồng hồ âm thanh 8000 mỗi giây: +160 cho mỗi 20 ms âm thanh.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 byte âm thanh G.711 (20 ms, một byte mỗi mẫu)","IP Camera Streams":"Luồng camera IP","Video (RTP)":"Video (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"RTSP là cách trình phát video, đầu ghi và ứng dụng an ninh lấy hình trực tiếp từ camera IP. Nó hoạt động như một chiếc điều khiển từ xa: trình phát hỏi camera có gì, thiết lập một luồng, rồi nói PLAY và sau đó TEARDOWN, bằng các thông điệp văn bản rất giống HTTP. Bản thân video không đi trong RTSP: nó chạy riêng dưới dạng RTP, ở đây qua UDP.",Controls:"Lệnh điều khiển",Watched:"Đã xem","Described, set up, played, stopped":"Mô tả, thiết lập, phát, dừng","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC hỏi camera có gì, đăng nhập bằng hash của mật khẩu, thiết lập một rãnh video và nhấn PLAY. Video tới dưới dạng gói RTP trên các cổng riêng, một khung hình chính chia ba mảnh, cho đến khi TEARDOWN kết thúc phiên. Nhấn XEM LẠI để xem lại.","6 on one TCP connection":"6 trên một kết nối TCP","Key frame":"Khung hình chính","Split into 3 packets":"Chia thành 3 gói","1185d200, 60 s timeout":"1185d200, hết hạn sau 60 s","What Can You Do?":"Bạn làm được gì?","OPTIONS over a TCP connection":"OPTIONS qua một kết nối TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC mở rtsp://192.168.1.64/stream1. Nó kết nối tới camera ở cổng TCP 554 và bắt đầu bằng OPTIONS: bạn hỗ trợ những lệnh nào? Camera liệt kê chúng. Như HTTP, mọi yêu cầu và phản hồi đều là văn bản; header CSeq đánh số chúng.","Numbered by":"Đánh số bằng","what can you do?":"bạn làm được gì?","Describe the Stream":"Mô tả luồng","SDP says what the video is":"SDP cho biết video là gì","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE xin bản mô tả của luồng. Camera muốn đăng nhập trước: 401, kèm một thử thách digest. VLC hỏi lại với hash của mật khẩu, và phản hồi mang SDP: một rãnh video H.264, loại payload RTP 96, với đồng hồ 90 kHz.","Digest: a hash":"Digest: một hash","H.264, payload type 96":"H.264, loại payload 96",Track:"Rãnh","describe stream1":"mô tả stream1","log in first":"đăng nhập trước đã","SDP: H.264 video":"SDP: video H.264","track 1":"rãnh 1","Set Up":"Thiết lập","Agree on ports for the video":"Thống nhất cổng cho video","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP cho trackID=1 cho biết cách gửi nó: RTP qua UDP, tới cổng 50000 (video) và 50001 (báo cáo RTCP) của laptop. Camera đồng ý, chọn cổng riêng là 6970 và 6971, rồi mở phiên 1185d200 mà mọi yêu cầu sau đều nêu tên.","Laptop ports":"Cổng của laptop","track 1, RTP over UDP":"rãnh 1, RTP qua UDP","to ports 50000-50001":"tới cổng 50000-50001","session 1185d200":"phiên 1185d200","from ports 6970-6971":"từ cổng 6970-6971",Play:"Phát","The remote control’s PLAY button":"Nút PLAY của điều khiển","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY bắt đầu phát luồng từ bây giờ (npt=0.000-). Phản hồi cho VLC biết số thứ tự và dấu thời gian RTP nào đến trước, để nó sắp video cho khớp. Từ đây trở đi, video hoàn toàn không đi trong RTSP.",Range:"Khoảng","From now":"Từ bây giờ","First packet":"Gói đầu tiên","Video arrives":"Video tới","On the UDP ports":"Ở các cổng UDP","play from now":"phát từ bây giờ",playing:"đang phát","Video Arrives":"Video Tới","A key frame in RTP packets":"Một khung hình chính trong gói RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"Camera gửi một khung hình chính, tức một bức hình trọn vẹn, trong ba gói RTP: các mảnh H.264 đánh dấu là đầu, giữa và cuối, bit đánh dấu bật ở gói cuối. Cả ba mang cùng dấu thời gian 90 kHz. Tiếp theo là các khung nhỏ hơn chỉ chứa phần thay đổi, 25 khung mỗi giây.",Packets:"Số gói","3 for one key frame":"3 cho một khung hình chính","Same for the whole frame":"Như nhau cho cả khung",Frames:"Khung hình","25 a second":"25 mỗi giây","a key frame in 3 packets":"khung hình chính trong 3 gói",Stop:"Dừng","TEARDOWN ends the session":"TEARDOWN kết thúc phiên","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Khi người xem đóng luồng, VLC gửi TEARDOWN kèm ID phiên. Camera ngừng gửi video và xác nhận. Nếu VLC cứ thế biến mất, camera vẫn sẽ dừng sau 60 giây không nhận được lời nào từ nó.",Ended:"Đã kết thúc",Otherwise:"Nếu không","Timeout after 60 s":"Hết hạn sau 60 s","stop session 1185d200":"dừng phiên 1185d200",stopped:"đã dừng","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"Camera. Nó ở cùng mạng, nên khung đi thẳng tới nó, không qua router.","The camera’s network port.":"Cổng mạng của camera.","RTP + video":"RTP + video","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, như bản mô tả của camera)","Marker clear: more of this frame follows.":"Không đánh dấu: còn tiếp phần của khung này.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Đồng hồ video 90.000 mỗi giây; mọi gói của một khung có cùng giá trị.","Identifies this video stream.":"Định danh luồng video này.","FU indicator":"Chỉ báo FU","0x7c (fragment of a frame)":"0x7c (mảnh của một khung)","Fragmentation unit: one piece of a frame too big for one packet.":"Đơn vị phân mảnh: một mảnh của khung quá lớn so với một gói.","FU header":"Header FU","0x85 (first piece of a key frame)":"0x85 (mảnh đầu của khung hình chính)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Loại 5: khung hình chính (IDR), một bức hình trọn vẹn mà bộ giải mã có thể bắt đầu từ đó.","1398 bytes of the key frame":"1398 byte của khung hình chính","0x05 (middle piece of a key frame)":"0x05 (mảnh giữa của khung hình chính)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, như bản mô tả của camera)","Marker set: the last packet of a frame.":"Có đánh dấu: gói cuối của một khung.","0x45 (last piece of a key frame)":"0x45 (mảnh cuối của khung hình chính)","900 bytes of the key frame":"900 byte của khung hình chính","Multicast TV":"Truyền hình multicast","Joins and leaves":"Tham gia và rời đi","Channel 1":"Kênh 1","TV channels":"Kênh truyền hình","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Multicast gửi một luồng duy nhất tới một địa chỉ nhóm, và mạng chỉ sao chép nó tới nơi cần: đó là cách nhà mạng phát các kênh truyền hình trực tiếp. IGMP là cách một thiết bị báo cho router biết nó muốn những nhóm nào. Switch lắng nghe (IGMP snooping), nên mỗi luồng chỉ tới các cổng đã yêu cầu.","IP protocol 2":"Giao thức IP số 2",Groups:"Nhóm","Version here":"Phiên bản ở đây","Tuned In":"Đã vào kênh","Joined, copied, checked, left":"Tham gia, sao chép, kiểm tra, rời đi","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"TV box rồi đến laptop tham gia kênh 1 bằng các báo cáo IGMP. Router chỉ tham gia một lần cho cả nhà, còn switch, vốn lắng nghe, chỉ sao chép kênh tới các cổng cần nó. Các truy vấn giữ cho kênh tiếp tục chạy, và khi laptop rời đi, câu trả lời của TV box giữ kênh vẫn bật. Nhấn XEM LẠI để xem lại.",Upstream:"Hướng về nhà mạng","One stream for the home":"Một luồng cho cả nhà","Copies to ports that joined":"Sao chép tới cổng đã tham gia","Every 125 s":"Mỗi 125 s","Pick a Channel":"Chọn kênh","The TV box joins a group":"TV box tham gia một nhóm","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Người xem chọn kênh 1. Mỗi kênh là một nhóm multicast, ở đây là 233.252.0.1, và TV box gửi một IGMP Membership Report tới địa chỉ đó: tôi muốn nhóm này. Switch lắng nghe (IGMP snooping), ghi nhớ cổng 2 và chỉ chuyển báo cáo cho router.","Switch notes":"Switch ghi nhớ","Port 2 wants it":"Cổng 2 muốn nó","233.252.0.1, please":"233.252.0.1, làm ơn","to the router port only":"chỉ tới cổng router","Ask the Provider":"Xin nhà mạng","The router joins for the home":"Router tham gia thay cả nhà","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Router là một IGMP proxy: nó tham gia nhóm ở phía internet bằng báo cáo của chính nó, từ địa chỉ công cộng của nó, và mạng của nhà mạng bắt đầu gửi kênh 1 xuống đường dây. Dù trong nhà có bao nhiêu màn hình xem, router chỉ tham gia một lần.","Router role":"Vai trò của router","IGMP proxy":"IGMP proxy",Joins:"Tham gia","Once for the whole home":"Một lần cho cả nhà","for the whole home":"thay cả nhà","The Channel Flows":"Kênh Chảy Vào","Sent only where it was asked for":"Chỉ gửi tới nơi đã yêu cầu","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Máy chủ truyền hình của nhà mạng gửi kênh 1 tới 233.252.0.1: các datagram UDP, mỗi cái chứa bảy gói MPEG-TS 188 byte gồm video và âm thanh. Router cho chúng vào trong, còn switch chỉ đẩy ra cổng 2: chỉ TV box tham gia, nên laptop không nhận được gói nào.",Datagram:"Datagram","UDP, 1,316 bytes of TV":"UDP, 1.316 byte truyền hình",Holds:"Chứa","7 MPEG-TS packets":"7 gói MPEG-TS","CHANNEL 1":"KÊNH 1","MPEG-TS over UDP":"MPEG-TS qua UDP","passed into the home":"chuyển vào nhà","port 2 only":"chỉ cổng 2","A Second Screen":"Màn Hình Thứ Hai","The laptop tunes in too":"Laptop cũng xem kênh","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Laptop mở kênh 1 trong VLC và gửi báo cáo của chính nó. Switch thêm cổng 1 và giờ tạo hai bản sao cho mỗi datagram. Router đã nhận kênh rồi, nên nó không xin gì thêm từ nhà mạng: trên đường dây vẫn chỉ có một luồng.","Switch sends to":"Switch gửi tới","Ports 1 and 2":"Cổng 1 và 2","Still one stream":"Vẫn một luồng","Router asks":"Router xin","Nothing new":"Không có gì mới","the same one stream":"vẫn một luồng ấy","copied to ports 1 and 2":"sao chép tới cổng 1 và 2","Still Watching?":"Vẫn Đang Xem?","The router checks regularly":"Router kiểm tra định kỳ","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Cứ 125 giây router gửi một General Query tới 224.0.0.1, tức mọi thiết bị: các bạn còn muốn những nhóm nào? Switch chuyển nó tới mọi cổng. Mỗi thành viên trả lời vào một thời điểm ngẫu nhiên trong vòng 10 giây, nên router và switch tiếp tục cho kênh chảy vào.","125 seconds":"125 giây","224.0.0.1, all devices":"224.0.0.1, mọi thiết bị","Answer within":"Trả lời trong","10 seconds":"10 giây",QUERY:"TRUY VẤN","any groups wanted?":"cần những nhóm nào?","to every port":"tới mọi cổng",REPORT:"BÁO CÁO","still watching":"vẫn đang xem",Leave:"Rời đi","The laptop stops watching":"Laptop thôi xem","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Đóng VLC sẽ gửi một Leave Group tới 224.0.0.2, tức mọi router. Có thể người khác vẫn đang xem, nên router chỉ hỏi về nhóm đó và đợi 1 giây. TV box trả lời, nên kênh vẫn giữ; switch chỉ thôi gửi nó tới cổng 1.","Leave sent to":"Rời đi gửi tới","224.0.0.2, all routers":"224.0.0.2, mọi router","About that group alone":"Chỉ về nhóm đó","Stays: the TV box answered":"Giữ nguyên: TV box đã trả lời",LEAVE:"RỜI ĐI","done with 233.252.0.1":"xem xong 233.252.0.1","anyone for 233.252.0.1?":"còn ai cần 233.252.0.1?","to the ports that joined":"tới các cổng đã tham gia","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast: 01:00:5e, rồi 23 bit cuối của địa chỉ nhóm. Card mạng lắng nghe các nhóm mà hệ thống của nó đã tham gia.","The TV box’s network port.":"Cổng mạng của TV box.","4, 24 bytes":"4, 24 byte","IPv4, with one 4-byte option.":"IPv4, kèm một tùy chọn 4 byte.","48 (network control), 0":"48 (điều khiển mạng), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Đánh dấu là điều khiển mạng, nên được gửi trước lưu lượng thông thường.","Always 1: IGMP never goes past the first router.":"Luôn là 1: IGMP không bao giờ đi quá router đầu tiên.","A multicast group address.":"Một địa chỉ nhóm multicast.","Router Alert option":"Tùy chọn Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Nhờ mọi router dọc đường nhìn vào bên trong, dù gói không gửi cho nó.","This device wants the group’s traffic.":"Thiết bị này muốn lưu lượng của nhóm.","Max response time":"Thời gian trả lời tối đa","Only queries use it.":"Chỉ truy vấn mới dùng.","Covers the IGMP message.":"Bao trùm thông điệp IGMP.","Group address":"Địa chỉ nhóm","The multicast group: one TV channel.":"Nhóm multicast: một kênh truyền hình.","Seen arriving on the router’s internet side":"Thấy khi tới phía internet của router","MPEG-TS · 7 packets":"MPEG-TS · 7 gói","The provider’s router, passing the channel on.":"Router của nhà mạng, chuyển kênh đi tiếp.","Sync byte":"Byte đồng bộ","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Mọi gói transport stream đều bắt đầu bằng 0x47, để bên nhận tìm được chỗ bắt đầu của các gói.","Flags, PID":"Cờ, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: video)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Gói thuộc luồng nào: video của kênh, âm thanh của nó, hay các bảng liệt kê chúng.","Payload, counter":"Payload, bộ đếm","0x14 (payload only, counter 4)":"0x14 (chỉ payload, bộ đếm 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Đếm từ 0 đến 15 cho mỗi PID, nên gói bị mất hiện ra như một khoảng trống.","184 bytes of the channel’s video":"184 byte video của kênh","More packets":"Các gói khác","6 × 188 bytes: video and audio":"6 × 188 byte: video và âm thanh","Six more transport stream packets, each with its own 4-byte header.":"Thêm sáu gói transport stream, mỗi gói có header 4 byte riêng.","Seen going into the switch, port 8":"Thấy khi đi vào switch, cổng 8","The router, passing the channel into the home.":"Router, chuyển kênh vào trong nhà.","0x19 (payload only, counter 9)":"0x19 (chỉ payload, bộ đếm 9)","The router asks: which groups does anyone here still want?":"Router hỏi: ở đây còn ai muốn những nhóm nào?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Thành viên trả lời vào một thời điểm ngẫu nhiên trong khoảng này, để các câu trả lời không tới cùng lúc.","Zero in a general query: every group.":"Bằng 0 trong truy vấn chung: mọi nhóm.","This device no longer wants the group.":"Thiết bị này không còn muốn nhóm nữa.","The router asks: does anyone still want this group?":"Router hỏi: còn ai muốn nhóm này không?","Live Streaming Upload":"Tải Lên Phát Trực Tiếp","RTMP handshake":"Bắt tay RTMP","Video and audio":"Video và âm thanh","Ingest Server":"Máy chủ ingest","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"RTMP là cách phần lớn streamer gửi video trực tiếp lên một nền tảng: OBS và các ứng dụng khác đẩy nó tới một máy chủ ingest, nơi biến nó thành các buổi phát cho người xem. Sinh ra cho Flash, nó sống lâu hơn Flash như một cách tải lên. Mọi thứ chung một kết nối TCP: lệnh, âm thanh và video, được cắt thành chunk.","H.264 video, AAC audio":"Video H.264, âm thanh AAC","Encoded in AMF0":"Mã hóa bằng AMF0","Secure version":"Phiên bản an toàn","RTMPS, over TLS":"RTMPS, qua TLS","Adobe specification (2012)":"Đặc tả của Adobe (2012)",Live:"Đang phát","Connected, published, streamed":"Đã kết nối, đã đăng, đã phát","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS bắt tay với máy chủ ingest, kết nối tới ứng dụng live của nó, nhận stream 1 và đăng lên đó bằng khóa stream. Video và âm thanh sau đó chảy thành chunk trên cùng kết nối TCP cho đến khi streamer dừng. Nhấn XEM LẠI để xem lại.","One TCP, port 1935":"Một TCP, cổng 1935",Stream:"Stream",Chunks:"Chunk","Up to 4,096 bytes":"Tối đa 4.096 byte","None: RTMPS adds TLS":"Không: RTMPS thêm TLS","TCP, then RTMP’s own":"TCP, rồi tới của RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Streamer bấm Bắt đầu phát. OBS kết nối tới máy chủ ingest ở cổng TCP 1935, rồi RTMP có màn bắt tay riêng: phiên bản 3 và 1.536 byte ngẫu nhiên mỗi chiều, mỗi bên gửi lại cho bên kia. Nó cho thấy hai đầu cùng nói RTMP; nó không mã hóa gì cả.","Each side":"Mỗi bên","Sends 3,073 bytes":"Gửi 3.073 byte","version 3":"phiên bản 3","1,536 random bytes":"1.536 byte ngẫu nhiên","version 3, its own bytes":"phiên bản 3, byte của mình","and C1 sent back":"và gửi lại C1","S1 sent back":"gửi lại S1",Connect:"Kết nối","To the server’s live app":"Tới ứng dụng live của máy chủ","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS nâng kích thước chunk lên 4.096 byte và gửi connect cho ứng dụng tên live, bằng AMF0, một định dạng nhị phân gọn có từ thời Flash. Máy chủ đặt cửa sổ, băng thông và kích thước chunk của riêng nó, rồi trả lời _result: NetConnection.Connect.Success.",App:"Ứng dụng",Encoding:"Mã hóa","chunk size 4,096":"kích thước chunk 4.096","window, bandwidth, chunks":"cửa sổ, băng thông, chunk","Make a Stream":"Tạo một stream","createStream returns stream 1":"createStream trả về stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Mỗi thông điệp nêu một luồng thông điệp; 0 là chính kết nối. OBS giải phóng và công bố khóa stream của mình, rồi dùng createStream xin một stream để gửi, cả ba lệnh trong một gói. Máy chủ trả lời bằng stream ID 1.","3 in one packet":"3 trong một gói",Gets:"Nhận được","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"Đăng","The stream key goes live":"Khóa stream lên sóng","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish nêu khóa stream, bí mật cho biết kênh này của ai. RTMP không mã hóa gì, nên khóa đi dưới dạng văn bản thuần; các nền tảng ưa RTMPS hơn, tức cùng thứ đó chạy qua TLS. Máy chủ kiểm tra khóa và trả lời NetStream.Publish.Start.","The stream key":"Khóa stream","None (RTMPS adds TLS)":"Không (RTMPS thêm TLS)","on stream 1":"trên stream 1","stream key, live":"khóa stream, live","Video and Sound":"Hình và Tiếng","Metadata, settings, then frames":"Siêu dữ liệu, thiết lập, rồi khung hình","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS mô tả buổi phát: 1920×1080 với 30 khung hình mỗi giây, video H.264, âm thanh AAC. Nó gửi thiết lập cho bộ giải mã, rồi một khung hình chính khoảng 30 KB cắt thành chunk 4.096 byte. Sau đó khung hình tới liên tục trên cùng kết nối TCP.","AAC, 48 kHz stereo":"AAC, 48 kHz stereo","30 KB in 8 chunks":"30 KB trong 8 chunk",METADATA:"SIÊU DỮ LIỆU","H.264 + AAC settings":"thiết lập H.264 + AAC","KEY FRAME":"KHUNG HÌNH CHÍNH","8 chunks":"8 chunk","Stop Streaming":"Dừng Phát","FCUnpublish and deleteStream":"FCUnpublish và deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Khi streamer bấm Dừng phát, OBS gửi FCUnpublish và deleteStream cho stream 1. Máy chủ trả lời NetStream.Unpublish.Success và kết thúc buổi phát cho người xem. Sau đó OBS đóng kết nối TCP.","C0: version":"C0: phiên bản","RTMP version 3, the only one in use.":"RTMP phiên bản 3, bản duy nhất đang dùng.",Time:"Thời gian","A timestamp; zero is allowed.":"Một dấu thời gian; cho phép bằng 0.",Zero:"Số 0","Random data":"Dữ liệu ngẫu nhiên","Random bytes the server must send back.":"Các byte ngẫu nhiên máy chủ phải gửi lại.","S0: version":"S0: phiên bản","Random bytes the client must send back.":"Các byte ngẫu nhiên máy khách phải gửi lại.","1,536 bytes: C1 back":"1.536 byte: gửi lại C1","The timestamp from the block it echoes.":"Dấu thời gian từ khối mà nó gửi lại.","Time read":"Thời điểm đọc","C1’s random bytes, sent back unchanged.":"Các byte ngẫu nhiên của C1, gửi lại nguyên vẹn.","1,536 bytes: S1 back":"1.536 byte: gửi lại S1","S1’s random bytes, sent back unchanged.":"Các byte ngẫu nhiên của S1, gửi lại nguyên vẹn.","RTMP · 2 messages":"RTMP · 2 thông điệp","First message":"Thông điệp thứ nhất","Chunk header":"Header chunk","type 0, chunk stream 2":"loại 0, chunk stream 2","A full header follows: this chunk starts a message.":"Tiếp theo là một header đầy đủ: chunk này bắt đầu một thông điệp.","Message stream":"Luồng thông điệp","Stream 0: the connection itself. (This number alone is little-endian.)":"Luồng 0: chính kết nối. (Chỉ riêng số này là little-endian.)","Chunk size":"Kích thước chunk","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Từ giờ bên này cắt thông điệp thành chunk tối đa cỡ này (128 cho tới khi nói khác).","Second message":"Thông điệp thứ hai","type 0, chunk stream 3":"loại 0, chunk stream 3","Matches a reply to its request.":"Ghép một phản hồi với yêu cầu của nó.","Command object":"Đối tượng lệnh","object, 5 properties":"đối tượng, 5 thuộc tính","Which app on the server, and the address OBS was given.":"Ứng dụng nào trên máy chủ, và địa chỉ OBS được cho.","End of object":"Hết đối tượng","RTMP · 4 messages":"RTMP · 4 thông điệp","The other side should hear back after every this many bytes it sends.":"Bên kia cần nhận hồi âm sau mỗi lần gửi được chừng ấy byte.","Bandwidth, limit":"Băng thông, giới hạn","5,000,000 bytes, dynamic":"5.000.000 byte, động","How much the sender may have unacknowledged at once.":"Bên gửi được giữ bao nhiêu dữ liệu chưa xác nhận cùng lúc.","Third message":"Thông điệp thứ ba","Fourth message":"Thông điệp thứ tư",Properties:"Thuộc tính","object, 2 properties":"đối tượng, 2 thuộc tính",Information:"Thông tin","object, 4 properties":"đối tượng, 4 thuộc tính","RTMP · 3 messages":"RTMP · 3 thông điệp","Nothing: AMF0 null.":"Không có gì: null của AMF0.","Stream key":"Khóa stream","Which channel this is. It works like a password, and here it travels unencrypted.":"Đây là kênh nào. Nó hoạt động như mật khẩu, và ở đây đi mà không mã hóa.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"Stream mới: video và âm thanh sẽ đi trên đó.","type 0, chunk stream 4":"loại 0, chunk stream 4","Stream 1, the one createStream made.":"Stream 1, cái mà createStream đã tạo.","Publishing type":"Kiểu đăng","Live: not recorded by this request.":"Live: yêu cầu này không ghi lại.","type 0, chunk stream 5":"loại 0, chunk stream 5","object, 3 properties":"đối tượng, 3 thuộc tính",Handler:"Bộ xử lý",Event:"Sự kiện",Metadata:"Siêu dữ liệu","array of 14":"mảng 14 mục","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"ID codec như trong tệp video Flash: 7 là H.264, 10 là AAC.","type 0, chunk stream 6":"loại 0, chunk stream 6","Frame, codec":"Khung hình, codec","0x17 (key frame, H.264)":"0x17 (khung hình chính, H.264)","AVC packet type":"Loại gói AVC","0 (decoder settings)":"0 (thiết lập bộ giải mã)","The sequence header: the settings a decoder needs before the first frame.":"Header chuỗi: các thiết lập bộ giải mã cần trước khung hình đầu tiên.","Composition time":"Thời gian kết hợp","The H.264 profile, level and parameter sets.":"Profile, level và các bộ tham số của H.264.","AAC; the other bits are fixed for AAC.":"AAC; các bit còn lại cố định với AAC.","AAC packet type":"Loại gói AAC","Sample rate and channels, for the decoder.":"Tần số lấy mẫu và số kênh, cho bộ giải mã.","1 (video)":"1 (video)","Compressed picture data.":"Dữ liệu hình ảnh đã nén.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Khung hình chính: một bức hình trọn vẹn. Cứ 4.096 byte lại có một header chunk 1 byte nối tiếp nó."},g={strings:{...r,...s,...o},patterns:[[/^([\d,]+) bytes$/,"$1 byte"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 byte: report.pdf, byte $2"],[/^(.+) h later$/,"$1 h sau"],[/^(.+) min later$/,"$1 min sau"],[/^(.+) s later$/,"$1 s sau"],[/^(\S+) \(relative\)$/,"$1 (tương đối)"],[/^(\d+) \(ephemeral\)$/,"$1 (tạm thời)"],[/^(\d+) TCP segments$/,"$1 đoạn TCP"],[/^(\d+) segments$/,"$1 đoạn"],[/^(.*), (\d+) segments$/,"$1, $2 đoạn"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,"TLS 1.3 · $1 bản ghi · byte $2 trên $3"],[/^TLS 1\.3 · (\d+) records?$/,"TLS 1.3 · $1 bản ghi"],[/^Ethernet padding · (\d+) bytes$/,"Phần đệm Ethernet · $1 byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 byte 0, cho đủ mức tối thiểu 300 byte"],[/^(\d+) zero bytes$/,"$1 byte 0"],[/^(\d+) random bytes$/,"$1 byte ngẫu nhiên"],[/^Seen as it leaves (.+)$/,"Như khi rời $1"],[/^Option (\d+)$/,"Tùy chọn $1"],[/^value (\d+), echo (\d+)$/,"giá trị $1, echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 byte, cộng $1 byte tùy chọn."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows bắt đầu từ $1. Ở đây cố ý đặt là $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(h,e,t)=>t==="1"?`Bắt đầu từ ${e}; router trên đường trừ đi 1.`:`Bắt đầu từ ${e}; mỗi router trong ${t} router trên đường trừ đi 1.`],[/^all (\d+) bytes of it$/,"toàn bộ $1 byte"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Gói gây ra việc này, đúng như thiết bị báo lỗi đã nhận (TTL $1), để bên gửi biết đó là gói nào."],[/^Port (\d+), TLS from the start$/,"Cổng $1, TLS ngay từ đầu"],[/^(\d+), TLS from the start$/,"$1, TLS ngay từ đầu"],[/^type 79, (\d+) bytes$/,"loại 79, $1 byte"],[/^(\d+) of (\d+) bytes$/,"$1 trên $2 byte"],[/^(\d+) more bytes$/,"thêm $1 byte"],[/^offset (\d+), (\d+) bytes$/,"vị trí $1, $2 byte"],[/^offset 0, (\d+) bytes \(all of it\)$/,"vị trí 0, $1 byte (toàn bộ)"],[/^record, (\d+) bytes$/,"bản ghi, $1 byte"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · thông điệp $1/4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(h,e,t,i)=>{const n=i==="request"?"yêu cầu":"phản hồi";return e?`${e}${n} ${t}`:`${n[0].toUpperCase()}${n.slice(1)} ${t}`}],[/^(\d+) registers$/,"$1 thanh ghi"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, giọng nói"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 byte)'],[/^(masked|not masked), (\d+) bytes?$/,(h,e,t)=>`${e==="masked"?"có mặt nạ":"không mặt nạ"}, ${t} byte`],[/^(\d+) \(disguised\)$/,"$1 (đã che)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 byte"],[/^0 \(none\), (\d+) bytes$/,"0 (không có), $1 byte"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), loại $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (thanh ghi $2)"],[/^yes, AS (\d+)$/,"có, AS $1"],[/^id 2, (\d+) bytes$/,"id 2, $1 byte"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, như đã thống nhất trong SDP)"]],post:a};export{g as default};
